/* 平成29年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h29.committeeSessions.push(...[{"id":"h29-20170306-3","meetingId":"h29-c-budget","date":"2017年3月6日","dateIso":"2017-03-06","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時１８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を183件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"新妻副委員長","kind":"質問・要望","question":"会派におかれましては、１人当たりの質問時間は、答弁時間も含めて、１０分、１５分、２０分のいずれかとし、会派で割り振ることとしております。なお、無所属の委員の質問時間は、答弁時間も含めて、１日につき１０分となります。終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"質問","question":"職員給与について全体的なところをお聞きしたいと思います。前年だと７,５００万円ぐらい増えていた状況の中で、この流れについてお聞きしたいと思います。これは私この前、本会議の中でも質問させていただきまして、そのときは健康面ということでお聞きしたのですけれども、実際、健康面というよりも、この職員の中で平均するとどのぐらいの残業になっているのか、その辺を含めて教えてください。","respondent":"黒田税務課長、中山障害者福祉課長、米田人事課長","answer":"今後の考え方ですが、国の予算審議の中でも、都市部の住民税が減しているということは活発に議論されておりまして、国のほうでも。中身としてですが、児童発達支援につきましては、未就学のお子さんの療育の場、そして障害児通所支援、今回、９,０００万円ほど増額していますが。近年横ばいであったものが少し上昇に転じているというような感想も持っておりまして、こちらについては、ご指摘のありました職員の健康管理の面からも。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ですから、平均すると０.５かもしれないですけれども、一部の方に負担がかかってしまっているのかなというふうに感じるところです。国の働き方改革とかと様々な話も出ていますので、殊に残業の問題は今、世の中で騒がれている中で、やはり品川区としてもその辺は十分対応しているのだということが言えるような形をとっておいていただきたいという、その辺、もう１回お答えをお願いできますでしょうか。","respondent":"中山障害者福祉課長、米田人事課長","answer":"まだまだ事業所ができてくるような状況もありますし、対象の子どもは、実は今、放課後等デイを利用されている子どもは２６９名いらっしゃるのですが、このほかにも対象になる子どもがいらっしゃるということでは。この辺につきましては、所属の中で、あるいは部全体の中で平準化していただくということでの取組みは行っておりまして、毎年度、四半期ごとに超勤時数、細かいものもお示しするとともに。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"通所に関しては、これからも必要に応じてやっていっていただきたいのと、対象の方の要望に応えるようによろしくお願いします。区長の施政方針の中にあったのですけれども、転入者は年間３,０００人以上、この３年間で１万人以上の転入が入っているので納税義務者は増えているのですけれども、高齢者が出ていくことと、若年の方が入ってきているのか、そこら辺のところをどう捉えているのかを教えてください。","respondent":"黒田税務課長","answer":"納税義務者における年齢のところですが、７０歳以上の方でありましても、納税義務者につきましては平成２７年と比較すると、やや増、６０歳台でも増ということでありますので、平成２８年度のところにおきましては、納税義務者については、この年代についても、やや増加傾向です。","id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。逆に、新しく入ってきた方、今度、税務面だけではなくて、１万人以上の方が品川に入ってくる、その新しい方たちと今まで品川に住んでいる方との連携、つながりについては区としてどういうふうに考えていくのか。その１万人ぐらいの方のニーズをどのように捉えているかということについてお答えをいただきたいと思います。","respondent":"柏原企画調整課長","answer":"特に最近は大型のマンションが建設されたりということで、新しく入ってくる方が多くなっている状況です。そういった中で、今まで住んでいる方々との地域間での連携といいますか、これをどう捉えるかというのは、１つ課題だというふうに捉えております。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"意見","question":"やはり最近、大型マンションが非常に増えてきている中で、町会の関係の方と連携がどこまで密にとれるか、うまくいっているところもあると思います。それは地元の中でやらなければいけないのかもしれないのですけれども、区として地域に対して様々なつながりをつくっていく中で、新しい方にそこに入っていただけるためにどのように考えていくのか、その点をもう１回、お答えをお願いします。","respondent":"柏原企画調整課長","answer":"１つの事例で申し上げますと、平成２９年度予算にはなるのですけれども、勝島地区であったり、それから八潮地区、こういったところのまちづくりをどういうふうにしていくのだという考え方について。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そういう形で区として立ち上げていっていただきたいと同時に、１つの町会で大変な人数の多い町会も出てきています。そこでは、また新たにどんどんマンションが建っていく中、大変な苦労もあると思いますので、その辺も区としてご協力していただければ幸いだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"つる委員","kind":"質問","question":"これは一視点からの検証なので、あらゆる角度から様々な研究者によってさらに深めてもらいたいというご本人の意向もありますけれども、相当インパクトのある指摘かなと思いながら、そういう視点も含めて質問させていただければと思うのですが、まず先ほど、出産・子育て応援事業の更正減額については、理由をお聞きしまして、育児パッケージの契約落差ということですけれども、まずこの予算の中身。","respondent":"太田品川保健センター所長","answer":"全体の予算の中身としましては、人件費や一般需要費としてチラシ等の印刷代等も含まれております。それに主なものとしては、カタログギフト代が含まれております。","id":"exchange-008"},{"speaker":"つる委員","kind":"質問","question":"平成２７年度の１１月から始められて、そのときは５カ月で、事務事業概要を見ると、その数字とかが出ているのですが、丸々１年間の本格実施という中で、今まさに実施している平成２８年度において、どのぐらいの対応なのかということを改めて伺っていきたいと思うのですが、その前に、まずそもそも論ですが、ネウボラネットワーク、この場合は妊娠期となると思うのですが。","respondent":"太田品川保健センター所長","answer":"妊娠期の方から就学前の子どもをもつ全てのご家庭ということになります。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"そうしたことも後に含めて確認させていただきたいと思うのですが、平成２８年度の６月からは、出産されて１カ月後までに電話して様々状況を確認するということもやられていると伺っています。そうした中で、この出産・子育て応援事業は、妊婦全員が対象ということで、今回されていると思うのですが、まず、全員なので１００％だと思うのですけれども、その上で改めて、何％の見込みがあるか教えてください。","respondent":"太田品川保健センター所長","answer":"１月末の妊娠届出に対しては、大体７５％の面談率となっています。","id":"exchange-010"},{"speaker":"つる委員","kind":"確認","question":"１月末現在で見ると７５％だということですね。当然、ご家庭の状況によって、会える会えないはあると思うのですが、もう１回確認ですけれども、どのあたりまでをしっかりと目標にして取り組まれているか教えてください。","respondent":"太田品川保健センター所長","answer":"そういう自治体につきましても、区役所の中で面接ができるような状況ということも伺っておりますので、３保健センターは区役所の中に１つも入っておりませんので、その中で７５％ぐらいの面談率を上げられれば、出産した方につきましては。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"いずれにしてもこれは、平成２８年度３月に全て終わって、また今年の決算等でしっかりと確認をさせていただきたいと思うのですが、本当に母子、それから先ほどネウボラの対象としてありました家族全体の健康、そして安心の子育て、育児環境を整えていくためには、相談体制のより一層の充実が必要かと思います。利用者の声については、ホームページをネットで確認させていただきました。","respondent":"太田品川保健センター所長","answer":"宿泊型につきましては、２月末現在で、ＮＴＴが１０件、聖路加が１件、東芝病院が２件、昭和大学が２件ということになっております。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問","question":"合計すると１５件でしょうか。１０件、１件、２件、２件だったと思います。","respondent":"太田品川保健センター所長","answer":"失礼いたしました。東芝病院が３件で、１６件でした。","id":"exchange-013"},{"speaker":"つる委員","kind":"確認","question":"過去の質疑などを見ると、初産ではない方、事務事業概要を見ると、初産後の母親と生後６０日未満の乳児で授乳や育児に不安がありとなっているのですが、ただ、区民の方に配られるチラシの中には、そういうものも含めて、結局、初産の方となっているのですが、このあたりの確認と、品川区内で初産の方の人数が、平成２５年から平成２８年ぐらいの年度でもしわかれば教えてください。","respondent":"太田品川保健センター所長","answer":"初産にしたということにつきましては、産後鬱のＥＰＤＳが高値になった方のうち、初産で里帰りをしないという方がほとんどで、８割を占めておりましたため、この事業につきましては、家族の支援が得られないという方で、かつ初産ということにしております。","id":"exchange-014"},{"speaker":"つる委員","kind":"質問","question":"そういった部分だとか、あとは申込書も見ましたけれども、ご家族等から十分な支援が受けられないとあって項目が３つぐらい、チェックマークがあったりするのですが、それをどう正確に把握していくかというところと、本人申告による性善説であるところ。ですので、対象者の要件の緩和等の検討も必要だと思いますが、このあたりはいかがお考えでしょうか。","respondent":"太田品川保健センター所長","answer":"様々条件が厳しいというご指摘は、今後、検討しますが、まずは自助、共助、公助ということで、ご家庭で手伝ってくださる方がいる場合には、ご家庭での支援をやっていただくというのが順序ではないかと考えています。","id":"exchange-015"},{"speaker":"つる委員","kind":"質問・要望","question":"予定していた他の質問は別の款でやりますが、またこのことについても他の款でしっかりと進めていきたいと思います。いずれにしても、拡充、充実、安心の子育てができる品川区ということをしっかりとこれからも構築していただきたいということで、これからも応援していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"私からは、３８ページ、国庫支出金、４２ページ、都支出金に関わって、最終補正ですので、今年４月の認可保育園待機児ゼロが実現しない問題を伺いたいと思います。国や都からの支出金について、そもそも公設公営の区立認可保育園の建設と運営に使える支出金は、国、そして東京都に、項目としてあるのかどうか伺いたいと思います。","respondent":"吉田保育施設調整担当課長、秋山財政課長","answer":"区立保育園に対する建設、運営の補助金ということですけれども、これは公設の保育園の建設および運営に対する補助金はございません。公設公営の保育園への国の補助は、基本的にはございませんので、どちらに入っているということもございません。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"いずれにしてもないということがわかりました。文教委員会の議事録を見ていましたら、平成１３年の閣議決定で、今後の保育園運営は民設民営を基本として、その後、国庫負担金はゼロ、東京都もゼロと、そういう仕組みだということだと思います。公設公営の認可園を品川区は財政負担だと主張しますけれども、ならば、なぜ国や都に建設や運営費に係る支出金も求めないのか、その理由を伺いたいと思います。","respondent":"秋山財政課長","answer":"一般的には、国からは地方交付税というところで措置をされているというふうに考えておりますので、その中で一般財源として各自治体が使っているというところで、特別区とはちょっと事情が違うのかなというふうに思います。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺ったのは、なぜ国や都に建設や運営に係る支出金を求めないのかと伺ったので、そこを伺いたいと思います。つまり、公設公営の認可保育園を財政負担だと言って、民営化を進めていったり、保護者に保育園保育料の値上げを求めたり、保護者には求めますけれども、国や都にはなぜ求めないのか理由を伺いたいと思います。","respondent":"秋山財政課長","answer":"特別区から全国市長会等の要望の中に、そういう子育てに対する財政支援は要望はしておりますので、全くそういうことをしていないということではないと考えています。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の子育てに関する中で、建設費と運営費の項目は入っているのですか、そこも伺いたいと思います。結局、親に求めるように国や都に対してしっかりとした財政負担を私は求めていくべきだと思いますので、この点も改めて伺いたいと思います。最終補正ですので、４月入園の待機児ゼロというこの問題についても伺いたいと思いますけれども、そもそも区長の公約ですから、とても大きな課題だと私は思っております。","respondent":"秋山財政課長、大澤待機児童対策担当課長","answer":"国や都への要望ですけれども、子育てを支援するという国の政策、東京都の政策の中に、大きく区分けをして、区としても要望はしています。平成２９年度の待機児童数につきまして、まだ出ていない状況ですので、待機児ゼロがいつ実現するのかということに関しましては、今お答えできる状況ではございませんけれども。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"任期中に実現するのかとずばり聞いたので、そこのお答えを伺いたかったのですけれども、できないということだったのでしょうか。人口の一極集中となる原因を自らつくって、今になって予想しがたかったということは、区のまちづくりの失敗だということでしょうか、この点を伺います。なぜ働きたいという女性が増えていること、この思いを理解することができなかったのか、理由も伺いたいと思います。","respondent":"稲田都市開発課長、大澤待機児童対策担当課長","answer":"各地区の権利者の方が勉強会等を重ねながら、何年もかけて、その地区にふさわしいまちづくりをやるという中で、子育て支援施設等もつくっていくというところで、区とも協議しながら、現在はやっているです。待機児童がゼロになるかどうかですけれども、平成３０年度のゼロを目指して努力は続けてまいります。それから改善策ですけれども、認可保育園等の開設につきましては、基本的に子ども・子育て計画に沿って進めていくものです。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"端的に言います。まちづくりのほうですけれども、様々考えながらやっていっているのだと、そう説明するならば、なぜ人口一極集中を招いたことが予想しがたいことだったという答弁になるのか、そこを伺いたいと思います。そもそも待機児が解消されない理由について、必要な保育園が足りないことだということを区は原因と捉えているのか伺いたいと思います。","respondent":"齋藤子ども未来部長","answer":"品川区は大変な人気区になっております。濱野区政になるまでは、人口３０万人を切るのではないか、こういった懸念をされていたところ、今、３８万３,０００人です。保育園の待機児が多い区の特徴は３つあります。１つ目は、女性の就労の機会があるところです。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれ質問したのでお答えいただきたいと思うのですけれども、原因と対策が間違っていると思うのです。つまり、人気区だから対策が追いつかないのであれば、では、人気をなくすのですか。それは区民は望んでいないと思うのです。区長の公約も２年も先延ばしです。このことへの反省がなぜないのか、その点についても伺いたいと思います。","respondent":"齋藤子ども未来部長","answer":"区政７０周年を迎えまして、品川区がこれほど隆盛を誇っておりますのも、区だけではなくて、区議会との両輪となって待機児童対策を進めてきたからだと考えております。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"あまりにも私の質問に対して誠実な答弁ではないと、その点だけは指摘したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"松永委員","kind":"質問","question":"私からは、４１ページ、４７ページ、７５ページの公園・児童遊園整備について、４３ページのいじめ防止対策費、８１ページの特色ある教育活動費について、時間がありましたら、７３ページの下水道管改修事業更正減額について伺いたいと思います。あわせて、４７ページの都補助金の公園・児童遊園整備についてですが、まず、この６００万円減になっている理由、内容についてお伺いします。","respondent":"溝口公園課長","answer":"続きまして、スポーツ施設整備費の６００万円の減額ですが、これは八潮北公園の整備にあわせて都の補助金をいただくという形で計画しておりましたが、スケートボードの整備をあわせて行うという観点から、次年度に工事を送るため。","id":"exchange-025"},{"speaker":"松永委員","kind":"質問","question":"わかりました。この７,３５０万円には、そういう意味があったということで初めてお伺いしました。その中でトイレについてなのですけれども、工事が年度内にできなかったということだったと思ったのですが、現在、しながわ区民公園のトイレについて、どういう形になっているのかお伺いしたいと思います。","respondent":"溝口公園課長","answer":"しながわ区民公園の整備につきましては、当初、トイレの整備も今年度中に２カ所ほど終わらせる予定でおりましたが、契約の不調等、また保守の見直し、そういったところで全体計画を見直す中で、次年度、平成２９年度に予算計上させていただいて整備を計画しているものです。","id":"exchange-026"},{"speaker":"松永委員","kind":"質問","question":"歳出の７５ページの公園・児童遊園整備について伺います。しながわ区民公園改修工事の勝島の海再整備基本計画・設計委託の８５０万円減、天王洲公園の改修設計委託も同じく７００万円減、また管理棟改築実施設計委託でも１,６００万円の減となっておりますけれども、当初予算より全体的に減少している原因について伺いたいと思います。","respondent":"溝口公園課長","answer":"今回、公園整備事業費に関する減です。これにつきましては、全て設計委託を行っているものでございまして、大きい理由といたしましては、契約差金が一番大きな減額理由となっているものです。","id":"exchange-027"},{"speaker":"松永委員","kind":"質問","question":"その設計委託された会社は全て同じところだったのか、それについて少し伺いたいと思います。次に、４３ページの国庫補助金のいじめ防止対策費について伺います。そうした中、補正予算の国庫補助金では、財源更正によって２１７万２,０００円減少しておりますけれども、その理由について伺いたいと思います。","respondent":"溝口公園課長、村尾教育総合支援センター長","answer":"今回の委託です。それぞれ違う業者が今年度末のまとめに向けて事業を進めているという形になっているものです。以上が減額の理由です。区の取組み等について、この減額によって特に大きな変化はというご質問でしたが、従来どおり今回、また来年度も含めて、いじめ防止対策を含めて、ＨＥＡＲＴＳの取組みを進めてまいります。","id":"exchange-028"},{"speaker":"松永委員","kind":"質問","question":"しっかりといじめ防止に取り組んでいただければと思います。この事業は、東京都教育委員会が進めている事業で、日本の伝統文化に関する取組みを行って、子どもたちの理解を深め、日本人として誇りを持ってもらい、また日本のよさを発信する能力や態度を育成する教育であると伺っております。そこで、１５０万円減について、なぜ東京都はこの事業に対して減額を行ったのか伺いたいと思います。","respondent":"熊谷指導課長","answer":"平成２８年度当初予算では、前年度同規模、５校で１校当たり５０万円として予算計上を行っておりましたけれども、東京都教育委員会が、オリンピック・パラリンピック教育の中で伝統文化を大きな柱としておりますので。","id":"exchange-029"},{"speaker":"松永委員","kind":"質問","question":"委託事業ではあるのですけれども、本区としてどのように進めていくのか。その減額した分は、何か対策を行うのか、先ほどと同じような質問になるのですけれども、影響は出てこないのか、もう一度お願いいたします。","respondent":"熊谷指導課長","answer":"反対にオリンピック・パラリンピック教育とあわせて充実したというふうに考えてあります。","id":"exchange-030"},{"speaker":"松永委員","kind":"質問・要望","question":"東京オリンピック・パラリンピックも控えているので、ぜひ日本の良さを、また品川の良さを今後も発信できるよう力を入れていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"それと今回、一般会計の補正予算なのですけれども、トータルで４億７,６００万円余の減額補正となっていますが、私は当初予算の精度がなかなか高いと思っているのですけれども、トータルでこの金額というのは、ご自分たちではどういうふうに評価しているのかお伺いします。","respondent":"秋山財政課長","answer":"補正予算のそもそもの意義というか、位置づけというご質問ですけれども、補正予算は、今回ご説明させていただきましたように、当初予算を立てて執行しているわけですけれども、最終年度末に当たりまして、国庫支出金等の特定財源に連動して追加になったものですとか。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"財政課長、そうは言っても、当初予算を見て、トータルでは４億７,６００万円という形なのですけれども、中身を見ると、すごい増額、減額が激しいのです。今回の補正で増額分で幾らか、減額分で幾らか、また、それはそれぞれ何％に当たるのかお伺いします。","respondent":"秋山財政課長","answer":"例えばやむを得ず変更するということで大きなものが、補助１６３号線ですとか、ハード系のものは国との予算の関係で減になっているものが多いです。増のものでは、例えば区立保育園の経費であるとか、認証保育園の運営費です。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問","question":"財政課長、もうちょっと数字的にも、パッパ出てくると私は思ったのですけれども、補正の考え方です。ですから、そういう意味においても、精度の高い当初予算としていかないといけないと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"秋山財政課長","answer":"精度の高い予算というのは、もちろんそれは私どももやらなければいけないということでやっているところです。補正予算をするということは、それなりの理由があってやっているというものでございまして、補正予算を立てたから必ずやるのだというようなことは考えておりません。","id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"もう１つは、障害児の通所支援事業については、難しいという答弁だったような気がするのですけれども、障害者福祉課はどういうお考えであるかお伺いします。","respondent":"佐藤保育課長、中山障害者福祉課長","answer":"医療的ケア児の受け入れに関してですが、法改正の趣旨や医療的ケア児の増加等から、受け入れに向けた課題の検討を行ってまいります。医療の必要なお子さんの療育の件ですが、現在では、城南分園のほうで行っております。これをこの４月から新たに１つ事業所をつくって、医療の必要な子どもの療育ということでは障害者のほうで対応していく予定です。","id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"障害者福祉課長、それは前向きな答弁ととっていいのでしょうか、後ろ向きな答弁としてとっていいのでしょうか。これが前向きであるならば、本会議の答弁とは違うと思うのですけれども、その辺について、はっきり答弁していただけますか。","respondent":"中山障害者福祉課長","answer":"働く親に対する支援というのは、保育課のほうの支援になってくるというふうに考えているところです。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"私は、前向きととりましたので、ぜひ支援してください。よろしくお願いします。次が、８１ページの義務教育施設整備基金積立金追加分なのですけれども、これは３０億円積み立てているのですよね。この結果的に２００億円になるのですけれども、この目標額は幾らなのでしょうか。その基金の積立額の目標と、これから改築が必要な学校の改築費の総額を、大まかでいいので教えてください。","respondent":"秋山財政課長、篠田学校計画担当課長","answer":"それなりに金額がかかってきまして、１０年程度を見たときに、年間の３０億円程度の積立てをしていかないと、学校の改築に対する費用が、具体的に言うと、基金が下回ってしまうので。学校の改築に関しましては、規模ですとか、状況によってかなり差がありますので、現状では、直近で大体１校当たり４０億円前後の金額がかかってまいりますことから。","id":"exchange-037"},{"speaker":"藤原委員","kind":"質問","question":"積立額の目標と、これから改築が必要な学校の改築費の総額を教えてくださいと言ったのに、答えていないですよね。意図的に答えていないならあれなのですけれども、これ、わからないのだったら、総額もわかっていないのに３０億円を積み立てているのですか。","respondent":"秋山財政課長","answer":"ただ、目標額につきましては、積みつつ一方で使っていきますので、使わなければ目標３００億円まで積めばあとは何もしないでいいということですけれども、使いながら積み立てていきますので、その３００億円というのは目標ですけれども。","id":"exchange-038"},{"speaker":"藤原委員","kind":"質問","question":"財政課長、またこれは伺います。次が、どうしても伺わないとならないことで、ページ数だと７５ページ、天王洲公園改修工事なのですけれども、今年度は設計段階なのでしょうか。これは改修の内容はどういうものか。オリンピック・パラリンピックに向けたものがあるかどうかお伺いします。","respondent":"溝口公園課長","answer":"今回、減額補正したものにつきましては、来年度以降のＡ・Ｂ面の人工芝の張替え工事、また管理棟の建替え、そういったものをやっていくものです。オリンピック・パラリンピックの情勢、今後のスポーツ利用促進という観点もあわせまして、改修工事を進めているものです。","id":"exchange-039"},{"speaker":"藤原委員","kind":"意見","question":"オリンピック・パラリンピック準備課長はいらっしゃらないですよね。その辺、どういう形で所管の課と、いらっしゃいますか。オリンピック・パラリンピックの担当課長として、この天王洲の公園、どういう思いがあったか、時間、最後までいいので、お願いします。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"天王洲公園につきましては、ブラインドサッカーの国際大会を目指しているところでございまして、そういった意味で、オリンピック・パラリンピックが終わった後も天王洲公園を活用するというふうに考えているところです。","id":"exchange-040"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"私は、７３ページ、橋梁費、橋梁長寿命化修繕、そして７７ページ、防災街区整備事業の中延二丁目旧同潤会地区について質問させていただきたいと思います。初めに、橋梁長寿命化修繕計画、この内容についてお知らせいただければと思います。","respondent":"多並道路課長","answer":"長寿命化計画は、平成２２年に、今後の橋梁等の管理を長寿命化させるために、維持管理により長持ちさせたいという観点で計画を立てたものです。平成２７年にそれを改定いたしまして、現在、その計画に基づき、計画的に修繕工事を行い、平成２８年度はその内容で行ったものです。","id":"exchange-041"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今現在、勝島橋、昨年、平成２８年９月から、予定ですと３月３１日までとなっておりますけれども、その辺の今現在の状況と、この工事が終わった後、橋梁名の表示など何か示すような、新しくなったことによって何か示されるのかどうかお知らせいただきたいと思います。","respondent":"多並道路課長","answer":"橋梁名等の表示につきましては、今後、水辺環境の舟運関係で様々事業の調整をしていただいているところもありますので、そこら辺の関係で、様々な実態を聞きながら、より良い関係に進めていきたいと思います。","id":"exchange-042"},{"speaker":"高橋（伸）委員","kind":"質問","question":"それとあと、品川区は、おそらく５０橋あると思うのですけれども、おっしゃったように、これからオリンピック・パラリンピックに向けて、水辺等の環境整備をやっていかなければいけないと思うのですけれども、他の橋を含めて、オリンピック・パラリンピックに向けた機運醸成のため区としてのペイントというか、キャッチフレーズを橋に掲げてやるという感覚でよろしいのでしょうか。","respondent":"多並道路課長","answer":"今後の全体的につきましては、舟運事業全体の進め方のご意見をお伺いしながら、全体的には、今後、より良い環境づくりは検討していきたいと思っているところです。","id":"exchange-043"},{"speaker":"高橋（伸）委員","kind":"質問","question":"この勝島橋のところの競馬場通りなのですけれども、これからホッケー競技が開催されるという中で、今現在、無電柱化を進めております。この橋にかかる歩道も、いずれは整備をしていくという考えでよろしいでしょうか、教えてください。","respondent":"多並道路課長","answer":"競馬場通りにつきましては、現在、電線共同溝の工事を今年度末までということで、工事完了予定です。その後、来年度以降、平成３１年度の初頭までに、道路整備工事、最終的に整備工事を行って終わらせるという段取りで進めているところです。","id":"exchange-044"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、７７ページの防災街区整備事業の中延二丁目旧同潤会地区について、お伺いをさせてもらいたいと思います。建設委員会でも様々質疑を私もさせていただきましたけれども、この解体工事を本年の２月から進めておりますけれども、今現在、順調に進んでいるのか、その進捗状況をお知らせいただきたいと思います。","respondent":"寺嶋木密整備推進課長","answer":"本年２月より予定どおり解体工事が進んでおります。幾つかのブロックに分けて、最終的には５月末までに解体工事を終了するということで、予定どおり進んでいるというように報告を受けております。","id":"exchange-045"},{"speaker":"高橋（伸）委員","kind":"質問","question":"それで今、解体のヤードといいますか、入口のところはちょうど中延小学校の前のところで作業車が出入りしていると思うのですけれども、時間を見ると、８時から１７時となっているのですが、この８時というのは、当然、通学のため通れないと思うのですけれども、実際には何時から始まっているのですか。","respondent":"寺嶋木密整備推進課長","answer":"お知らせしている時間は、準備や後片づけも含めた時間なので、通学時間を避けて実際には工事をするということで、事前の説明も受けておりますし、実際にそのように進めるということで事業組合のほうから報告を受けているところです。","id":"exchange-046"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"わかりました。工事期間中に荏原消防署および荏原消防団による除却を利用しての消防訓練を予定しているということで、第１回目が３月１２日（日）にあると思うのですけれども、詳細について、どういった内容なのか教えていただきたいと思います。","respondent":"寺嶋木密整備推進課長","answer":"４月にもう一度、まだ正確な日時は決定はしていないのですけれども、そちらのほうで実際に、例えば玄関扉の破壊とか窓枠の破壊、そういったことも含めて、こういった実地というか。","id":"exchange-047"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ここの解体の整備をやる中で、特に木造密集地域の中で、それぞれ皆さん、ご意見があって、今現在、整備をされているという中で、区としても様々大変なご苦労があったと思います。これから、今現在、近隣地区の解体工事に伴うことで、何か要望というか、クレームというか、そういうものがあるのかお知らせいただければと思います。","respondent":"寺嶋木密整備推進課長","answer":"紛争予防条例による説明会は２回、解体工事の説明会は１回、説明会をしているということで、その中でやはり高さの問題であるとか、日影の問題、それからアスベストの問題、それからあとネズミの問題という形で心配だという声が出たというふうに聞いておりまして。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは、４０ページと８０ページ、国庫補助金で、学校施設整備費、また７４ページ、土木費、都市計画費、公園新設改良費、どちらもトイレの改修について、今日は１本で確認をさせていただきたいと思います。今日は主に、トイレの洋式化を含めた改善について確認させていただきたいと思います。東京都の来年度予算に、小池都知事が前年度比約５倍となる８３億円の予算をつけたからです。","respondent":"品川庶務課長","answer":"学校予算で、今回、まず補正のほうですけれども、当初、申請を出していたのですが、これは国の財源の関係で、予算が不採択になってしまったという表記になってあります。学校のトイレですが、今年度につきましては４校、整備をしています。","id":"exchange-049"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ここで言っておかなければいけないのは、平成２４年決算特別委員会の６日目、平成２６年度予算特別委員会の７日目、平成２７年度予算特別委員会の７日目で、それぞれ学校トイレの洋式化の状況を確認し、洋式化すべきと我が会派としてもずっと言ってまいりました。品川区議会においても５年前からずっと言ってきたということであります。この調査のとおりで現状もいいのかどうか伺います。","respondent":"品川庶務課長","answer":"それから洋式と和式の比率ですが、今年度、改修工事を全て終わったという想定での段階で、和式については３６.６％、洋式については６３.４％の比率となっています。ですので、東京都の平均等よりも上回っているような状況です。","id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ここからが私、今回この質問でよく伺いたいのですが、同じ調査の結果には、各自治体ごとに今後の、主に新築・改築の場合のトイレ整備に対する教育委員会の方針という項目があって、各自治体が選択肢を1)から5)を選ぶようになっています。今回、９０％ということでお答えになっているのですけれども、品川区としてはどういうご見解なのか、そこを確認をさせていただきたいと思います。","respondent":"品川庶務課長","answer":"ただ、比率について、どういう比率でいくかというのは、また今後、状況も見ながら検討はしていきたいと思いますが、現在、改築校での比率を申しますと、８割から９割前後、洋式トイレにしているというような状況です。","id":"exchange-051"},{"speaker":"あくつ委員","kind":"質問","question":"先ほどの私の質問は、各階に１個残すのか、各トイレに１個残すのかというところを、今後の質問もあるものですから、はっきりしたいなというところが１点あるというところです。もしそういうお子さんがいらっしゃるのであれば、例えば学校に幾つかとか、そういう基準を設けるべきではないでしょうか。各階なのか、各トイレなのか、そういうところも含めてもう一度考え方を教えてください。","respondent":"品川庶務課長","answer":"ですので、１階当たり１個という基準ではなく、学校内の中で和式を置いていくというような考え方ですので、学校全体として８割から９割を洋式トイレ、残る１割から２割を和式トイレというような考え方です。","id":"exchange-052"},{"speaker":"あくつ委員","kind":"質問","question":"先ほど、国の補助金がつかなかったという話がありました。これから先、都から８３億円ですか、東京都内で１０万基のトイレがあるのでどこまで補助金か使えるのかわかりませんけれども、そういったものに積極的に手を挙げていくべきだとは思いますが、またもし国の補助、都の補助がおりない場合に、これは区としてもしっかり単費でやっていくのかどうか、そこについてご見解を伺いたいと思います。","respondent":"品川庶務課長","answer":"今後、８割、また９割に向けての考え方というところですが、このトイレ改修、非常に費用がかかります。今年度も、先ほど委員からもお話がありましたけれども、２億円から３億円程度をかけて４校整備しているというような状況です。","id":"exchange-053"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほど申し上げましたけれども、多額の税金を使って改修をするということですので、考え方、先ほどの方針ですけれども、もう少し整理を、時代とともに背景が様々変わってくると思いますので、そこは整理をしていただいて、かたくなに１個を残すというふうに、私はこの５年間ずっと聞いてきたわけですけれども、残すにしても、考え方がやはり１つあると思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"田中委員","kind":"質問","question":"６５ページの児童福祉費の職員給与費２億５,６５０万円の減額について伺います。待機児童の問題から、職員の人数確保はとても重要だと考えています。減額の理由は育休と伺いましたが、その人数と、育休とはどういった範囲なのか、この範囲は１年間のお休みなのか、産前産後のお休みなのか、皆さん、どのように育休をとられているのか伺います。","respondent":"米田人事課長","answer":"保育園運営費の更正減額ですが、こちらについては、平成２８年１２月の時点で、育児休業を取っている職員が６２人です。こちらですけれども、産休育休という、いわゆる出産に伴う休暇に引き続き、無給になりますが、育児休業ということで取られている職員の方々です。","id":"exchange-055"},{"speaker":"田中委員","kind":"質問","question":"６２人の職員の補完は、どういう形で補充されたのか伺います。","respondent":"米田人事課長","answer":"年度当初から育休に入られるというようなことがわかっていれば、あらかじめ任期付きの職員の採用ということで、育休に入る段階であてがうというようなことと、あとは派遣職員というような形での補充というようなことで主に行っているものです。","id":"exchange-056"},{"speaker":"田中委員","kind":"意見","question":"はい、わかりました。職員確保に品川区立保育園では、２０１６年度当初予算が、育休代替経費に約４億６,７００万円計上されていますが、一方、私立保育園では、代替職員費助成が約８６０万円です。私立保育園と区立保育園の補助金額の差について、ご説明ください。","respondent":"佐藤保育課長","answer":"私立保育園の運営費に関しましては、公定価格に対して区で約５０％上乗せをして１園当たり約１億４,０００万円の運営費を出しているところです。","id":"exchange-057"},{"speaker":"田中委員","kind":"意見","question":"区立保育園より私立保育園の数のほうが多いので、職員数も多いのかと思います。私立保育園は産休取得率が低いのかと思うのですけれども、私立保育園では産休が取りづらい状況にあり、辞めてしまう方が多いのではないかと不安になっているのですが、区立保育園より私立保育園の代替職員が少ないという事実を区はどのように分析しておられるのか、お願いします。","respondent":"佐藤保育課長","answer":"ただ一方で、人によっては考え方で、一度、仕事を辞めてゆっくり子育てをして、その後、戻ってくるというところも聞いております。いずれにしても、処遇改善等、国、都の補助金等も入れてやっておりますので、そういった中でより良い制度になればいいと考えております。","id":"exchange-058"},{"speaker":"田中委員","kind":"質問","question":"待機児童の状況を考えると、私立保育園はなくてはならない存在です。品川区全体の保育として、子どもたちの保育の質を保つためにも、保育士の補完、処遇待遇は重要だと考えます。私立保育園の保育士に対しても区として積極的に取り組み、この種の補助金の増額の必要性があると考えますが、いかがでしょうか。","respondent":"佐藤保育課長","answer":"法外の補助金に関しましては、基本的な考えは、公定価格と、区から出ている運営費に基づいて運営していただくということになりますので、今のところ法定外の補助金の増額は考えておりません。","id":"exchange-059"},{"speaker":"田中委員","kind":"質問","question":"たしか２億８,０００万円余のキャリアアップ補助金が品川区にも来ているということでした。２０１６年度より増額されているので歓迎しているのですが、区としては、この補助金がどのように活用されるべきだと考えますか、伺います。","respondent":"佐藤保育課長","answer":"東京都の制度でありますキャリアアップ補助金ですが、まず第一に、勤務条件、賃金体系を含め、職員に周知を図ること、そして資質の向上の計画策定、実施が必要になっております。","id":"exchange-060"},{"speaker":"田中委員","kind":"質問・要望","question":"保育士の給料アップが確実に実施されるような仕組みづくりが自治体には求められています。一例ですが、横浜市では、補助金が保育士１人１人の手に渡るように、１人１人の保育士から署名をもらい申請手続きを行うそうです。キャリアアップ補助金が人件費として、保育士の手元に確実にわたるような仕組みが品川区でもできているのかということを伺いたいのですが、いかがでしょうか。","respondent":"佐藤保育課長","answer":"その結果、平成２７年度の反映に関しては、約３万８,０００円という、定例会でもご答弁したような金額が出ております。今後も保育士のほうに処遇改善が適切に行くように、調査と私立保育園長会等で働きかけてまいります。","id":"exchange-061"},{"speaker":"田中委員","kind":"質問","question":"ありがとうございました、了解しました。なければ、預貯金に置いておかれるという理解で大丈夫ですか。はい、ありがとうあります。６２ページ、３款民生費、１項社会福祉費、１目社会福祉総務費、特別会計繰出金更正減額について伺います。過去３年の繰出金額が毎年繰越更正減額されています。昨年も質問しましたが、この特別会計繰出金更正減額の３つの事業会計の減額の理由をご説明ください。","respondent":"高森国保医療年金課長、永尾高齢者福祉課長","answer":"ご質問いただきました国民健康保険事業会計繰出金、後期高齢者医療特別会計繰出金について、ご説明をします。これは消費税が上がる見込みで保険料の率を減額しているものだったのですけれども、結果的に消費税増税が先送りになりまして、それで国と東京都と区で負担をするという制度になっております。","id":"exchange-062"},{"speaker":"田中委員","kind":"質問","question":"申し訳ございません。難しくて、もう少し具体的に、国と東京都の歳入はどこの事業に充てられて増えているのか。当初予算では見込めない理由はどういうところにあるのか教えていただけますか。","respondent":"永尾高齢者福祉課長、高森国保医療年金課長","answer":"国庫・都支出金の返還金については、説明がわかりづらくて申し訳ありません。国保の繰出金が減っている理由ですが、こちらは先ほど申し上げましたように、被保険者数が平成２８年３月現在、８万８,７６７人だったわけですけれども、平成２９年１月末現在では、８万３,９３９人ということで。","id":"exchange-063"},{"speaker":"田中委員","kind":"質問","question":"地域支援事業の繰入金ということでしょうか。そして、毎年７億もの補正がかかる理由がちょっとわからなくて、あと仕組み的に、この時期に国と都からの予算がつくのかということを教えてください。","respondent":"高森国保医療年金課長","answer":"実は、繰出金の中、国保会計から見ますと繰入金という話になるわけですけれども、こちらは法定内の部分と法定外の部分がございまして、法定内の部分につきましては、保険基盤の安定化、いわゆる保険料の軽減をしたものに対して入ってくるもの、また保険者支援分、職員給与費等。","id":"exchange-064"},{"speaker":"田中委員","kind":"質問・要望","question":"毎年７億円もの補正がかかる理由を答えていただきたいというのと、仕組み的にこの時期に国と都からの予算が付くからなのかということを教えていただけたらと思います。","respondent":"秋山財政課長","answer":"補正予算書の１１２ページに、国保医療会計の繰入金があります。ここが今、国保医療年金課長がご説明を差し上げた、繰入金と言っても、その中身は様々あります。それ１つ１つについて増減がありまして、それぞれの説明を今させていただいたと、そういうものです。","id":"exchange-065"},{"speaker":"安藤委員","kind":"質問","question":"私からは、３６ページ、特別区民税、地方消費税でお伺いします。特別区民税は１０億円増えて４１０億円です。それと、当初予算編成時と比べてどうして納税者が増えたと区は分析しているのでしょうか、伺います。同様に、地方消費税についても伺いますが、これが増えた要因は配分割合の増ということでしたが、要するに人口増が原因ということなのでしょうか、伺います。","respondent":"黒田税務課長、秋山財政課長","answer":"特別区民税の納税義務者数の伸びの見込みですが、平成２８年度の当初予算編成時におきましても、平成２８年１月１日の賦課期日現在の人口が伸びるということを予測しまして。地方消費税交付金の増の理由ですけれども、こちらは東京都の補正予算で、今年度、交付の見込みが７.９％増ということで、東京都として、東京都全体の消費税が７.９％増というふうに見込んでいるというものです。","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問","question":"予想より人口の伸びがあるですとか、人口の話も出てまいりましたけれども、午前中でも自治体の人気は人口増で決まるのだという答弁もありまして、呼び込みにかなり価値を見出していらっしゃるのかなという印象がありました。改めて伺いますが、再開発と税収増との関係を区はどのように考えているのでしょうか、伺います。","respondent":"黒田税務課長","answer":"再開発と税収増の関係というお尋ねですが、基本的に仕事をされている方の年代が転入されてくれば、当然収入を得ていらっしゃいますので、税が増えるというような関係にありますので、所得稼得層が増えれば税収が増えるというような関係にあるというふうに認識しているものです。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問","question":"人口を増やした、人口増を誘導したにもかかわらず、３０代、４０代の子育て世代はむしろ転出超過という現状なのですが、なぜなのかと思ってしまうのですけれども、呼び込む以上に、品川では子育てできずに区を離れる世帯が多いということではないのでしょうか、いかがでしょうか。なぜ子育て世代は品川区を離れているのか、どんどん呼び込んでいるにもかかわらず離れていくのか、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"これを比較した際、こちら、先ほど委員がご案内していただいた年齢層のところが、転出が増加になっているというものです。ただし、こういったところが見られる現状から、区としては施策をどのように充実させるかということで、この平成２７年、平成２８年、進めてきたところです。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問","question":"７５ページに、理想の子どもの数を実現するために今後品川区が取り組むべき点はという質問がありまして、そのトップは、５５.７％で、保育施設など子育て支援の施設が充実するとあります。保育園整備があまりに追いついていないというのが子育て世代流出の最大の原因だと私は思いますけれども、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"新年度予算のお話にはなりますけれども、今後も待機児童解消に向けた問題であるとか、そういった問題については、公有地等様々活用しながら、施策の充実をしたいというふうに掲げてきているものですので、こういった人口ビジョン。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問","question":"税収増につながっているということで、人口が増えているということなのですけれども、アンケートで、先ほども紹介しましたけれども、そうした子育て世代が子どもを産むために一番必要だとしている施策に対しては、やはり不十分ではないかと私は伺ったのです。保育園整備が追いついていないということが、子育て世代が離れてしまっているという原因だと思いませんかと伺ったので、もう一度伺いたいと思います。","respondent":"柏原企画調整課長","answer":"そういったところの重点すべきところに予算をかけてやってきているところでございまして、保育園につきましても、これまでも重点課題ということで取り組んできたものです。","id":"exchange-070"},{"speaker":"安藤委員","kind":"質問・要望","question":"さらに先ほども質疑でありましたけれども、国保や介護など各特別会計への一般会計繰入金も軒並み減らしている。私は、黒字、いわゆる繰越金というのは基金に積み増すのではなく、４月に待機児を生まないために緊急対策に使うなど、やはり目の前の喫緊の課題に使うべきだと思うのです、それはいかがでしょうか。そして、結果４６億円にもなった黒字、繰越金、この要因を区は何と考えているのか伺います。","respondent":"秋山財政課長","answer":"そういうこともありまして、今回、最終補正でも取崩しを９３億円というふうに計上しておりますので、最終補正後も必要なときには必要なところには使っておりますし、一方で余裕のある分は積み立てている、そういうものです。","id":"exchange-071"},{"speaker":"安藤委員","kind":"質問","question":"こうしたことで、生まれているのは１,１９０人の子どもが認可保育園を希望しながら入れなかったという事実です。午前中の答弁では、基金は義務教育基金だけでも３００億円が目標という答弁もありました。最終補正が積増しではなくて、１人の待機児も生まないような緊急対策への、予算の活用、それをはじめとした喫緊の住民要求実現のために予算を組むべきだと思いますけれども、いかがでしょうか。","respondent":"秋山財政課長","answer":"待機児童解消関係の推移ですけれども、平成２８年度当初に比べて、今回は１０％以上伸ばしております。金額にして約７４％増という形で金額を積んでおります。このように、品川区としても十分対応をさせていただいているところです。","id":"exchange-072"},{"speaker":"鈴木（博）委員","kind":"質問","question":"第１に、医療管理が必要なく退院許可された産婦が対象だということだとすると、医療機関で実施する意義はどこにあるのでしょうか。最初の３つ、関東病院と東芝病院と昭和大学病院は品川区内の病院なのでわかりますが、なぜそこに聖路加産科クリニック、ここは聖路加病院ではなくて、そのサテライトの助産施設だと思うのですけれども、どのような理由でその聖路加産科クリニックが選ばれているのでしょうか。","respondent":"太田品川保健センター所長","answer":"なぜ聖路加産科クリニックかということなのですが、区内の病院は出産された方のみということですので、それ以外の方の受入れをするということで、ベッド数がかなり多くかつ区民の利用実績があり、ハイリスクも対応してくださるという回答により。","id":"exchange-073"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今の所長のご返答で、あえて医療機関の必要がなくて、助産師が十分確保できる施設で適当に選ばれたのがこの４つだということが理解されました。この４つの施設で利用者の数と受入れのキャパシティーに関してお返事がなかったのですが、まずそこそこ利用者があったとしますと、この事業の中で、例えば区の職員とかネウボラの担当者はどのような形で関わられているのでしょうか。","respondent":"太田品川保健センター所長","answer":"キャパシティーについては、十分に対応可能であるというふうには伺っておりますが、今後、聖路加産科クリニックが助産院ということで、１９床から９床に病床が減らされるという情報が入ってまいりましたので、それでまた利用ができないという状況が増えるようであれば。","id":"exchange-074"},{"speaker":"鈴木（博）委員","kind":"質問","question":"定期接種のほうに行きます。平成２８年、昨年の決算特別委員会で、我が会派の沢田委員が質問した平成２８年３月までに生まれた児が任意接種、４月以後に生まれた児は定期接種、品川区民以外で３月に生まれた児は自費、このような非常に混乱した取扱いになっていることに関して、十分な配慮を要請したと思うのですが、結果として、その後、トラブル等の報告などはあったのでしょうか。２点お願いします。","respondent":"舟木保健予防課長","answer":"定期接種化後の救済措置として、区では任意接種の助成を今年度につきましては継続実施したことで、移行時の対応については特に問題なく、トラブル等の報告はありませんでした。","id":"exchange-075"},{"speaker":"鈴木（博）委員","kind":"質問","question":"水疱瘡ワクチンについてお伺いいたします。水痘ワクチンは平成２６年１０月に定期接種となり２年半が経過しました。過去数年間、水疱瘡は全国レベルで大体年間１００万人患者が発病すると言われておりましたが、この２年間、定期接種をやって以降の水疱瘡の患者の数の推移と、ワクチンの接種率について簡単にお示しください。","respondent":"舟木保健予防課長","answer":"接種率については、細かく把握はしていませんが、区について言えば、平成２６年度は７割くらい、平成２７年度は始まった年で１００％で、今年度につきましても大体９９％前後になるのではないかと考えています。","id":"exchange-076"},{"speaker":"鈴木（博）委員","kind":"意見","question":"定期接種になることによって、Ｂ型肝炎ワクチンも水疱瘡（水痘）ワクチンも接種率が非常に上がって、子どもを守るために非常に有意義だったと非常に感謝しているのですが、Ｂ型肝炎も水疱瘡も良かったです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-077"},{"speaker":"塚本委員","kind":"質問・要望","question":"この減収になった原因は単価というところが大きいのかなというふうには承知しておりますが、一応、回収量などその他の要因等あったのかどうかということと、この売払収入というのは、同額がリサイクル推進費のほうでも減額というか、一般財源からの増で補填されているという状況から見ると、基本的にこの売払収入というのは。","respondent":"小林品川区清掃事務所長","answer":"この収入につきましては、費用に充当すべきところなのですが、申し訳ございませんが、収入を十分確保できなかった関係で、結果的に一般財源をもって同額を経費補填していただきたいと考えております。","id":"exchange-078"},{"speaker":"塚本委員","kind":"意見","question":"今、ご答弁がありましたが回収量から言えば、古紙が前年度比７％減であり、５００万円弱の減収ということで７％減もかなり大きな要因ですが、より大きいのは、アルミ缶とペットボトルの単価が下がったところにあるということで、これは今までが高かったという状況が、むしろこれは特需であって、今ぐらいの価格というのが今後もずっと続くというふうに見ておられるのか。","respondent":"小林品川区清掃事務所長","answer":"一方、影響の大きいペットボトルなのですが、これは国の機関で入札で決まってくるということで、来年度は若干高めの金額が獲得できる想定をしておりまして、現在、底値の２６円４６銭で売却決定されておりますけれども。","id":"exchange-079"},{"speaker":"塚本委員","kind":"質問・要望","question":"そこのところがあまり高値を見込めないという中で、こちらの考え方というか、例えば資源回収ということにつきましては、ステーション回収と集団回収と大きく２つあるかと思います。こういった回収のあり方のバランスといいますか、市況に応じた新たな改善の余地というのですか、そういったところで何かお考えがあるかお聞かせをいただきたいと思います。","respondent":"小林品川区清掃事務所長","answer":"具体的に言えば、例えば古紙については、町会を含めてやっていただいている集団回収が、今かなり減ってきているので、そこのてこ入れをしていく、あるいは３つの回収の役割分担を考えて、品目の調整をすることによって作業効率を上げていく等の対策を、来年度以降。","id":"exchange-080"},{"speaker":"塚本委員","kind":"意見","question":"ちょっと時間がありますので、最後に、７３ページの橋梁長寿命化修繕経費についてなのですが、先ほども別の委員から質疑がありましたけれども、この長寿命化によって橋梁がどれぐらい寿命が延長するのかというところと、そういったことが結局巡り巡って、長い目で見れば、経費の削減、維持管理費とかそういったものの削減につながっていくはずだと思うのですけれども、そういったことは。","respondent":"多並道路課長","answer":"特にどれぐらい延びるかということも、いきなり壊れて直すということではなくて、それを１つ１つ延ばしていくというのが考え方ですので、１つ１つ考えるものです。","id":"exchange-081"},{"speaker":"木村委員","kind":"質問・要望","question":"５８ページの地域振興費の文化スポーツ振興費、そして７７ページの都市開発費の質問をいたします。２０２０年のオリンピック・パラリンピックに向け、国や都、そして本区においても機運を上げていく時期ですけれども、なぜこの時期に国庫支出金が、１４１万円余のマイナスになった理由をお聞かせください。マイナスの影響はどこに出てくるのかも、わかれば教えていただきたいと思います。","respondent":"池田スポーツ推進課長","answer":"理由といたしましては、諸収入で９２６万円が入るため国庫支出金の減と一般財源の減ということになっているものです。この影響についてですけれども、５３ページと４１ページに、財源について載っておりますので、そちらのほうも見ていただければと思います。","id":"exchange-082"},{"speaker":"木村委員","kind":"質問・要望","question":"５９ページに諸収入増額に伴い更正減額とありますけれども、補正前の額に合わせるために一般財源をカットしたということでよろしいのかどうか教えていただきたいと思います。","respondent":"秋山財政課長","answer":"これは一般財源のほうが、諸収入がプラスになりましたので、その分、一般財源が７８４万６,０００円使わなくて済むのだという、そういう意味です。","id":"exchange-083"},{"speaker":"木村委員","kind":"意見","question":"先ほど、スポーツ振興くじにより諸収入として９２６万円が付くとの答弁がありました。これは、スポーツ振興くじの中でも、どういう部分に当たるのかお聞かせください。","respondent":"池田スポーツ推進課長","answer":"こちらのスポーツ振興くじですけれども、今回、９２６万円付いているのは、先ほどもお話ししましたように、中延小学校の夜間照明の改修工事ということでつきまして、他にスポーツ振興くじということで助成金をいただいているものとして。","id":"exchange-084"},{"speaker":"木村委員","kind":"質問・要望","question":"それとも何をどうすれば配当金が入ってくるのかということもお聞かせください。そして、それ以外にも諸収入という点においては、競馬組合配当金や宝くじなどもそれに当たるのかと思うのですけれども、間違っていたら、教えていただきたいと思います。","respondent":"品川庶務課長","answer":"学校の人工芝を例としますと、平成２８年度は助成が付きました。平成２７年度も一部ついております。それから平成２５年度には付いていないというような状況で、毎年付いたり付かなかったりというような状況があります。","id":"exchange-085"},{"speaker":"木村委員","kind":"意見","question":"諸収入の中に、先ほど競馬組合の配当金や宝くじもそれに当たるのかどうかということもお答えください。","respondent":"秋山財政課長","answer":"これは補正予算ですので、年度の中でそういう新たに宝くじ等からお金が入ってきたときには、その諸収入というところで受けている、そういうものです。","id":"exchange-086"},{"speaker":"木村委員","kind":"質問","question":"今回の９２６万円ですけれども、中延小学校の照明工事、そして伊藤小学校と台場小学校の人工芝に使うということで、使用目的は決まっており、それ以外として、平成２７年度などにも入ってきたということでありますけれども、照明そして人工芝、先ほどお答えいただいてちょっと聞きそびれたかもわかりませんが、他にはどういうことに使うのかということもわかれば教えてください。","respondent":"秋山財政課長","answer":"宝くじ等のスポーツくじ等の収入ですけれども、どちらかというと、何かに使えるのかというよりも、人工芝であるとか、今回の照明であるとかというものに使った場合に、申請をして助成をいただけるというところで、先ほど庶務課長からもお話しさせていただいたように。","id":"exchange-087"},{"speaker":"木村委員","kind":"意見","question":"５８ページの文化スポーツ振興費の欄ですけれども、補正額が０になっています。右のページにある国庫支出金マイナス１４１万４,０００円と一般財源マイナス７８４万６,０００円から諸収入を差引きして０になったと考えていいかと思うのですが、この一般財源マイナス７８４万円余は、何がマイナスになったのかということをお聞かせください。","respondent":"秋山財政課長","answer":"一般財源の７８４万円というのは、当初、こちらの事業を行う上で、国庫支出金を予定していましたが、国庫支出金が１４１万４,０００円の減額になりましたということと、それからもう１つ、新たにスポーツ振興くじが９２６万円入りましたというので。","id":"exchange-088"},{"speaker":"木村委員","kind":"意見","question":"最後に１つだけ、７７ページの不燃化１０年プロジェクトがありますけれども、なぜ１０年プロジェクトとなっているのかお聞かせください。つまり、なぜ１０年という年数としたのか、理由をお聞かせください。","respondent":"寺嶋木密整備推進課長","answer":"その中の１つの木密地域不燃化１０年プロジェクトという施策を２３区が実施している、こういった経緯です。","id":"exchange-089"},{"speaker":"渡部委員","kind":"確認","question":"８６ページですとか、９６ページにも記載があるのですけれども、少しマイナンバーの関係について様々議論させていただければ、伺えればと思います。それから、今、木村委員からもありました５８ページ、５９ページについて、もう１度教えてください。だから、この９２６万円は、あくまでも中延小学校の照明だけの金額だったのかというところ、先にそこだけ確認させてください。","respondent":"秋山財政課長","answer":"ここの９２６万円は中延小のものです。","id":"exchange-090"},{"speaker":"渡部委員","kind":"確認","question":"先ほどの議論の中で少々ごっちゃになってしまっていたので、そこだけ確認させていただいて、マイナンバーの後で聞きます。先にマイナンバーを聞きます。今回、てっきり私自身も今年で一旦交付の臨時窓口、第三庁舎のほうも終わりなのかなと思っていたら、引き続き行うというのですけれども、今後のスケジュールを教えてほしいのと、なぜそのようにもう１回延長になるのか。","respondent":"提坂戸籍住民課長","answer":"ゴールデンウィークのタイミングで、そちらのほうを戸籍住民課の事務室に移しまして、５月の連休明けからは、戸籍住民課の事務室のほうでマイナンバーカードの交付を行ってまいります。防災センターの３階につきましては、連休明けから原状回復工事を行う予定です。","id":"exchange-091"},{"speaker":"渡部委員","kind":"質問","question":"現実問題、どういうところで使うかといいますと、通知カードを見て番号が書いてありますから、給与支払者の方々にお伝えしたりですとかがあります。このカード普及率といいましょうか、カードの普及率は、今年度はどうだったのでしょうか。どういう聞き方をしたらいいでしょうか。その割合が、区なり、国なりが想定していた数字より多いのか少ないのか、その辺がわかれば教えてください。","respondent":"提坂戸籍住民課長","answer":"既に２月末までにマイナンバーカードを交付した方が４万７４１件です。３月末の段階で大体４万３,０００件程度の方にマイナンバーカードを交付したいという考えです。","id":"exchange-092"},{"speaker":"渡部委員","kind":"質問","question":"これが感覚として私はわからないのですけれども、私自身は、これ、少ないなと思うのですが、そもそも国なり区なりが見立てた想定があったと思うのですけれども、それと比較してどうなのでしょうか。その辺の感覚がわかれば教えてください。","respondent":"提坂戸籍住民課長","answer":"国全体の見込みでは、平成２７年度と平成２８年度合わせて２,０００万件を見込んでおったのですが、今年度末で国全体の見込みが１,０００万件余です。それと比較しますと、品川区の交付率は上回っているという状況です。","id":"exchange-093"},{"speaker":"渡部委員","kind":"質問・要望","question":"実は、スマホでできますよと言ったところで、そんなものは若い人といいましょうか、使いこなせる人しかできないですから、ある程度ご年配の方になると、身内の方にこういうものが来ていてつくらなければいけないのだけれども、では、お父さん、お母さん、一緒にやりましょうという方がいれば、役所に来るなり、写真を撮るなりして手続きはできるのだけれども、そうでない人は多分置きっぱなし。","respondent":"提坂戸籍住民課長","answer":"今、手元に紛失された方の再交付件数は持ち合わせていないのですが、万が一、通知カードを持ち合わせていない場合は、ご本人が窓口に来ていただいて個人番号入りの住民票をお取りになって、その上でその番号を勤務先に提出していただければ。","id":"exchange-094"},{"speaker":"渡部委員","kind":"質問","question":"そうなのですけれども、例えば、給与所得などでこのカードは必ず必要になるわけですよね。ただやはり基金は大事ですよ、ないと困ったときに大変ですからね。それは置いておいて、印鑑証明とかがすぐに取れました、コンビニで２００円で取れます。ちょっと話を先に持っていきますけれども、９月からコンビニ交付が始まりました。実際、この半年近くやってみて、コンビニ交付はどれぐらいになるのでしょうか。","respondent":"提坂戸籍住民課長","answer":"コンビニ交付の交付件数ですけれども、２月の末で住民票が１,７４２件、印鑑証明は９７０件となっております。これをさらに伸ばすようＰＲを続けてまいりたいと考えております。","id":"exchange-095"},{"speaker":"渡部委員","kind":"質問・要望","question":"やはりもくろみは相当外れてしまいましたね。後ほど現時点での実際の申請状況がどれぐらいなのかということもあわせて伺いたいのですが、この際、やはり様々な部分において、今、転居が多い時期でもありますから、通知カードからの切替えはお済みですかとか、当然、ポスター、告知等も必要でしょうし、もしかしたらケーブルテレビで番組などつくって放映するのも必要かもしれません。","respondent":"提坂戸籍住民課長","answer":"あわせて、町会の掲示板にポスターなどにも張らせていただき周知を行う予定です。","id":"exchange-096"},{"speaker":"渡部委員","kind":"質問・要望","question":"車の運転免許証を返納して、経歴書でしょうか、そういうものをいただいてというようなこともある中で、この個人番号カード（マイナンバーカード）はできてさえしまえば、立派な身分証明書になるわけです。さらなる努力をお願いします。先ほど、地域スポーツの５８ページの金額のところは伺いました。数を教えてくれとは言いません。どのような推移になっているか、状況だけ教えていただければと思います。","respondent":"池田スポーツ推進課長","answer":"今ご質問のありました地域スポーツクラブ、そしてスポレク推進委員会に加入していますサークル数ですけれども、スポレクができた当初と比べますと、徐々にではありますけれども、増えているところでございまして、特に荏原Ｂ地域のスポーツクラブにおきましては、昨年度。","id":"exchange-097"},{"speaker":"渡部委員","kind":"質問・要望","question":"逆に、あそこの小学校の夜間照明だけでこんなにするのだと驚いている部分はあるのですが、そうやって活動団体がこれから増えていく中で、体育館ですとか、場合によっては余裕教室の活用というのでしょうか、貸し出している教室、ともかく体育館だけでは足りないというので、そのようなちょっと広めの教室を使ってダンスをやったり、また文化活動をやったりという方もいらっしゃいますので、宝くじなり。","respondent":"池田スポーツ推進課長","answer":"今のご指摘につきましては、今後も機を見て、いただけるものはいただくような形で申請をさせていただきまして、区民の皆様のスポーツを振興するように努力していきたいと考えています。","id":"exchange-098"},{"speaker":"西本委員","kind":"質問","question":"３６ページの特別区民税、様々絡めまして、６４ページの児童福祉費についてお聞きします。今回の補正予算なのですけれども、当初の見込みに対しまして、何か特徴的なことはあるのか、補正のポイントは何なのか、国とか都の動きを見た上での考え方、それから補正のやり方についてお聞きします。それから減少に転じる時期をどのぐらいと考えているのか、まずお聞きします。","respondent":"秋山財政課長、黒田税務課長、大澤待機児童対策担当課長","answer":"補正の考え方というか、ポイントですけれども、まず１つは、歳入面では特別区税、住民税の伸びがあったということ。減収に転じる見込みはですが、人口が、特に所得稼得層の年代が伸びている時期は当然、税収も入ってくるというところはあるのですが。区の乳幼児人口のピークは、平成３３年以降と見込んでおります。乳幼児人口のピークと保育需要が減少するというのが必ずしも一致しないとは思っています。","id":"exchange-099"},{"speaker":"西本委員","kind":"意見","question":"そうなってくると、では実際、区としての事業の展開をするときに、どういう方向の、バランスですね、バランスをどう考えていくのか。例えば高齢化になっている、それから待機児童の問題もそうですけれども、それらを解消していくという中で、どういう比率で全体を考えていくのかというところがもしもお考えがあればお願いしたいと思います。","respondent":"柏原企画調整課長、大澤待機児童対策担当課長","answer":"ただ、全体として人口が増えている中で、高齢者人口はさらに増え続けるというところがありますので、そういったところでの施策のバランスは非常に難しいところはありますが、人口動向などを見ながら、施策。そうは言いましても、例えば平成５５年以降ですとか、かなり先には閉園するような事業者も出てくるとは思いますけれども、区としましては。","id":"exchange-100"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり公設民営という形の手法も取り入れたりしている関係の中で、民間は様々な工夫をされて転用していくだろうということなのでしょうが、品川区として、公立になりますけれども、その公立についてはどういうふうに考えていくのでしょうか。ただ単に経費の削減という形でそれを決めるということではなくて、やはり全体的な流れの中で考えていただきたいと思いますが、いかがでしょうか。","respondent":"佐藤保育課長","answer":"保育の需要と供給に関しましては、子ども・子育て会議の中でも十分に議論いただきまして検討していきたいと思います。","id":"exchange-101"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは、まず４３ページのいじめ防止対策費、２点目が、１１０ページの高額医療費共同事業交付金、この２点でお伺いしたいと思います。そこで参考までに、１１１ページ、隣のページに「レセプト１件当たり８０万円を超える高額医療費に対する交付金追加分」とありますけれども、８０万円を超える高額な医療費が使われた件数と、主な病気治療がわかれば参考までに教えてください。","respondent":"村尾教育総合支援センター長、高森国保医療年金課長","answer":"ただ、国のほうで減額ということになりましたので、区として補正をさせていただいて、特に人数等の減少はなく、来年度も引き続きスクールカウンセラーとともに。ご質問のレセプト１件当たり８０万円以上の件数ですが、こちら、平成２８年１２月期を見ますと、おおよそですが、３５０件程度となっておりまして、平成２８年度の見込みですと、４,２００件程度かと考えております。","id":"exchange-102"},{"speaker":"こんの委員","kind":"質問・要望","question":"それぞれご答弁ありがとうございました。高額療養費のほうは、わかりました。やはり生活習慣病というところで、大事なことですけれども、そうすると、人間ドックの助成制度をしましたが、この助成を始めて、高額療養費にどんな効果が出てきたのかということを教えてください。","respondent":"高森国保医療年金課長","answer":"人間ドックの助成事業との関連ですが、人間ドック、また国保の基本健診等を早期に受診していただいて、病気を発見させていただければ、合併症等が出ないようなコントロールもできるようなことでございまして。","id":"exchange-103"},{"speaker":"こんの委員","kind":"質問・要望","question":"そのとおりです。なので、この効果が出るように、もっと人間ドックを進めていただきたいのと同時に、もう１つ、やはり予防医学というところでは、脳ドックというのも大変に有効だというふうに思います。かねてから区議会公明党としては、このことを先輩方が上げてきた声でもありますけれども、その点、脳ドックの必要性はどのように考えますでしょうか。","respondent":"高森国保医療年金課長","answer":"脳ドック等につきましても、やはり必要性はあるとは考えてありますが、現状では検討課題ということで承っておきたいと思います。","id":"exchange-104"},{"speaker":"こんの委員","kind":"質問・要望","question":"ですので、将来的に、近い将来で、考えていただきたいと思います。もう１つ、高額療養費の違う観点から要望したいのですが、高額療養費は、出産には直接関わってこないのですが、例えば帝王切開など、こうした出産に関わることで、医療が必要な場合には高額療養費が使えるというところですが、これは出産をされる方に何かこうしたことで安心感を与えるそうしたお知らせというのはあるのでしょうか。","respondent":"高森国保医療年金課長","answer":"申し訳ございません。区ではいたしておりませんけれども、医療機関のほうで、そういうふうなことは様々な形でサポートしていただいていると考えているところです。","id":"exchange-105"},{"speaker":"こんの委員","kind":"質問","question":"医療機関では、お知らせするところとしないところとあるので、もし出産のお知らせのパックにそうしたものもお知らせとして加えられるといいかなというふうに考えますけれども、いかがでしょうか。","respondent":"高森国保医療年金課長","answer":"関係各課と調整させていただきたいというふうに考えてあります。","id":"exchange-106"},{"speaker":"渡辺委員","kind":"質問・要望","question":"７５ページ、公園整備事業費というところで伺います。そういう意味で言うと、需要が大変高い、利用者の要望も多くある中で、整備、改修という意味では、二、三十年前のレイアウト構造から、やはり今が課題解消に向けて、これから先、２０２０年に向け、またそれ以降、向こう１０年、２０年を見据えた、大きなチャンスだと思います。そういう中では、細かく様々な想定で効果を追求していくべきかと思います。","respondent":"溝口公園課長","answer":"そういった中では、日頃の日常管理が非常に大事になってくると思いますので、少しでも長く使えるよう、また、あまりにも傷みが激しいようであれば、その部分の補修はしっかりやって。","id":"exchange-107"},{"speaker":"渡辺委員","kind":"質問・要望","question":"そういう見込みが立った中で、関連して、区役所前の中央公園、こちらもイベント、行事などで大変利用頻度が高く、前もちょっと申し上げたのですが、この辺も想定をぜひ整備をしていただきたいと思いますがいかがですかということを、関連して１つ伺っておきます。そういったところでグラウンド面などの整備、考え方を伺いたいのが１つです。あわせて、クラブハウスのこともお聞きします。","respondent":"溝口公園課長","answer":"最後に、天王洲のクラブハウスです。今回増設する中に、約１００m2の多目的室を設置いたしますので、そういったことから、今後は文化的な利用も含めて、どのような形で利用していくのかということは、今後、検討していきたいと考えているものです。","id":"exchange-108"},{"speaker":"いながわ委員","kind":"質問","question":"簡単にお伺いしたいのですけれども、補助１６３号線整備で、３億８,９００万円ほど減額をされております。これは平成２６年度の債務負担行為で１１億８,９００万円余が事業の予算として組まれていて、差し引くと８億円余になるのですが、これが実際の大井町線の交差部の工事にかかった経費、工事実績というのですか、その辺がどうなのかということを教えてください。","respondent":"多並道路課長、鈴木建築課長、品川庶務課長","answer":"そのうち各年度ごとに行う工事ということで、年度ごとに協定を結んでございまして、それが予定で１１億８,９００万円余ということで行いました。戸建てにお住まいの方、高齢者の方々の中には、引っ越しができないとか、耐震化に踏み出すこと自体がもう億劫で面倒くさいとか。外壁改修の該当する学校名ですが、山中小学校、旗台小学校、冨士見台中学校です。","id":"exchange-109"},{"speaker":"いながわ委員","kind":"質問・要望","question":"都市計画道路に関しては、要は東急の軌道上、上が高架だから、東急の土地にある玉砂利、地図で確認ができたということだったので、それはあくまでも東急のその当時の施工がという部分だと、玉砂利を詰めているのは、東急が当時やったと思うので、それについては図面と違うというのが私も残念で、その分、工期が遅れるということで、ちなみに、この３億８,９００万円余というのは。","respondent":"多並道路課長、鈴木建築課長、品川庶務課長","answer":"補助１６３号線の件ですが、平成２９年度に、今年できなかった杭を打つ行為を、他の工事と合わせてできる部分を洗い出しまして。耐震化に向けた建築基準法の壁というご質問ですが、基本的には、事業主が、様々誤解をされているところもありますので。それに関して今回の補正予算で減額を出しているという状況です。","id":"exchange-110"},{"speaker":"南委員","kind":"質問","question":"介護保険会計について質問します。今年は、介護保険６期目です。平成２７年、平成２８年、平成２９年と、この６期の保険料の改定に当たって、当時、基金を１７億８,０００万円から１１億５,０００万円を取り崩していくと。各年度の取り崩した額、そして平成２９年度末の見込額は幾らか、まず教えてください。","respondent":"永尾高齢者福祉課長","answer":"最終補正予算書に記載のとおり、平成２８年度末の見込額が、１７億７,５７４万５,０００円という見込みになっております。","id":"exchange-111"},{"speaker":"南委員","kind":"質問","question":"平成２７年度、この新しい介護保険の６期が始まるときには、３年間合わせて１１億５,０００万円というふうに説明されていたのが、今、平成２７年、平成２８年だけで１億１,０００万円、それにプラスして平成２９年はここの資料に出ておりますけれども、その額を見て、どのように評価をしているのか伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"見込みに比べると、取崩しの金額は少ないという状況になっております。理由として考えられることといたしましては、国のほうで平成２７年度に大幅な報酬改定があり、平均でマイナス２.７％になっております。その影響を受けているかというふうに考えているところです。","id":"exchange-112"},{"speaker":"南委員","kind":"質問","question":"当初、６億３,０００万円の基金残高としていたものが、平成２９年度末では、この資料によりますと、１５億３,０００万円となっているわけです。取り崩すと言いながら、実際は余っている、その差が出たのは、先ほど質問しましたように、大幅な改定が原因だというふうに言っておりますけれども、これだけ品川区の介護保険財政、豊かな財政があるというふうに見ていいのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"毎期減っているところです。この後、高齢者の人口がかなり増えることが見込まれること、また制度改正なども控えていることから、どういう見込みになるかは予想がつきませんので、このぐらいあって、一番運営としては安定しているかというふうに考えているところです。","id":"exchange-113"},{"speaker":"南委員","kind":"質問","question":"今後の高齢者人口の増加も含めて、これだけあっていいのではないかということなのですが、私は、そもそも大幅な介護報酬の改定があるというふうなことであっても、それを見込んでいながら、６億３,０００万円というふうに残高を予想した結果、倍以上の実態になっているという、こういうことについて、どのように区としては見ているのかというふうに、改めて伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"ただ、現実として国の制度の変更があったために、そこを回避できたということは、良かったというふうに評価しています。","id":"exchange-114"},{"speaker":"南委員","kind":"意見","question":"私は、総合事業のところで、介護保険の大改悪を国が進めて、品川区は２年前から介護報酬を引下げていますよね。したがって、こういう状況の中で、事業所の運営が非常に深刻な状況になっているというふうに思うわけです。実際問題、調査に行ってきました。品川区としては、こういう介護報酬の引下げ、これについてはどういうふうに現場の実態を見たり聞いたりしているのか、その辺の認識をお願いします。","respondent":"永尾高齢者福祉課長","answer":"生活機能向上支援の部分と訪問型サービスＡの部分の差ということになるとは思いますけれども、これまで生活機能向上支援についても、給付のときの時代の制度とはほぼ同じような金額でやっておりますので、事業所がそういう制度を理解していただいて。","id":"exchange-115"},{"speaker":"南委員","kind":"質問","question":"最後に、そういうケースは聞いていないということなのですけれども、区内の全ての事業所が国の介護報酬よりも低く設定した介護報酬により、加算はつけていると言ってもやっている中で、大変だという意見は聞いていないのですか。私はどういう実態になっているのかということを、どう見聞きしているかというふうに聞いたのですけれども、その点についてもう一度答弁してください。","respondent":"永尾高齢者福祉課長","answer":"当初この報酬の単価を説明したときには、当然のことながら、どうやってやっていこうかという相談は多数来ております。それに対しては、１つ１つ回答を文章で書いて返しておりまして、それに対して実際に倒産した事業所は聞いていないということです。","id":"exchange-116"},{"speaker":"南委員","kind":"質問・要望","question":"そこでサービスを受けている高齢者が、自分の今の生活だけではなく、数カ月以上にわたって大変な状況になるわけですから、倒産などさせるわけにはいかないではありませんか。そういう点で、豊かな財政がある、今現在１５億円もあるわけです。もう時間もないので答弁はいいのですけれども、やはりきちんとした守る姿勢で支援をしていただきたいということを要求しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-117"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"どれぐらい差が、これから３カ月、ある程度これをつくるときから３カ月の予想を立てているわけでしょうから、その３カ月間の中で、どの程度というぐらいは、しょうがないかなと思う、例えば金銭的に大きく変わってしまうのかというのが、３つぐらい要因があるとすれば、こことこことここは、ある程度、動いてしまう可能性はあると思っていますというようなことを踏まえられているのかどうか。","respondent":"秋山財政課長","answer":"補正の基本的なところというご質問だと認識をさせていただきました。この補正を上げるに当たって、どのようなルートといいますか、考え方で上げてくるかというと、それぞれ所管のほうで事業を行っておりまして、その中で様々な要因があるかと思います。","id":"exchange-118"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今度は１,７００億円ぐらいの話だから、１％でも１７億円、２％では３４億円、そのぐらいの中で収まるならそれはしょうがないかなと何となく思うけれども、あまり９０億円だ、６０億円だと変わってきてしまうと、最終補正とは何というようなイメージにもなるので、そこら辺の数字をどう捉えているのかということと、決算見込み、今の最終補正から、そこら辺はどうお考えかということを教えていただきたい。","respondent":"秋山財政課長","answer":"この辺の基金の額につきましては、やはり経済の伸びというところとか、それからあとは、決算が出たときの執行の状況とかというものと絡んでくるのですけれども、平成２７年度の最終での伸びというのは、かなり思っていた以上に経済の伸びがあったのではないかというところで。","id":"exchange-119"},{"speaker":"石田（秀）委員","kind":"提案","question":"売上をどうするというのも１つではありますけれども、あとは、「ＵＭＩＬＥ ＳＱＵＡＲＥ」や「Ｇ－ＦＲＯＮＴ」ができて、あそこは我々品川区にあるわけで、そこをもっと区民とともに様々活用していく、そういう視点で２つお聞きしたい。２点目は、開催時間なのだけれども、今、９時で、これは警察との関係や、地域の関係など様々あることはわかっておりますけれども、私は１１時にすることを提案したい。","respondent":"秋山財政課長、久保田総務課長","answer":"我々は、本当に最終補正の精度を上げて、決算まで精度を上げていくということは、今後ともやっていかなければいけないことだと考えていますし、あわせて、基金とか積立ての時に区民にわかりやすい説明も同時に必要だと思っていますので。こうした意味からも、様々な事業等で活用できるようＰＲに努めながら、また競馬組合とも連携して進めていきたいと思ってあります。","id":"exchange-120"},{"speaker":"石田（秀）委員","kind":"提案","question":"ぜひお願いしたいと思います。せっかくオリンピックがあるわけで、そこはソフトの部分で様々な仕掛けができる部分だと考えていますので、ぜひそこら辺をお考えいただいて、我々も提案していきますので、よろしくお願いします。以上で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-121"},{"speaker":"若林委員","kind":"質問・要望","question":"７３ページの下水道合流改善事業、それから５０ページの基金繰入金関係の２点をお伺いしたいと思います。それからもう１点は、補正予算書の８７ページに、繰越明許費の説明が載っておりまして、そこには理由として、都との協議、それから設計変更等に時間を要するという説明が載っておりますけれども、これについてもう少し詳しくご説明をいただきたいと思います。","respondent":"和田河川下水道課長","answer":"８７ページの設計変更等に時間を要しという具体的な内容ですけれども、これについては、池上通りで工事をしているわけですが、池上通りにある既設のマンホールに推進管というモグラのような機械を打ち当てて接続する工事なのですけれども。","id":"exchange-122"},{"speaker":"若林委員","kind":"確認","question":"今年の６月で、その２が完了するという意味ですか。債務負担行為でその３というのも見えるのですが、そこも確認させてください。","respondent":"和田河川下水道課長","answer":"空気抜きの管はもうできているのですけれども、その上の建屋、意匠関係、この辺の工事が残っておりまして、この工事をその３と名づけて発注するものです。そういう意味では、６月までには全ての工事は完了し、この勝島運河の貯留施設の工事全体が完了するという見込みです。","id":"exchange-123"},{"speaker":"若林委員","kind":"質問・要望","question":"これで立会川、勝島運河の水質改善が大いに期待されるということで、工事完了をしっかり進めていただきたいと思います。そこで、水質改善について、引き続きお尋ねをしたいと思います。こういう基準と実際の検出される数値の逆転現象が起こっているのですけれども、なぜ目黒川と立会川でＢＯＤの環境基準が違うのか、これは環境課長になるのでしょうか、お聞かせいただきたいと思います。","respondent":"和田河川下水道課長","answer":"それから下水道局が策定しました経営計画２０１６という計画がありますが、これは２０１６年からオリンピックまでの５年間の計画ですけれども、この計画の中には、目黒川の合流改善施設として、上流側にもう１つ大規模な合流改善施設を建設するということで。","id":"exchange-124"},{"speaker":"若林委員","kind":"質問・要望","question":"そこにも品川区が入ってやっていくということですので、また力強く都と連携を取りながら地ならしをしていただいて、５年と言わず、早期の抜本的な改善となるように、これは進めていただきたいというふうに要望しますので、よろしくお願いします。５０ページの基金繰入金についてお尋ねしますが、公共施設整備基金繰入金が６億円減額、財政調整基金繰入金が４億円余減額となっております。","respondent":"秋山財政課長","answer":"繰越金のほうから先にお答えしますけれども、これは実質収支とぴったり合うように、実質収支というのが平成２７年度から平成２８年度に繰り越す金額そのものですので、それとぴったり合うように今回補正をしているということですので、合わせているということです。","id":"exchange-125"},{"speaker":"あべ委員","kind":"確認","question":"６５ページの認可保育所移行支援について、それから８４ページの午前中も少し質問がありました給与費の明細についてお伺いしたいと思います。それから認可保育所の移行支援なのですけれども、平成２８年度、予算書のほうでは１カ所１,６５０万円で、これがマイナスになっているということは、１カ所予定していたところができなかったということなのでしょうか。","respondent":"秋山財政課長、大澤待機児童対策担当課長、米田人事課長","answer":"土木費の補助金で、国費の配分減ですけれども、再開発は国費の配分減による歳出の減という形ですが、そうでない場合もございまして。平成２９年度につきましては、全ての園に意向調査をかけましたけれども、合うところがないということで、今のところ移行の予定はございません。これについての縮減については、前にも増して引き続き取り組んでいきたいと考えているところです。","id":"exchange-126"},{"speaker":"あべ委員","kind":"確認","question":"それからあと、数字の面では、西品川一丁目の減額幅が非常に大きいと思っているのですけれども、何か理由があって滞っていることなのか、それもあわせてお伺いしたいと思います。移行支援については、これは希望がないからということなので、年度途中でも希望が出てくれば、それは予算も込みで対応するという姿勢はあるのかどうか、確認をさせてください。","respondent":"秋山財政課長、大澤待機児童対策担当課長、米田人事課長","answer":"ただ、今回の場合は、西品川の再開発なのですけれども、これはかなり全体の規模が大きいものですので。認可保育園の移行ですけれども、今後、認可へのご希望があって、要件を満たすことができましたら、それは今後とも支援をしてまいります。労働衛生上でも職場の偏りということでも議論になっておりますけれども、著しくここの職場でということはありませんけれども。答弁漏れがありました。事業が滞っているかですけれども、再開発についてはそういうことはございません。","id":"exchange-127"},{"speaker":"あべ委員","kind":"質問","question":"西品川の事業については、様々な要因があって、なかなか進んでいないところもあるというふうにも伺っていますが、場合によっては土木費のほうでもう１回伺いたいと思います。ただ、この西品川の事業の中で、今、道路と作業ヤードの間が歩道が非常に広くなっておりまして、ここを例えば暫定拡幅をすることによって渋滞を一定解消することは考えられないだろうか、その１点だけお伺いできればと思います。","respondent":"稲田都市開発課長、米田人事課長","answer":"西品川一丁目の再開発事業についてです。建物完成なのですが、平成３０年１月に事務所棟、平成３０年８月に住宅棟ということで、建物の完成予定は進捗どおり行っているです。そういうような対応も１つですし、ある特定の職員に偏っているということについては、その職場での仕事の配分だったり、特定の職員が、やる気、気概を持ってやっているという部分もあるかと思いますけれども。","id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"６４ページの民生費、児童福祉施設費と、８２ページ、公債費、時間があれば、その他またお聞きいたします。このような背景の中で平成２８年度が始まったわけですが、今回の減額補正については、確保すべき人数が集まらなかったのでしょうか。全体の給与の単価が下がったのか、この２億円および３,４００万円のところについてご説明をいただきたいと思います。よろしくお願いします。","respondent":"米田人事課長","answer":"先ほども申し上げましたように、昨年度の１０月１日の現員現給で見込んでおるところですが、その後、育児休業等に入る職員も増加しておりまして、あるいは、職員の入れ替わりによる若干の若返りということでの給与費の差額、こういうようなものが。","id":"exchange-129"},{"speaker":"高橋（し）委員","kind":"質問","question":"就学前の乳児教育のほうの幼稚園の先生方のものは、今お話しあったこの中に入っているとのことですが、教育費のほうではないでしょうか。","respondent":"米田人事課長","answer":"単独の幼稚園と、それから幼保一体施設ということで、教育のほうは単独の幼稚園について計上しています。一体施設については、こちらのほうに計上しておりまして、こちらは現員でやっておりますので、それが欠員であるということはございません。","id":"exchange-130"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、約８００名ほどいらっしゃるという話で、とすると、今、様々な育休の方や、そういった事情があったのですが、年度途中にお辞めになられた方がいらっしゃって、それでどれぐらいの方を採用ができていたのか。かなり様々なご努力をされたと思うのですが、それでも足りない状態とかが生じていたのでしょうか。その辺をお願いしたいと思います。","respondent":"米田人事課長","answer":"職員の採用につきましては、いわゆる任期の定めのない正規の職員につきましては、４月１日の採用ということで、それについては年度途中の欠けた分等も含めて、４月１日で採用していくです。","id":"exchange-131"},{"speaker":"高橋（し）委員","kind":"質問","question":"この競争は、先ほどちょっと別の話題でありましたが、保育士の獲得競争は、ふるさと納税の返礼品競争と近いというような状況もあるとの、マスコミ報道もありましたけれども、公立、私立を含め、人材の奪い合いをするというのではなくて、広い範囲で、やはりオール東京、２３区で確保できるような方法を何とか考えていくことはできないでしょうか。","respondent":"佐藤保育課長","answer":"広域的な保育士の確保策ですが、平成２７年度から国の公定価格での上乗せ、また東京都の独自事業でありますキャリアアップというところで保育士の確保と、ある程度、広域的なバランスのとれた処遇改善政策を進めているところです。","id":"exchange-132"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"８２ページですが、公債費で、利子と元金について減額補正があるのですが、１目の元金のほうだけでお尋ねしますけれども、当初予算では、平成３年から平成２３年の起債の償還元金としての予算でしたが、この元金については、利子と違って確定をしているのだと思います。素人ですので思い当たるのは繰上げ償還ぐらいしかないのですが、わかりやすくお話ししていただきたいと思います。","respondent":"秋山財政課長","answer":"今回の公債費の補正ですけれども、これは平成１７年、平成１８年の減税補てん債についての利率の変更というものです。","id":"exchange-133"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、１１２ページ、国保の繰入金のところでお聞きしたいのですが、５節のその他一般会計繰入金が減になっていますけれども、都からの報奨金、収納率向上取組成績別算定表に基づく品川区への交付金、これと、区で公費１,７００億円が保険者支援として投入されていて、品川区にはそのうち３億７,６５５万円が入っていますけれども、この５節にこの部分が入ってくるのか伺いたいですが。","respondent":"高森国保医療年金課長","answer":"都の分である都の普通調整交付金、特別調整交付金につきましては、計算の仕方が若干違っておりまして、年度当初に８％程度を見込んで、当初予算計上していますので、その枠の中で調整しておりますため、この補正予算の中には含まれてございません。","id":"exchange-134"},{"speaker":"石田（ち）委員","kind":"質問","question":"こうした公費だったり報奨金がどういうふうに配分されているのかということがわからなかったのでお聞きしました。この報奨金について、代表質問でもさせていただいたのですが、平成２７年度の報奨金は９,３００万円という答弁でした。この９,３００万円の内訳を教えてください。","respondent":"高森国保医療年金課長","answer":"平成２６年度の実績に基づきまして交付いただいたお金ですが、こちらは収納率の関係でいきますと、現年度の収納率の伸び率による交付金ということで４,０００万円、滞納繰越分の収納率による交付ということで２,０００万円、滞納処分部門で差押件数による交付が３,０００万円。","id":"exchange-135"},{"speaker":"石田（ち）委員","kind":"質問","question":"ちょっと聞き方がよくなかったのですけれども、品川区の実績として、現年分の収納率が何％で、現年分の収納率の伸び率が何％か。そして、収納繰越分の収納率が何％で、その伸び率が何％か。そして、差押件数がどれくらいかという、この実績の内訳もお聞きしたいと思います。","respondent":"高森国保医療年金課長","answer":"ご説明をします。収納率部門で現年度の収納率の伸びによる交付ですが、こちらは１.０２％伸びておりまして、東京都の指標では、０.５５％以上達成した場合に交付される４,０００万円。","id":"exchange-136"},{"speaker":"石田（ち）委員","kind":"質問","question":"この品川区の国保収納率は、２３区で２位でありますが、その背景には、苛酷な取り立てがあることを代表質問でも述べてきました。最低生活費は差し押さえてはいけないとなっていますけれども、この最低生活費が幾らか認識はされているでしょうか、伺います。","respondent":"高森国保医療年金課長","answer":"国税徴収法によりますと、給与の場合の差し押さえによっては、基本的には１人１０万円プラス生活、体面維持費ということで２割程度というふうな形になります。扶養者が１名いますと、プラス４万５,０００円ということで認識しています。","id":"exchange-137"},{"speaker":"石田（ち）委員","kind":"質問","question":"最低でも１４万５,０００円は残しておくと、そういうことがわかっているのに、口座に入れば全て差し押さえるのはなぜなのか伺いたいと思います。本会議の答弁では、個々の状況により対応しているというふうに答弁されていますけれども、本当にそうした個々の状況によって対応されているのでしょうか。とても個々の状況により対応をしていると言えないと思うのですけれども、いかがでしょうか。","respondent":"高森国保医療年金課長","answer":"この間ご答弁申し上げているとおり、預金に入ったお金につきましては預金債権という認識で対応しておりますが、個々の案件に基づいて様々な状況があります。","id":"exchange-138"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これは前回も質問のところで示させていただいているところですけれども、せっかく相談に来た区民に、個別具体的な実情を聞くこともなく、払うことを諦めさせているというのが今の区の実態なのではないでしょうか。こういった非情な容赦のない差し押さえはやめるべきだと思います。それらを使って、高過ぎる国保料の引き下げ、そして払える国保料にしていくべきだと思いますけれども、いかがでしょうか。","respondent":"高森国保医療年金課長","answer":"３億７,０００万円余につきましては、これは軽減等を行っている保険者に対しての保険者支援金という性質で公費が入ってきてあります。国が２分の１、東京都が４分の１、そして品川区が４分の１を足して、公費として３億７,０００万円余という形になってあります。","id":"exchange-139"},{"speaker":"石田（ち）委員","kind":"質問","question":"もう何度も言っているのですけれども、こうした３億７,０００万円余の公費は、保険料引き下げに使えるというふうになっているのです。やはり国保の根本になるのは、区民の健康と命を守るという、そしてそこにしっかりと払える保険料にしていくことではないでしょうか。通知だけで、そのまま何もなければ差し押さえる、これが容赦のない差し押さえでないと言えるのか伺いたいと思います。","respondent":"高森国保医療年金課長","answer":"申し上げているとおり、こちらのほうにおいでいただいて、これは自主納付が原則ですから、私どものほうから個別にお伺いして、滞納ですけれどもいかがなさいますかというお話は現状ではできませんので、その辺のところはまずご理解いただいた上で。","id":"exchange-140"},{"speaker":"石田（ち）委員","kind":"質問","question":"先ほども言ったように、相談に来ても追い返されるという状況です。本当に個々の状況に応じて個別具体的な実情を聞くこともなく差し押さえる、これは違法だと、区は違法ではないというふうにおっしゃいますけれども、違法な取り立てだと私は思います。しっかりと国保が払える国保料にしていくためにも公費の投入をしていくべきだと思いますけれども、改めていかがでしょうか。","respondent":"高森国保医療年金課長","answer":"繰り返しになりますが、様々な形でご相談いただきたいです。","id":"exchange-141"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"例えばメニューがあって選択をしていくものだったり、区が行う事業で、補助金、こういうものないかなと探してみたら見つかるとか、いわゆる国や東京都から、こういった補助金がありますけれどもというような紹介型というのですか、そういったもの等、どういった仕組みになっているのか、改めて教えていただきたいのと、品川区がこの補助金、助成金を取りに行くというときに、特に予算編成時とこの最終補正時。","respondent":"秋山財政課長","answer":"それは国が政策的に地方自治体を誘導するための補助金もありますし、あとは包括補助金的なものがありまして、区でやっている事業の中で、該当するものがあれば、それを積極的に申請をするという、どちらかというと、大きく分けるとその２つがあろうかというふうに思ってあります。","id":"exchange-142"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは普段は採択されるもので、不採択になったら、これはいわゆる単費でやらざるを得なくなるとかといった事態が生じたときに、本来、国で例年補助金として出されているのに、今回は、先ほどのトイレの件ではないですけれども、何らかの理由で断られてしまって単費になってしまうというのは、品川区としては、普段補助金の活用ができていたものができなくなってしまうので、そういった場面になったときに。","respondent":"秋山財政課長","answer":"１つ目のご質問ですけれども、申請して不採択になった場合ということで、もちろん不採択になったものは、結論から言えば単費でやることになるのですけれども、その場合にも、やはり歳入がどうのこうの、補助金があるとかないとかということではなくて。","id":"exchange-143"},{"speaker":"石田（し）委員","kind":"質問","question":"教育費の委託金ですが、先ほど、我が会派のエースの松永委員からこの件がありまして、５０万円から２０万円に減額がなされた中で、オリンピック・パラリンピックの関連事業でこれを賄っているから充実をしてやっているというようなお話でしたが、そもそもオリンピック・パラリンピックの関連費用が、特色ある教育活動に充当されているわけでありまして、これの違いが私はあるのかなと思うのですが。","respondent":"熊谷指導課長","answer":"オリンピック・パラリンピック教育の推進事業でありますけれども、各学校そして幼稚園に３０万円ずつついているものです。全ての公立学校、幼稚園についておりますけれども、その中で、オリンピック・パラリンピック教育の大きな柱としまして、伝統文化という柱があります。","id":"exchange-144"},{"speaker":"石田（し）委員","kind":"質問","question":"ということは、この委託金は、学校を指定はされていなかったのか、それともオリンピック・パラリンピックの関連予算の指定されている学校だから、要は同時に合わせてできたということなのか、そこを改めて教えてください。","respondent":"熊谷指導課長","answer":"全ての公立学校、幼稚園でオリンピック・パラリンピック教育推進事業が３０万円予算がついております。指定校５校は、３０万円をオリンピック・パラリンピック教育の予算として受けつつ、伝統文化ということで２０万円上乗せして５０万円の予算があります。","id":"exchange-145"},{"speaker":"石田（し）委員","kind":"質問","question":"わかりました。当初の予算を組み立てたときと比較して、半減ですので、正直、事業の内容が大きく変わってしまうのではないかと。充実をしているということですが、その点、当初予算のときと今回の最終補正で変わったことはないということを最後に一言いただければと思うのですが、いかがでしょうか。","respondent":"熊谷指導課長","answer":"そもそもこの事業ですけれども、平成２７年度のときは、伝統文化を学ぶ授業でございましたが、平成２８年度は発信ということで、午前中にもお話しした都立学校に派遣されているＪＥＴ青年との交流が主です。","id":"exchange-146"},{"speaker":"たけうち委員","kind":"質問","question":"それから３点目の建築物耐震化は、先ほども別の委員からありましたけれども、４億近く減ということですが、この減の内容について、予算書等では耐震化が木造住宅の一戸建てまたアパート、それぞれ３０棟、アパートが１５棟、それから非木造が３棟、マンションが２棟、特定緊急輸送道路が１３棟というのが予算書だったのですが、このうちのどれがどのように減ったのかということがわかれば教えてください。","respondent":"廣田子ども家庭支援課長、川島健康課長、鈴木建築課長","answer":"請求については２カ月遅れで来る形ですが、平成２７年度の後半には、冬場ですが医療費が少なかった一方で、１月の末から２月にかけて。平成２９年度の当初予算も、この２,０００件を見込んだ形で組ませていただいております。今回の減額補正の大きい中身ですが、１件当たりの予算規模が大きい特定緊急輸送道路沿道建築物の耐震補強工事について。","id":"exchange-147"},{"speaker":"たけうち委員","kind":"提案","question":"それぞれありがとうございました。今、インフルエンザが増えていてとありましたけれども、私たちも今までインフルエンザの子どもへの補助みたいなものも提案とかしてきたこともありましたけれども、そういう関係なども、今後探っていくのも大事なのかと、予防することで、かえってそちらのほうの部分が減るのかななどということも思うのですが、その辺のところの考えをお聞かせください。","respondent":"廣田子ども家庭支援課長、川島健康課長、鈴木建築課長","answer":"今後、医療費の削減につきましても、保育園、小中学校等の予防対策でありますとか、連携して削減の工夫について研究していきたいと思ってあります。それから体制の整備ということで、今までしばらく契約医療機関は増やしてはいなかったのですが、今回の２,０００件ほどの増を見越しまして。今ご質問いただいた件ですが、やはり中身的には特定緊急輸送道路沿道建築物の補強工事費、これは１件当たり用意していた金額が非常に大きい金額です。","id":"exchange-148"},{"speaker":"たけうち委員","kind":"提案","question":"最後のところから行きます。それから子どもすこやか医療費については、これは非常に大事な施策なので、医療費が上がっているからということでクレームを言っているつもりはないのですけれども、様々な効果的なやり方をまた検討していただければと思いますので、要望して終わりにいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-149"},{"speaker":"松澤委員","kind":"質問・要望","question":"市街地整備事業費の中に、西品川一丁目地区再開発事業、大井一丁目南第１地区再開発事業、目黒駅前地区再開発事業、パルム駅前地区再開発事業、駅前通り地区再開発事業と５つありますけれども、これらの完成年度と現状の進捗状況をお知らせいただきたいと思います。","respondent":"稲田都市開発課長","answer":"大井一丁目南です。現在、掘削工事をやっておりまして、竣工予定が平成３２年を予定しております。掘削工事による基礎工事を今やっているという状況です。そして、武蔵小山パルム駅前地区です。これは建物竣工が平成３２年１月です。こちらも今、建築工事を進めているです。","id":"exchange-150"},{"speaker":"松澤委員","kind":"質問","question":"それぞれ、今、完成年度をお聞きいたしました。これを見ますと、平成２６年度が更正減額が５億円、平成２７年度、昨年度が９億円強、今年度は４７億２,９１６万円、特に今年度大きくなっているのです。なぜ今年度だけこんなに増えてしまったのかということをお聞きしたいと思います。","respondent":"稲田都市開発課長","answer":"再開発事業ですが、その地区、今、６地区ほど事業中ということでやっております。そういう中で各現場の進捗状況が様々あるです。","id":"exchange-151"},{"speaker":"松澤委員","kind":"確認","question":"今の西品川は、補助金が減になったというふうに聞こえたのですが、そうなのですか。もう一度確認しておきたいと思います。","respondent":"稲田都市開発課長","answer":"そういう中で、個々の年度におきまして修正をかけながら、補助金の配分の違いがあったりしますので、各年度ごとで修正をかけながら事業計画を見直しながらやっていっているです。多少の違いはありますけれども、トータル的には、事業をやっていけるというところでやっております。","id":"exchange-152"},{"speaker":"松澤委員","kind":"質問","question":"この開発事業の中では、補助金がちょっと減という話が今ありましたけれども、例えば大井一丁目南第１地区再開発事業においては、国庫補助金交付年度の変更に伴って年度内に執行が見込めないため翌年度に繰り越す、繰越明許費でしょうか、これがやはり駅前通りにも書いてありますね。その辺をお聞きしたい。","respondent":"稲田都市開発課長","answer":"再開発事業ですが、先ほども申しましたように、原則的にはその年度年度で見直しをかけながらやるということですので、今年度、補助金等に関して、また来年度改めて要望していくですが、この大井一丁目南第１地区におきましては、国の補助の交付年度の変更に伴いまして。","id":"exchange-153"},{"speaker":"松澤委員","kind":"質問","question":"そうしますと、４７億余の更正減額が、それは補助金がついていたのが４７億余減額に、今年執行できないということになると、これは来年度に打ち切り再計上になるのでしょうけれども、そのときにもう補助金がつかなくなってしまうのですか。それとも今年度ついている補助金は、来年度に再計上しても補助金はついて回るということなのでしょうか。その辺だけ聞いておきたいと思います。","respondent":"稲田都市開発課長","answer":"今年度少し低かったというところにおきましては、来年度の要望は少し、また配分等を見直しながらやっていくということで、全体的に事業をやる中においては、大体バランスがとれているのではないかというところで考えてあります。","id":"exchange-154"},{"speaker":"松澤委員","kind":"質問・要望","question":"時間がないので次に行きます。もう１つ、防災街区整備事業の中で、中延二丁目旧同潤会地区、これは大変に大きな予算を組んでいる中で、今回、補正でプラスになっているということは、大変にこの事業が進んでいるというふうに思われるのですけれども、これは皆さんもう引っ越しをされたということなのでしょうか。その辺のことをお聞きしたいと思います。","respondent":"寺嶋木密整備推進課長","answer":"防災街区整備事業の今回の補正に関しましては、実は補償費というものが事業費の中にありまして、実際には、例えば建物の補償費、それからあと引っ越し等にかかる仮移転を含めた補償費、こういったものが事業費に入っておりまして、これが当初の段階では。","id":"exchange-155"},{"speaker":"須貝委員","kind":"質問","question":"私は、６ページ、繰越金等について財政課にお聞きしたいと思います。５７ページ、シティプロモーション事業の考え方を企画調整課にお聞きしたいと思います。そして、新しくできた災害復旧基金が１５億円、さらに繰越金が当初予算と比べて２１億円増えたということは、単年度で総合計９９億円使わないお金が残ったということでしょうか、教えてください。","respondent":"秋山財政課長","answer":"今年度、積立金で、先ほど義務教育基金の積立金についてはご説明をさせていただきました。それから財政調整基金の減についてもご説明をさせていただきました。","id":"exchange-156"},{"speaker":"須貝委員","kind":"質問","question":"ただ単純に、総合計９９億円が使わないお金が残って、基金にも振り分けたということですよね。毎年こんなにプラスが残るならば、区民の方は大方減税を望むのではないでしょうか。生活困窮者に対して、残った、使わなかったお金の５％、１０％は、そういう方たちのために使う。お金を返すということも、これはやはり考えるべきではないかと思うのですが、その辺についてご見解をお聞かせください。","respondent":"秋山財政課長","answer":"ただ、区の歳入が伸びているのは、１つは税収が上がっているということで、ただ、税収が上がっているだけで何もしなければ、それは積み上がっていることで返すということもあり得るかと思いますけれども、私どもとしましては、税収が上った分につきましては、例えば今回。","id":"exchange-157"},{"speaker":"須貝委員","kind":"質問","question":"そんな中で、ふるさと納税による６億３,０００万円、減収が出ております。これは気にならないのですか。だから、うちもどんどん２３区を挙げて、良いものを売ればいいじゃないですか。そういうやり方をしてやっていって、お金が一部の自治体にいっぱい行って、逆にちゃんとやっている自治体にお金が回らない、こういう仕組みはおかしいと思うのですが、何かお考えがあるのでしょうか。教えてください。","respondent":"秋山財政課長","answer":"ふるさと納税につきましては、今年２月の区長会総会でも、本来の制度の趣旨から、現在、逸脱しているということ、それから税負担の恩恵を受ける一方、失われた自治体の行政サービスの低下になるということで、不公平が生じていることで。","id":"exchange-158"},{"speaker":"須貝委員","kind":"質問","question":"税務課でも必死になって徴税しているのでしょう。そうではないでしょう。どうしたらこれを止められるのだということを考えなければいけないと思う。品川区はどうなのでしょうか。このような状況下において、シティプロモーション、必要があるのですか。これは企画調整課にお聞きしたいのですが、全部満たされているではないですか。どうしてシティプロモーションが必要なのですか考え方を教えてください。","respondent":"中島企画部副参事","answer":"シティプロモーションに関しましては、品川区の魅力を区内外に発信するということで取り組んでおります。目的といたしましては、将来的な人口減少を見据えてやっております。短期的には様々とご意見もあると思いますが、長期的な人口減少を見据えて取り組んでいるところです。","id":"exchange-159"},{"speaker":"須貝委員","kind":"質問","question":"現に日本全国を見て、２３区、この品川区などは、人口が非常に増えているのですよ。人がどんどん集まって住宅もどんどん建っている。果たしてそれが意味があるのか、私は非常に疑問に思います。それに対してはしっかり今言っておきます。ところで、このシティプロモーションにテレビＣＭを受注している電通が関わっていると聞いたのですが、これは事実でしょうか。","respondent":"中島企画部副参事","answer":"今回の平成２８年度、事業を委託しています電通に関しては、電通東日本ということで、１００％子会社に発注をしております。","id":"exchange-160"},{"speaker":"須貝委員","kind":"質問","question":"１００％子会社に発注しているという話です。これは新聞報道にも出ましたが、社員に違法な長時間労働をさせたとして、労働基準法違反容疑で電通が書類送検された。そして、日本中央競馬界では指名停止になっています。そして、滋賀県、京都府、奈良県、和歌山県、このような自治体にも広がっているのですが、品川区はしないのでしょうか、お聞かせください。","respondent":"立川経理課長","answer":"電通ですが、区で契約しているのは、電通の本社ではございません。電通の子会社ということになっておりますので、指名停止ということにはならないということで考えております。","id":"exchange-161"},{"speaker":"須貝委員","kind":"質問","question":"今ちょっとお話ししたのですが、１００％電通の子会社ということは、それはどう考えてもイコール電通ということではないのですか。資本がそれだけ入っていれば、１００％電通でしょう。それは違いませんか。","respondent":"立川経理課長","answer":"資本がどの程度注入されているということには関わらず、別会社という扱いになっております。","id":"exchange-162"},{"speaker":"須貝委員","kind":"質問","question":"条例というのは私はわからないですが、少なくとも品川区、自治体ですよね。それで、皆さんの模範となるべき活動、行動をとっているわけではないですか。今の話だったら、いや、子会社、１００％電通の子会社ですが、名前が違うからいいのだ。いや、名前が違うからいいのですかという話なのですが、もう一度ご答弁ください。そして、条例ではどういうふうになっているのですか。","respondent":"立川経理課長","answer":"いわゆる事業者を指名停止する場合に、区の内規で指名停止基準を設けております。それは国も東京都も設けているところですけれども、区の指名停止基準には抵触しないということで、子会社は指名停止にはしないです。","id":"exchange-163"},{"speaker":"須貝委員","kind":"質問","question":"最後に１つだけお聞きします。これ、前に聞いたときには、電通がやっていると聞きました。それはいつから子会社に変わったのですか。それとも、もともと子会社だったのですか。たしか総務委員会では、電通が受けているという話を聞きましたが、もう一度ご答弁お願いします。","respondent":"中島企画部副参事","answer":"電通東日本に関しましては、プロポーザルで、電通ではなく電通東日本に発注をしています。","id":"exchange-164"},{"speaker":"須貝委員","kind":"質問","question":"すみません、今、電通とついているのですね。それでも全然違う会社だと、そういうふうにおっしゃるわけですか。ただ一般の区民の方が、それでは納得しないと思うので、私はやはりそういうところは正すところは正して、区民から誤解を受けないような条例なり仕組みづくりをすべきだと私は思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-165"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは、３９ページ、シティプロモーション推進経費について伺おうと思っています。先ほどの話で盛り上がってしまって、なかなか聞きにくくなってしまいましたが、今年は、品川区でシティプロモーションサミットも行なわれるということで、ぜひ力を入れてやっていっていただきたいと思いますが、３９ページの内容について教えていただきたいのと。","respondent":"中島企画部副参事、伊崎地域活動課長、久保田総務課長","answer":"３８ページ、３９ページのシティプロモーション推進経費の交付金の関係ですが、平成２８年度に、シティプロモーション特設ホームページを作成したこと。町会等で使える補助金についてですけれども、具体的には東京都の地域の底力の発展の補助金というのがございまして、そちらにつきましては。指定寄附金の関係ですけれども、指定寄附金につきましては、寄附をされる方が。","id":"exchange-166"},{"speaker":"大倉委員","kind":"質問・要望","question":"シティプロモーション、動画広告ということで、一般質問でもしたのですが、目標を持って動画再生回数をしっかりと増やしていくというところが非常に大事だと思いますので、その辺をしっかりとしていただきたいと思いますが、お答えがあればお願いしたいと思います。この辺の指定寄附金の事業内容に対しての寄附、メニューという部分でいうと、どのぐらいあるのかということを教えていただければと思います。","respondent":"中島企画部副参事、秋山財政課長、伊崎地域活動課長","answer":"鉄道車内の動画広告につきましては、今年度、ＪＲと東急で行いました。指定寄附金の件ですけれども、これは事業を指定して寄附金を出すと言われればどこでも指定寄附は受けるということで。ただ、内容につきましては、やはり東京都からの説明ということになりますので、そこは区としても理解をしながら。","id":"exchange-167"},{"speaker":"大倉委員","kind":"質問・要望","question":"こういうふうに使えますよ、こういうものに使ったらどうですかというアドバイスができれば、もう少し活用ができるのかなと、私も調べたところ、使えるけれども使っていないというのが、１個、２個見つけたので、こういうものは町会としても使っていったほうがお得だなというところで、ぜひそういった説明の工夫であったり、わかりやすいご説明をしていただければ。","respondent":"秋山財政課長、伊崎地域活動課長","answer":"教育事業指定寄附金については、教職員互助会からの寄附ということで、そういうところから寄附があった場合に、こちらのほうで職員福利厚生に資するものであれば、災害対策職員待機寮管理費に充当ということで。町会長あるいは町会の会員の皆様に対しましては、地域センターも含めて丁寧に対応していきたいと考えております。","id":"exchange-168"},{"speaker":"大倉委員","kind":"質問・要望","question":"指定寄附金はわかりました。団体のほうから入ってくるというところではありましたが、受け身ではなく、そういった制度を利用して、政策の部分でもしっかりと、今様々なサイトが民間で活用されてくる中で、制度的にも確定申告しなくていいような制度もできまして増えてくるという中で、ぜひとも受け身ではない前向きな積極的なこうした寄附を受けるような取組みもぜひ工夫していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-169"},{"speaker":"飯沼委員","kind":"質問・要望","question":"６ページの歳入と、５７ページの基金積立金の追加、８１ページの義務教育施設整備基金についてお伺いします。歳入なのですが、特別区税、地方消費税、特別区の財調、合計で４５億円余が潤沢に歳入が増えているということで、これをぜひ区民の暮らし、福祉増進のために使ってほしいと、これをまず質問します。そして、当初のところの予算と差額が幾らになるのか、これを教えてください。","respondent":"秋山財政課長","answer":"平成２８年度の決算の見込みですけれども、こちらはまだ見込みなので定かではありませんけれども、増えるのではないかというふうに見立てているものです。","id":"exchange-170"},{"speaker":"飯沼委員","kind":"質問・要望","question":"数字をいっぱい並べていただいたのですが、少しもわかりません。基金のところの差がどれぐらいになるのかということを聞いたので、そこを教えていただきたいのと、財調基金はやはり緊急の対策などにも使えますよね。公共施設整備基金も建物を建てたりとか、様々そういう公共施設のところに使えるといった意味では、広く考えて福祉に使える部分がどのくらいあるのか教えてください。","respondent":"秋山財政課長","answer":"そういう意味でお話をすると、全部というお答えになろうかと思います。","id":"exchange-171"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そこの予算がふさわしく確保されているかどうか、どのように考えているのかお伺いをしたいと思いますが、具体的な中身で聞きます。精神の方のグループホームが２３区中２２位という整備率が出ました。２３区で最低の福祉というと、多分嫌われる言葉であると思いますが、整備率について、どのような認識を持っているのか、これを伺うのが１点です。","respondent":"中山障害者福祉課長","answer":"そういった意味で、Ｂ型の整備率というところでは、一応、特別支援学校の卒業生の卒後の見込み、そうしたものを勘案しながら、足りないところについては整備をするという考え方でいます。","id":"exchange-172"},{"speaker":"飯沼委員","kind":"質問・要望","question":"実際的に現在４２４人の方が利用しているというところにおいては、定員の１.５倍もの詰め込みで行われているという中身なのです。今、質問の中で、どこでどう検討しているのかという答えが全くなかったわけですけれども、ぜひこの障害者差別解消法の実効性を高めていく意味でも、品川区が障害者の皆さんの今解決してほしい問題を責任持って改善を求めていきたいと思いますが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"ただ一方で、就労継続支援Ｂ型というのは、様々なメニューがあって、通いたい就労の中身があることが重要かと考えていますので、そういった意味で区内の施設の就労メニューに合わない方が、例えば近隣の就労継続支援Ｂ型を使っていらっしゃるような。","id":"exchange-173"},{"speaker":"飯沼委員","kind":"意見","question":"障害を持たれている方は、様々な障害があるというところにおいては、対策も１つ１つ違ってくると思うのですが、どういう状況にあるのかというのを１つ１つ細かく丁寧に把握するところからスタートすると思うのです。私は、全庁的に障害者の置かれている状況が把握されているのか、共有されているのか、そこをぜひもう１回お聞かせください。","respondent":"中山障害者福祉課長","answer":"ただ、個別のケース、それぞれどういったニーズがあって、どういった支援が必要かというのは、今は計画をつくっておりますので、その計画の中で個々のニーズの把握を行い、そして必要な資源については整備をしていく、そのような考え方です。","id":"exchange-174"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私もこの障害者の計画、福祉計画を改めてもう１回読ませていただきました。実態をぜひしっかり見て、改善をする計画に練り直してほしいし、やはり絵にかいた餅にならないためには、この実現のための予算をしっかりとつくらなくてはいけない。平成２８年度品川区一般会計補正予算に対しては反対をいたします。この実態から、以上、３会計に反対をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-175"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だから、そういうようなことをどうやって具体的に３８万人の区民の方々に対応していくのかと考えていくと、もちろん課長も頑張ると思うのだけれども、品川区だけでは無理ではないですか。つまり、国がやることだから、様々な形で国に要望して、それから様々な機関を総動員しながらやっていかないと、３８万人の方々のカード執行には結びつかないと思うのですが、いかがでしょうか。","respondent":"提坂戸籍住民課長","answer":"先ほども申し上げたところですが、広報、ホームページ、それから町会の掲示板に張らせていただく、それから先ほどちょっと申し忘れたのですけれども、若い方はツイッターとか、その辺もよくご覧になっているので、そういう手法も十分活用して周知をしまして、あと。","id":"exchange-176"},{"speaker":"伊藤委員","kind":"質問","question":"それは確かに理解できるのです。やってください。それはそういう方向なのでしょうけれども、だけれども、どう言ったらいいのですか、文章１つで理解する方と、それから番号カードのことを何回も説明をして、ご本人の承諾をしっかり得た上でないとできないこともあるわけではないですか、非常にプライバシーの高いものであるから。改めて答弁をお願いいたします。","respondent":"提坂戸籍住民課長","answer":"２３区の様々な所管課長会ですとか、その下のレベルの実務研究会、そういうところでも様々なシステム的な障害、窓口の実務上の問題などを話し合って、東京都、国のほうに要望を上げているところです。今後とも様々な問題を話し合って、どんどん国に上げていきたいと考えています。","id":"exchange-177"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そうなのですよね。本人の確認がないとできない話ではないですか。相当ハードルが高いと誰でも想像するわけではないですか。やはりそれはもっと様々な観点から考えていかないと、いくら品川区が頑張ったところで、なかなか限界があると思うので、ぜひ所管課長会、それから２３区の区長会を含めて、具体的な要望で対応していただきたいと思うのですが、いかがでしょうか。","respondent":"提坂戸籍住民課長","answer":"品川区もそういう形で一生懸命、周知、ＰＲを行ってまいりたいと考えています。","id":"exchange-178"},{"speaker":"伊藤委員","kind":"質問","question":"ぜひよろしくお願いいたします。それから、いじめ防止と学校ＩＣＴ化に関連して質問します。唐突なことですけれども、私もホームページが改竄されました。この情報は、実は警視庁のサイバーパトロールというところから連絡があったのです。だから、そういう観点からも、サイバーパトロール等と連携をしたいじめ対策を新しく構築すべきと思うのですが、いかがでしょうか。答弁をお願いいたします。","respondent":"村尾教育総合支援センター長","answer":"今後、まさにインターネット上のいじめを含めて、様々な問題行動等もありますので、それについては積極的に、教育委員会、そして東京都との連携は進めていこうというふうに考えております。","id":"exchange-179"},{"speaker":"伊藤委員","kind":"確認","question":"ぜひ進めてください。つまり、そういう案件があるということがわかった後、ＨＥＡＲＴＳ等の様々なシステムができているのだけれども、そういうことで具体的に解決していく仕組みになっているのですかということの確認を改めてお願いいたします。","respondent":"村尾教育総合支援センター長","answer":"同時に、このようなインターネット上においての児童生徒の個人情報とか、様々な状況につきましては、生活指導主任会を月１回行っておりますので、そこでも情報共有をしながら、各学校で改めて児童生徒に対し。","id":"exchange-180"},{"speaker":"伊藤委員","kind":"質問","question":"目的は、つまり、そこの一番最後のところです。つまり、タブレットで、どの端末がどういうところのどういうサイトへアクセスをしたかということまで把握することができる。だから、そういう観点から考えていくと、児童生徒の、監視ではないのです、決して監視ではないのだけれども、いじめに関する情報については、そういうところからも取れる可能性があると思うのですが、いかがでしょうか。","respondent":"有馬学務課長","answer":"今、タブレット推進校で行っていますけれども、それとパソコン教室も含めて、ログは一応取っております。誰がどういうふうにアクセスしたかということは管理をしている状況です。","id":"exchange-181"},{"speaker":"伊藤委員","kind":"質問","question":"もちろんログはいいのですけれども。だから、これは非常にいいなと思いました。だから、ログは必要です。だけれども、ＩＣＴ機器はさらにもう今一歩進んでいる。そういうことを活用しながら、様々な情報をしっかり把握をした上で、最終的にはいじめの解決につなげていくことをつくり上げていったらいいのではないでしょうかということを質問していますので、改めて答弁をお願いいたします。","respondent":"有馬学務課長","answer":"家に帰ったときにはオフラインになりますけれども、学校にいる場合は、ある程度、生徒が自由に使えるという状況ですので、すみません、先ほどタブレットのほうも取っていると言いましたけれども、タブレットはこれから取るということを検討しているということで。","id":"exchange-182"},{"speaker":"伊藤委員","kind":"意見","question":"それからコミュニティサイトと言ったか、正確でないかもしれないけれども、ネット上では様々なサイトがいっぱい出てきます。不特定の方々が交流できるサイトで、しかも無料です。お願いいたします。","respondent":"村尾教育総合支援センター長","answer":"ネット上にいじめを含めて、子どもたちの個人情報につきましても、改めて専門の業者と教育委員会で様々な機会で検討会を持ちまして、どのような対処をするかということについても、専門家の意見を聞きながら、十分対応していきたいというふうに考えているところです。","id":"exchange-183"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/697202?Template=document&Id=1054#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":129386,"voices":442}},{"id":"h29-20170307-3","meetingId":"h29-c-budget","date":"2017年3月7日","dateIso":"2017-03-07","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時１５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を156件抜き出しています。","topics":[{"id":"topic-01","title":"平成２９年度品川区一般会計予算","agenda":"平成２９年度品川区一般会計予算","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"おはようあります。１２６ページ、シェアサイクル事業補助金、１３０ページ、都議会議員選挙費に関連した質疑をします。初めに、シェアサイクルの社会実験が平成２９年度から始まるということですけれども、この取組みに関して、お知らせいただきたいと思います。","respondent":"安井土木管理課長","answer":"こちらは、特に都市型観光プランを実践するということで、オリンピック・パラリンピックも控えて、新しい観光客をどういうふうに、交通などの面でフォローしていくかというような考え方から、これを区内でも実施するというような形で考えているところです。","id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは、区民に対してのサービスなのか、あるいは、他区から来る来訪者に対しての取組みなのか。当然、私は、区民のためのシェアサイクルだと認識しているのですけれども、その辺のことを教えていただきたいのと。この社会実験、平成２９年度開始ということですけれども、何月から始まるのか、お知らせいただきたいと思います。","respondent":"安井土木管理課長","answer":"こちらは、都市型観光プランということで、区内の方が観光するというのもありますけれども、特に、外国人の方が、これから品川区にもいらっしゃるだろうというようなこともありますし、また。","id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"５キロメートルとか、そのぐらいなのですかね。ここを社会実験していくということで。これ、運営に関しても、食べ歩きとか、観光に関しての、そういうマップの作成とか、そのシェアサイクルを借りていただく人に、品川区をもっと知ってもらうというような取り組みというか、冊子とか、そういう広報活動はどういう形になっているのか、教えていただきたいと思います。","respondent":"安井土木管理課長、鈴木文化観光課長","answer":"対象エリアなのですけれども、特に湾岸部、既に実施している港区とか、これからやろうとしている大田区もそうなのですけれども、特に、天王洲エリアはどうですかとか、あるいは水族館のほうにもどうですかとかいうような話もありまして。今後、シェアサイクルのハード、ポートの整備と合わせて、協議しながら、適切な資料や周知方法を、合わせて検討していきたいというふうに考えております。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問","question":"ご答弁の中で、港区と大田区と、今、一緒にやっているという取組みの中で、今後、展開として、オリンピック・パラリンピックも含めて、近隣区との連携があるのか。あるいは、区も独自でやっていくのかというところが、どういうふうにお考えになっているのかということ。開始時期が年度末というのは、まだ、いつという時期的には、決まっていないということでよろしいのでしょうか。お知らせください。","respondent":"安井土木管理課長","answer":"いつということなのですけれども、なるべく早い時期で、年内を目指して実施ができるようにしていきたいというふうに考えてあります。","id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"まだちょっと時期的に、いつかというのは見えないということで、これから、区民の方に対して、あるいは観光客を含めて、これからＳＮＳの広報とかでも発信していくということでよろしいのかどうかというのをお聞きしたいのと。それと、プレス発表にあったサイクルポート、あくまで、これ、イメージなのですけれども。わかっている範囲でお知らせいただきたいと思います。","respondent":"安井土木管理課長","answer":"既に設置しているところから、やはり、利用率が悪いところについては、新たに場所を移すとか、そういったことも考えてありますので、あまり駐輪場のような固定的なものではなくて、このスポットと言われる部分も、必要な観光スポットであるとかいうところに。","id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これ、ぜひ、おもてなしということで、観光を含めたすばらしいシェアサイクルシステムだと思うので、ぜひ今後、いろいろまたご検討いただいてやっていただきたいと思います。続きまして、１３０ページ、都議会議員選挙費に関連いたしまして、今度、アトレ大井町駅に期日前投票所を開設、新設するということで、その辺のところをお知らせいただきたいと思います。","respondent":"工藤選挙管理委員会事務局長","answer":"選挙という特殊性のため、投票の秘密や公平性、秩序維持の面から、私どもも慎重に検討していたところですが、今回、アトレ大井町の協力を得ることができまして、７月の都議会議員選挙から、期日前投票所を新たに設置するです。","id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは、駅ビル内に設けるのは、２３区初めてということで、今、ご答弁ありましたように、アトレの中の何階になるのかという、その投票所、今わかっている範囲で、どの場所というのがわかっていれば、お知らせいただきたいと思います。","respondent":"工藤選挙管理委員会事務局長","answer":"アトレ大井町のエスカレーターを上がって、３階のエスカレーター横に、いわゆる、客だまりのようなスペースがあります。ちょうどそちらのほうで、大体９０平方メートルぐらい場所がとれるわけですけれども、そちらのほうをパーテーションで囲いまして、投票所を設置するです。","id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"アトレ大井町のことはわかりました。期日前投票ということで、１３の地域センターの中でも、期日前投票所が開設されると思います。荏原第四地域センター、６月から大規模な内装工事があるとの話ですけれども、荏原第四地域センターは、今まで確か２階に期日前投票所があったと思うのですけれども、今回、全面的な工事があるということで、今度、設置の場所がどの辺になるのか、教えていただきたいと思います。","respondent":"工藤選挙管理委員会事務局長","answer":"そういったところで、代替というところで、今、私どもが考えておりますのが、ちょうど、荏原町駅前の再開発ビルがあります。こちらの一画をお借りして、投票所を設営するということで、今、考えているところです。","id":"exchange-008"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今、ご答弁あったところ、再開発のところは、１階がテナントが入っていて、２階もテナントが入っているのですね。そこだと、場所は１階なのか、２階なのか、ちょっとその辺のところを教えていただきたい。","respondent":"工藤選挙管理委員会事務局長","answer":"今、予定しているのが、２階の一部分です。ちょうど、こちらのほう、聞くところによりますと、支え愛・ほっとステーションの、いわゆる拠点となるというお話を聞いておりまして、そちらのほうの関連部署と、今、連携をしてお話をしています。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"４８ページ、特別区民税、８９ページ、国民年金事務費、７５ページ、電柱・電線類、７６ページ、自転車駐車場使用料について伺っていきたいと思います。２０１６年の世論調査を確認しますと、９割以上の方が、住み続けたいという希望があったりとか、長期の居住の方とか、結構いらっしゃる中で、一方で、わずかではありますけれども、転出意向の方も３.６％ぐらいいらっしゃる。","respondent":"黒田税務課長、柏原企画調整課長","answer":"納税義務者数増の傾向がいつまで続くのかというご質問ですが、平成２９年度の予算編成にあたりましては、平成２９年１月１日現在の人口も、４,６３８人、前年比で増えておりまして、生産年齢人口につきましても。人口の動向の部分です。そちらにつきましては、人口推計をした中では、今後まだ、全体としては、１０年程度は人口が伸びるというような推計をしています。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問","question":"最後のほうにお聞きした、住宅に対する施策というところがありましたので、次の質問と合わせて伺えればと思うのですが。昨日の質疑の中で、「保育需要が増えるのは、区の魅力の取組みに対する評価のあらわれ」このような趣旨の答弁もありました。これはこれで、品川区が展開している施策が、非常に評価されての、そうした流入人口が増えているという、１つのあらわれでありますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"つる委員","kind":"提案","question":"都心の中で、東京の中で、そして２３区の中で、品川区というのは、ある意味で、昨日もありましたけれども、シティプロモーションをしなくとも、品川区というだけでも、それ自体がシティプロモーションとなるぐらいの、まさに魅力のある区であるというふうに、私自身も考えておりますが、一方でやはり、具体的に地域を見ていくと、本当に昼間の時間帯に、若い世代の方々に、そうした。","respondent":"高森国保医療年金課長","answer":"１０年年金のご質問ですが、区内の対象者、おおよそ２,０００件です。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問・要望","question":"区内では約２,０００件ぐらい、２,０００人の方がいらっしゃるということです。次に移ります。電柱・電線類でありますが、今、国、東京都、そして品川区としても、電線類の地中化、これを推進しており、区議会公明党としても、これまでも求めてきたところでありますが、それはそれで、景観の部分でありますとか、災害時の電柱倒壊等を防ぐというところでは、非常に推進をしていただきたいと思います。","respondent":"安井土木管理課長","answer":"ちなみに、電柱をやめて電線地中化にしますと、９分の１に減免されるという、地中化の１本当たりの線も、９分の１に、単価減でインセンティブを与えるというようなことにもなっておりますので、事業者にとっては安くなるだろうというふうなところはあると思います。","id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"事業者にとっては、９分の１になるというところですが、よく理解できました。最後の駐車場については、１点だけ教えていただいて、歳出のところでまたやっていきたいと思いますが。区内のバイク、二輪車になりますが、その保有台数等がわかれば教えていただきたいのと、区で設置されているところと民間と合わせて、バイクの駐車場が何台あるのか教えてください。","respondent":"桑波田交通安全担当課長、黒田税務課長","answer":"区内のバイクの保有台数につきましては、申し訳ありませんけれども、現在把握しておりません。駐車場の設置台数につきましては、区営につきましては、バイク９３８台分、あと民間は５３１台分が設置されているところです。軽自動車税の課税台数ということで申し上げますと、平成２８年度の課税実績で、原動機付自転車。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"ここは平日はいつもいっぱいで、とても使いにくい状況があります。４月には、近くに認可保育園が２園できる関係から、今後は駅前駐輪場を利用したい人もさらに増えるのではないかと思いますけれども、まずもって、多くは駅の利用者ですから、ＪＲの要請と合わせて、区営駐輪場の改修や建替えで台数を増やす、こうした計画が必要だと思いますけれども、合わせていかがでしょうか。","respondent":"桑波田交通安全担当課長","answer":"現在ある駐輪場につきましても、なかなか施設が古くて、使い勝手の悪い状況もありますので、増設と合わせて、今ある駐輪場の改修等のほうも考えているところです。","id":"exchange-015"},{"speaker":"中塚委員","kind":"提案","question":"改修を考えてくれているということですけれども、ぜひよろしくお願いしたいと思います。この階数を高くして台数を増やす、こうした計画を具体化していただきたいと思いますけれども、いかがでしょうかというご提案です。いずれにしても、新たな駐輪場をつくる場合は、周辺住民や地元町会などへの説明や意見の聴取、ここにはとても丁寧さが必要だと思いますけれども、この点についても伺いたいと思います。","respondent":"桑波田交通安全担当課長","answer":"新しく増設するにあたりまして、地域、町会ですとか近隣の方、こういったところにも、いろいろ説明会等を実施しながら、丁寧に進めていきたいと考えております。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"新たな整備と同時に、こうした利用状況もよく把握をしながら進めていただきたいと思うのと、ここは、歩行者と自転車が重なり合う場所ですので、ここの設置はちょっとやめたほうがいいのではないかと思うのですけれども、その点についても伺いたいと思います。合わせて、再開発についても、幾つか伺います。公共施設管理者負担金の総額。事業中のものの見込みも含めて、それぞれ伺いたいと思います。","respondent":"桑波田交通安全担当課長、稲田都市開発課長","answer":"場所につきましては、現在、まだ確定ではありませんし、これから具体的に検討していきたいと考えております。今後の見込みも含めまして、管理者負担金、７７億１,４００万円というふうになっております。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"駐輪場のほうは、地元の方のご意見を聞いて、ひとつよろしくお願いしたいと思います。ここに税金が使われることを住民に話すと、民間の超高層マンションになぜ税金を使うのか、意味がわからないと、そうした声も伺います。しかし、認可保育園には、建設費や運営費も、補助金はゼロなのに、再開発にはさまざまな補助メニューがあるというのは、私はおかしいと思いますけれども、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"木造密集地もあるというところで、そういうところも改善していこうということで、地域の方が、その地区のことを考えてやるというところで、そういうところを共同化して、そういう道路や空地等を整備しながら、安全なまちをつくるというところで補助金が充てられるものです。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"私の質問は、おかしいとは考えないのかと伺ったので、その点、伺いたいと思います。つまり、認可保育園にはなくて、再開発にはたくさんの補助メニューがあるのは、私はおかしいと思います。再開発への助成制度について、調査設計計画費、都市整備費、共同施設整備費、事務費の、それぞれ助成メニューがありますけれども、どんなところが具体的に助成対象となっているのか伺いたいと思います。","respondent":"稲田都市開発課長","answer":"補助メニューの対象ですが、まず、設計費もあります。それから、補償費というのもあります。それから、共同施設整備費におきましては、建物の中の共有部分、そういうところに対応して、補助を出しているものです。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問","question":"認可保育園にはなくて、再開発にはあるのはおかしいではないかと、そう思わないのかと伺ったので、その辺についてご答弁伺いたいと思います。しかし、公設公営の認可保育園の建設費と運営費には、補助金はゼロとの説明です。これは、住民から見ても、私も思いますけれども、おかしいと思いますけれども、いかがでしょうか。これだけの巨額な税金を使う事業は、ほかにあるのか、伺いたいと思います。","respondent":"稲田都市開発課長","answer":"まちづくり、これは区民生活においては非常に重要なものです。私どもはそのまちを、安全・安心なまちに変えていくというところで、拠点の整備、再開発事業等、今後も予算が許す限りは続けていきたいというふうに考えております。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"公設公営の認可保育園では建設費はゼロ、運営費もゼロです。例えば、大震災で住宅が全壊になっても、支援金は最大で３００万円しか出ないのに、実際はとても足りず、建替えが進まず、二重ローンで苦しめられている。これが実態です。私は、こうした、区民よりも大型開発を優先しているこうした区政は、転換をして、福祉・暮らしこそ最優先に切りかえるべきだと思いますけれども、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"先ほど来、申し上げておりますが、安全・安心のまちづくりを進めていくことは、区民にとって非常に重要なことですので、引き続き進めてまいりたいと思います。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"区政の転換を求めましたが、説明ができないということだと思います。私は、こうした仕組みは、しっかりと変えていくべきだと思いますので、ぜひご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"いながわ委員","kind":"質問","question":"とりあえず、それについてお伺いします。特別区たばこ税なのですが、今後、受動喫煙防止対策ということで、今、国会でいろいろ審議をされていると思うのですけれども、これが施行されたときに、実際、税収の見込み額と言うのですか。減の理由ですね。発行数が増えなければ、コンビニでの発行数も増えないというふうに思っていますが、その辺をどう分析をされているのかということを教えてください。","respondent":"黒田税務課長、鈴木文化観光課長、池田スポーツ推進課長、提坂戸籍住民課長","answer":"平成２９年度の予算編成にあたりましては、マイナス７％程度の前年比で減を見込んでおりまして、このところ、禁煙志向でありますとか。それと、平成２９年度についての収入額の減少の理由ですが、１つは、例年の、毎年の利用数、収入額を参考にすることと、それから。昨年７月に改修いたしました、しながわ区民公園の利用料につきましては、平成２８年度につきましては、平成２６年度の数字から、当初。","id":"exchange-023"},{"speaker":"いながわ委員","kind":"質問・要望","question":"課長のお口から、老朽化しているということがありましたので、これは、歳出でまたいろいろと質問させていただきたいと思います。真横にはバーベキュー場もあり、その先には、しながわ水族館も位置している、非常に、真夏とか、家族の利用が多い時期に、一連の流れの中で、使用料と言うのですか。ちょっと歳入からそれてしまうのですけれども、ちょっとそこだけお聞かせいただきたいです。","respondent":"伊崎地域活動課長","answer":"マイナンバーカードに限ったことではございませんが、区の新しい施策や。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問・要望","question":"議会広報費、区議会ホームページについてなのですけれども、昨年度より、私が要望しております区議会ホームページに載っている一般質問などのインターネット録画中継、これは、過去の一般質問などを閲覧できるのですけれども、今現在、Silverlightというシステムが入っておりますけれども、これが古いシステムらしくて、新しいパソコン、スマホ、タブレットでは。","respondent":"原区議会事務局長","answer":"予算事項別明細書の１５９ページの下から３行目の、インターネット映像配信委託等、こちらのほうが、前年と比べると、１７５万９,０００円増えているかと思いますけれども、この中に、その対応についての経費を盛り込んでいるということで。","id":"exchange-025"},{"speaker":"筒井委員","kind":"意見","question":"具体的に、どういったシステムを使うのか、また、いつから一般の区民の方が見ることができるようになるのか、その見通しをお知らせください。","respondent":"原区議会事務局長","answer":"こちらについては、委員ご指摘のとおり、現在はそういったシステムが入っていないと見られないという形になってありますけれども、こちらについてはマルチデバイス化ということで、インターネットの環境に左右されないような対応ということで、今、調整をしています。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"やはり、非常に、人口の増加というのは重要だと考えておりまして、また、今後も、将来の人口増は、先ほども見込まれているということなのですけれども、やはり、納税義務者ということでは、生産年齢人口の増加が非常に重要だと考えておりますけれども、人口は増加するということですけれども、生産年齢人口は、品川区人口ビジョンによりますと、中位・低位推計では、横ばいというふうに見えるのですけれども。","respondent":"柏原企画調整課長","answer":"生産年齢人口につきましては、一定程度、中位推計ということで、平成３２年ぐらいまでをピークに、徐々に上がっていくですが、そこからは一定程度で、そのままをキープするような形ということで見込んでいるものです。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"品川区人口ビジョンを見ますと、平成４３年から、高位・中位・低位の推計、いずれの推計でも減っていってしまうということで、やはり対策を立てなければいけないと考えております。逆に、この生産年齢人口を減らしてしまうリスク、ネガティブ要因というのはどのようなものがあると考えておりますでしょうか。その２点、お知らせください。","respondent":"柏原企画調整課長","answer":"今年度も、平成２９年度予算のほうで、新たな施策の方向性というのを示させていただいた中で、子育て、それから年少人口の部分を、いかに増やして定着していただくかというところでの施策は、充実したもので出させていただいてあります。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"転勤の場合というのは致し方ないのですけれども、今後はやはり、２３区間でも、自治体間競争と言いますか、そうした競争が起こると思います。リスク、ネガティブ要因について。すなわち、生産年齢人口の流出の可能性というのもありますけれども、そうした羽田新ルート案によって、生産年齢人口の流出の可能性ということについて、どのようにお考えでしょうか。お知らせください。","respondent":"中村都市計画課長","answer":"今、区の段階といたしましては、必要な情報を国から集め、そして、区民の皆様に十分周知をしていただくという段階ですので、現在、まだそういった人口流出については考えておりませんが、これについても、国に、十分に必要な対応を求めていくという考えです。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"ふるさと納税寄附金についてお伺いをいたします。このふるさと納税も、私、品川区の特別区民税、歳入減のおそれがあるリスク、ネガティブ要因の１つだと考えておりますけれども。各区への取材をもとに作成したと書かれておりますけれども、この歳入減見込額、平成２９年度８億円というのは、そうした見込みを出したということは事実でしょうか。その点、お知らせください。","respondent":"黒田税務課長","answer":"特別区民税の算定にあたりまして、減額の要素といたしまして、ふるさと納税による減があるのですが、平成２８年度の課税実績で、約６億３,０００万円ほど減があったということがありますので、平成２８年中につきましては、熊本地震等による、いわゆる支援でありますとか。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"昨日、他の議員の質問に対しまして、品川区としても対応していくということがありましたけれども、品川区長としても、これは明確にもう反対すべきだと考えております。品川区は８億円ですけれども、さらに膨らむ可能性がありますので、廃止を前提とした議論を、品川区やほかの区の皆さんと協力して、そうした議論を進めるべきだと考えておりますが、その点、区としてはどのようにお考えでしょうか。","respondent":"黒田税務課長、秋山財政課長","answer":"品川区でも返礼品は用意しておりますが、あくまでも寄附のお礼という形で捉えておりますので、地方を応援したいという気持ちは、ふるさと納税の趣旨は、これは存続されるべきものと思いますが、現在の、減収になった自治体に。品川区といたしましても、品川区長が区長会の総会でも、その旨発言をしておりますし、東京都の会合においても、ふるさと納税については、自治の本旨にもとるという、そういう態度で、強力に要請をしていると、そういうところです。","id":"exchange-031"},{"speaker":"横山委員","kind":"質問・要望","question":"１０１ページ、橋梁改修事業について。１１７ページ、高齢者世帯の安否確認事業について。もし時間がありましたら、１０５ページ、いじめ防止対策費についてもお伺いいたします。橋梁改修事業についてお伺いをいたします。都市型観光プラン推進事業について、お伺いをいたします。区外の方から最近増えている相談なのですけれども、「品川区に住みたいのですけれども、どこがいいでしょうか」という相談。","respondent":"多並道路課長、鈴木文化観光課長、中島企画部副参事、中元広報広聴課長","answer":"ただ、デザイン性等の考えにつきましては、来年度に水辺環境の全体的な考え方を整理しようということで。地域の実行委員の方とも何度か打ち合わせ等をしておりまして、ご指摘の目黒区との連携、目黒区側の商店街との連携についても、地域のほうでは。もともと交通の利便性がいいということもありますので、そういうところを、好きな、気に入った場所を選んでいただければと考えています。","id":"exchange-032"},{"speaker":"横山委員","kind":"質問・要望","question":"次の質問に移らせていただきます。高齢者世帯の安否確認事業についてお伺いいたします。緊急通報システムの宅建協会への周知の状況を確認させていただきたいのと、一例なのですけれども、宅建協会ではなく、家賃保証会社から不動産業者へ、そのパンフレットが配布されたというお話も、一部伺っておりますが、配布の経路につきまして、区が把握している情報がありましたらお知らせください。お伺いいたします。","respondent":"今井住宅課長、立木産業活性化担当課長","answer":"初めに、ご指摘いただきました高齢者の見守り事業につきましては、福祉計画課の事業ですが、今ご質問の、私ども、宅建業界、または家主との連携も図っておりますので、今後、緊急通報システムにつきましては。そちらのほうで、子育て中のお子さんを預かったりですとか、そういった連携。それから、あとは、マッチング等に関しましては、ハンズオン型で、きめ細かく対応させていただいているところです。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"高齢者の見守りのほうなのですけれども、緊急通報システムを知らないという方もいらっしゃいますので、周知徹底をよろしくお願いをいたします。子育て世代、女性の支援につきましても、是非、マッチングの仕組みというところの視点で、今後検討いただければと思いますので、こちらも要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"質問","question":"私からは、１３８ページ、基金繰入金で、障害児者総合支援施設建設経費。昨年も出ていましたけれども、これは、全国から注目をされている、障害者の方の生活支援拠点として、国が全ての自治体につくりなさいと言っているものなのですが、確かモデル事業としてお金が出ていたと思うのですが、国からの、これは、補助金というのは使用しないのかどうか、そこをまずお伺いしたいと思います。","respondent":"中山障害者福祉課長","answer":"建設にかかる国からの補助金というご質問ですけれども、こちらのほうは、障害者施設中心ということで、特に国からの補助金はございません。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ですから、今後、こういったことは、本当は企画部門なのでしょうけれども、品川区は各所管、もうしっかりされていますし、それをつないでいくということはもちろん必要だと思うのですが、この障害者の総合支援施設、ぜひ、こういう観点を入れて、食堂も入るわけですから、こども食堂とか、そういうことも考えられると思うのですけれども、そういうモデル施設になっていただきたいと思うのですが。","respondent":"中山障害者福祉課長、大串福祉計画課長","answer":"こちらの施設には、在宅介護支援センター、それから障害の相談とホームヘルプ、訪看なども入りますので、日ごろの、そうした１つ１つの事例の積み重ねの中で、高齢者と障害者の連携というのは、進めていければと考えています。町会や自治会の皆様、あるいは民生委員、こういった皆様、地域にこれまでも根づいてご活躍をしていただいている皆様方と連携をしながらというところを第一に考えて、設置をさせていただいたところです。","id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そこで伺いたいのが、この財源について、２パターンがあると思いますが、この２つが、区の自費なのか、単費なのか、ちょっと款が飛んでしまうのですけれども、介護保険財源なのかどうかというところ。こういったもの、もし、こういう運営費を出すということになって、登録をするのであれば、ぜひそういったものも、区民に周知をしていただきたいと思うのですが、いかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"来年度実施予定の認知症カフェですけれども、２種類ありまして、一般の認知症カフェの運営の補助事業については、国のほうの新オレンジプランでも定められているということで、介護会計の地域支援事業の中の包括的支援事業、任意事業費の中でやることにしております。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問","question":"私からは、１２ページ、債務負担行為の中の中小企業事業資金融資あっせんに伴う金融機関に対する損失補償について。それから、４８ページ、１款特別区税、１項特別区民税。それから、１３９ページ、１７款繰入金、１項基金繰入金について伺いたいと思います。それを、債務負担行為として毎年計上しておくものと理解をしましたが、その理解でいいかどうか、まず、それだけ簡単にお答えいただけますか。","respondent":"山崎商業・ものづくり課長","answer":"現在の融資制度は、区のほうが債務保証をする関係にはなってございませんけれども、特別緊急な場合だけ、銀行に対して、融資をあっせんをするときに、区が保証付であっせんをする場合が、災害時においては、起こり得るということで、条例にもそういった規定がございまして。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"それを伺って、趣旨はとても理解できて、これは必要だなというふうに考えました。それも１点、確認させてください。そう考えると、きちんとした議論は明日ですけれども、災害復旧特別会計に計上されるのがふさわしいのではないかなというふうに思ってしまったのですが、その辺について、どうなのでしょうか。","respondent":"山崎商業・ものづくり課長、秋山財政課長","answer":"委員の特別会計の部分のお話につきましては、区全体の、そうした災害に対しての対応という考えのものに、この融資制度の後にできている考え方と言いますか、そういうことです。こちらの債務負担行為は、条例に、中小企業に対する融資あっせんに伴う損失補償ということで、これは区が直接やることではありませんので、こういう債務負担行為とは。","id":"exchange-039"},{"speaker":"吉田委員","kind":"質問","question":"今日の質問に対する答弁はここまでで結構なのですけれども、やはり、その辺、きちんと切り分けていかないと、やはり、災害が起きたことを条件として、それがない限り不用額になっていくというものが、一般会計の中にあることがどうなのかなというふうに、それだけは意見を申し上げておきたいと思います。その辺の性質、きちんとしていく必要があるのではないかなという趣旨です。","respondent":"秋山財政課長","answer":"こちらの、１２ページの債務負担行為に基づくところは、予算化はされておりません。予算化はされていませんけれども、融資あっせんができるという債務負担行為をつけているというものですから、歳出としての予算は組んでいないのです。","id":"exchange-040"},{"speaker":"吉田委員","kind":"質問・要望","question":"それで、午前中にもご質問ありましたけれども、この実績から言うと、この見込みは随分強気なのかなというふうに思いまして、他区での実績をもとにということですけれども、もう少し、品川区の中での実績というのを、ほかの予算立ての話を聞いていますと、やはり実績ということが大きく予算立てのところには、強く働くのかなと思いますが、この点について、他区の実績ということから。","respondent":"提坂戸籍住民課長","answer":"平成２８年度の予算上の件数ですけれども、住民票の写しが１万５,０００件、印鑑証明が８,６００件となっておりますけれども、これは、平成２６年度の住民票および印鑑証明の、半年間の全発行件数の１０％ということで出したのですが、どうもそこまで。","id":"exchange-041"},{"speaker":"吉田委員","kind":"質問・要望","question":"もし、そんなことはないよ、ということがあれば、後でお答えいただきたいと思います。でも、やはり、マイナンバー制度がきっかけになって、２０１５年度の総務委員会でも、何回か、この情報を守るというか、そういうことについて確認をしています。でも、それは大分前ですので、改めて、現時点で、もし情報が流出してしまった場合の対応策をどのように考えるか、考えていらっしゃるのか、教えてください。","respondent":"仁平情報推進課長","answer":"個人情報自体は、紙の文書もあります。こちらの取扱いにつきましては、毎年、必要な職員研修、並びに各職場における取組みとか、そういう啓発事業を行っておりますので、仮に情報の漏えいとか、文書の流出等がございました場合には、全区的に対応していく形になるかと思います。","id":"exchange-042"},{"speaker":"吉田委員","kind":"質問","question":"システムをきちんとつくっていらっしゃるというのは、何度もご説明いただいていますし、理解というか、そういうふうに頑張っていらっしゃるのだろうなというふうに思っています。それで、もしあったときにどうするかということを考えておくのが、危機管理ということなのではないでしょうか。改めて、危機管理ということでの、人的エラーも含めての対応策、どのように考えているか、教えてください。","respondent":"仁平情報推進課長","answer":"品川区の場合には、電子データ以外に、紙の媒体も含めまして、全て行政情報ということで、厳しく取り扱うよう、指導を徹底しておりますので、まず、職員から漏れるというようなことは考えておりませんけれども、そういう事象が起きた場合には。","id":"exchange-043"},{"speaker":"吉田委員","kind":"質問・要望","question":"でも、ミスは起きる。使われ方の報告が、昨年の１２月２１日号の区報と、品川区のホームページ、平成２７年度決算のあらましの一部に掲載されたということで、確認をいたしました。ここからが質問なのですけれども、ここに書いてあるのは、２０１５年度に徴収された１億６６６万円の使われ方だけではないでしょうか。何か、きちんとしたご報告をいただきたいと思いますが、いかがでしょうか。","respondent":"秋山財政課長","answer":"１０年間分を、１０億円余になるわけですけれども、それを５年間の防災の予算に使うですので、そちらの防災の予算につきましては、１年間を見ただけでも、防災の費用というのは１０億円を超えているわけですから、その中で使っているということは。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"９２ページの民生費補助金に入っていると思っています。子どもの貧困対策関係でお伺いします。ちょっとどこに入っているのか教えていただきたいのが１点です。子どもの未来応援プロジェクト検討委員会が設置されて、今度、学習支援、こども食堂など、取組みが始まろうとしていますが、検討委員会はどのような組織なのか、教えてください。子どもの貧困はどこで取り組んでいくのか、合わせてお聞きいたします。","respondent":"廣田子ども家庭支援課長","answer":"子どもの貧困の対策をどこでやるかというお話なのですけれども、子どもの貧困対策というふうによく言われておりますけれども、子どもが貧困なのだということではなくて、親の自立支援、親の低所得とか、さまざまな問題がありますので。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問・要望","question":"連絡会議ということですね。自治体が本気で貧困問題を掘り起こして、その解決のために目標を設定し、事業を展開する必要、私は一大事業と考えていますが、ちょっとご所見を、この点、聞かせていただきたいのが１点です。やはり、国がこの法律をつくったのですから、財政面でもしっかりとつけていかなくてはいけない。地方からも求めていかなければいけないと思いますが、いかがでしょうか。","respondent":"廣田子ども家庭支援課長、伊東生活福祉課長","answer":"子どもの貧困についてということなのですけれども、この子どもの未来応援プロジェクトの中では、貧困だけではなくて、孤食であるとか、子どものさまざまな生活環境による影響も鑑みながら。子どもの貧困と言いますか、生活困窮者自立支援法が制定されたのが２年ほど前ですけれども、そのときから、子どもの支援というところでは、補助率が２分の１というような形で始まったものでございまして。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっと、終わりのほうがよくわからなかったのと、ぜひ、国の責任として、国に求めていってほしいというところに力を入れたので、ここを答えてください。","respondent":"伊東生活福祉課長","answer":"先ほどの、１０分の１０というところで、ここの予算のところではないのですけれども、別のところで、都からの補助金として、我々のほうでやっております、生活保護受給者世帯向けの塾代補助、そちらに関しては１０分の１０という形で実施しています。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問・要望","question":"全庁的な推進体制を求めています。全庁的に、福祉支援策の周知をしていただきたいと思いますが、いかがでしょうか。これが１点です。学校は１日、子どもたちが過ごす場所です。学びの場でもありますし、さまざまな、子どもたちの様子が分かる場所でありますので、ぜひ、学校に、スクールソーシャルワーカーを配置して、子ども、そして保護者の支援にあたっていただきたいと思いますが、いかがでしょうか。","respondent":"廣田子ども家庭支援課長、村尾教育総合支援センター長","answer":"平成２９年度につきましては、さらに深めていくということで、メンバーの中に、教育委員会の中では、今まで、経済的支援ということで学務課長しか入っておりませんでしたが、教育総合支援センター長。現在、ご案内のとおり、品川区においては、学校支援チームＨＥＡＲＴＳに、ソーシャルワーカー４名を配置し、日々、各学校からの要望に従って訪問し、時には保護者、また児童等とも面談をしながら、貧困だけではありませんけれども。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"確認","question":"本気で取り組んでくださっていること、拡大をしていくということで、ぜひ、子ども未来部の所管のところだけではないですよね。そういったところを、もう１回ちょっと確認をさせてください。","respondent":"廣田子ども家庭支援課長","answer":"メンバーでは、福祉部生活福祉課は子どもだけを対象としている部署でもございませんし、自立支援につきましては、親の就労支援というところも大きな柱となっておりまして、就労支援の部分につきましては、商業・ものづくり課の力も借りておりますし、検討の段階で。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ、分科会の動きなども、これから、議会のほうにご報告をしていただきたいと思います。そういった面で、ぜひ、教員以外のこういった職員の配置を、ぜひ充実をさせていただきたいと思うので、もう１回お答えをいただきたいと思います。","respondent":"村尾教育総合支援センター長","answer":"福祉とのつながりということは、まさにスクールソーシャルワーカーの業務の１つでもありますので、例えば、主任児童委員会に参加したり、また、療育支援ネットワークに参加したりということで、さまざまな形でネットワークを広げながら、保護者の支援のほうには努めてまいります。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いかがでしょうか。貧困の連鎖を断つというのが、この法律の大きな目的でもあるのですが、１８歳以上の生活保護世帯も含めて、貧困家族の子ども、また、養護施設などを卒業した方の大学進学を支援する方策が、とても狭まれていて、なかなか困難だという声を、いっぱい相談も受けているのですが、都と区と連携をして、ぜひここのところの方策を考えていただきたいのですが、いかがでしょうか。","respondent":"廣田子ども家庭支援課長、伊東生活福祉課長","answer":"１８歳以上の学習支援、大学進学の支援につきましては、まさに今回取り組む学習支援事業にも入っているところです。今、課長が申し上げたとおり、大学進学に関しては、現時点では、我々のほうでは、いろいろなメニューを示して選択していただいているという状況で、直接的な支援というのは、まだ整っていない状況ですが、今後。","id":"exchange-051"},{"speaker":"渡部委員","kind":"質問","question":"１５９ページの議会費をやりますので、局長、よろしくお願いします。それと、１５４ページの特別区債のところでやりますけれども、先に、特別区債のところで、小学校の校地取得で、後地小学校ほか３校ですね。特別区債をどういうときに起こすとかというのは、うちの幹事長にちょっと習いまして、勉強してきたのですけれども、これ、後地小学校ほか３校という、３校を、まず教えていただければと思います。","respondent":"品川庶務課長","answer":"後地小学校を除く３校ですが、大井第一小学校、延山小学校、鮫浜小学校です。","id":"exchange-052"},{"speaker":"渡部委員","kind":"質問","question":"教育費のところを見ると、その３校は名前が出ていて上がっているのだけれども、後地小学校という名前が消えているのは、なぜなのですか。後地小学校が何か特殊な事情があって、起債してここには入っているけれども、歳出のほうであらわれてこないのでしょうか。","respondent":"品川庶務課長","answer":"後地小学校のほうは、現在、校庭の用地が一部国の用地になっておりまして、現在、国と交渉をしている最中です。ほかの３校につきましては、交渉のほうを終えまして、現在、公社のほうで買取りをしていまして、今年度、確実に行けるということで、歳出に計上しております。","id":"exchange-053"},{"speaker":"渡部委員","kind":"質問","question":"わかりました。そうしますと、今回、ここで、特別区債で４校分出ています。歳出のほうは３校で、１校は事情がわかりましたけれども、区債が結局、この金額、どういうふうな形で戻ってくるのか。４校一括で財調算定がかかってくるのか、どういうふうに分かれて返ってくるのか。後地小学校の関係。まだ最終的な国との調整が途中なのだけれども、どういう形で進んでいく予定なのか。","respondent":"秋山財政課長","answer":"特別区債ですけれども、一応、１４ページでお示ししていますように、２５年以内ということで、起債の方法を考えているものです。ただ、これから先、具体的に今、シミュレーションはしておりますけれども、実際に細かい設定につきましては、利率等は今後の検討です。","id":"exchange-054"},{"speaker":"渡部委員","kind":"確認","question":"２５年の話、今、確認しました。でも、これ、学校用地というのは、例えば隣接地。接地しているところで、例えば今後も改築等が進んでいくのかなと思うのですけれども、そういうたびに、起債していく可能性があるのかどうか。どんどんそれが足されていくのかどうか。その辺の考え方を教えてください。","respondent":"秋山財政課長","answer":"教育債に関しましては、起債を行いまして、その返済分と言うのですか。については、財調算定に算入されるということで、今、教育債については、学校用地とか教育債で使えるものについては、なるべく教育債を活用して買っていこうという方針です。","id":"exchange-055"},{"speaker":"渡部委員","kind":"質問","question":"済みません。実は、ごみ屋敷だったから、ブロック塀とかがもうへこんだりというような形になるのだけれども、こういう所というのは、とりあえず買うのか、何か活用しようと思って買うのか、どのような形のお考えがあったのか。もし教育委員会のほうでわかるのであれば、例えば、ここを購入した後、使い道とかが何かあるのであれば、それを教えてほしいと思います。","respondent":"品川庶務課長","answer":"延山小学校の隣接地ですが、まだ、具体的に学校のほうでどのように使うかというのは、現在検討中ですが、例えば、学校で畑に使うとか、物置に使うとか、いろいろと用途のほうはありますので、その辺も学校と調整をしながら進めていきたいというふうに考えております。","id":"exchange-056"},{"speaker":"渡部委員","kind":"質問・要望","question":"よろしくお願いします。一生懸命片づけた土地なものですから、有効活用していただきたいと思います。１５９ページです。この分厚い予算書で、たった１行、議会文書等共有システム導入経費。これは本当に、議会が議会改革の一環の中で、２年間、議員同士で議論させていただきました。はこの数字、７７１万４,０００円を、どのような形で経費がかかっているのか、ばらしてほしいと思います。","respondent":"品川庶務課長、原区議会事務局長","answer":"済みません。先ほどの答弁のほう、訂正させてください。後地小学校の用地につきましては、歳出のほう、３９５ページのほうで計上していますので、４校とも歳出のほう、計上しています。スケジュール感につきましては、６月、７月ぐらい。これは、いろいろ環境整備が伴いますので、そういった調整をしながらという予定ではありますけれども、６月、７月ぐらいということで、想定をしています。","id":"exchange-057"},{"speaker":"渡部委員","kind":"質問","question":"私たち議会としても、どういうものを入れてほしいというのも、お願いをしまして入れていただくのですけれども、ましてこれ、委員会等で活用するとなると、当然、理事者の皆様にも同じものをお持ちいただかなければなりません。それが１点。新しい端末で、新しいソフトを使うわけですから、これは実は、行政側の方々も一緒でございまして、行政側の理事者の方々、どのような形で、やはり研修をやっていくのか。","respondent":"原区議会事務局長","answer":"そういった意味では、操作等々については、当然のことながら、なれていただくための手法についても相談をしていきたいと考えていますし、また、端末等についても、議会の環境と、区長部局の環境が若干違うところがありますので、そういったところを考慮しながら、双方が。","id":"exchange-058"},{"speaker":"渡部委員","kind":"質問・要望","question":"附箋も張れるし、メモもとれるしというような、これから品川区議会が一気にＩＣＴ化されますので、どうか皆様方、一緒に協力いただきたい。とりわけ、資料等に関しましては、ほとんどの資料がそこに入ってくるものですから、僕らも常に何でも勉強しながら臨める体制になっていくことを祈って、この質問は終わりにします。ちょっと時間があります。昨日聞き残したことを少しだけ教えてください。","respondent":"黒田税務課長、提坂戸籍住民課長","answer":"給与報告書の未記載のところについてお答えいたします。通知カードを拒否された方の数というお尋ねでよろしいでしょうか。","id":"exchange-059"},{"speaker":"あべ委員","kind":"質問・要望","question":"内容のほうに行きます。そしてまた１３４ページの財産貸付収入についてもお伺いしたいと思います。これは、平成２９年度はどの程度の影響と見込んでいるでしょうか。それから、住宅の使用料に関連してなのですけれども、これ、ここで伺うのが妥当かどうか、私もちょっとわからなかったのですが、孤立死というものが問題となっております。契約の金額についても確認させてください。教えてください。","respondent":"原区議会事務局長、黒田税務課長、秋山財政課長、今井住宅課長、立川経理課長","answer":"これは、先ほどもご案内させていただきましたけれども、議会だけではなく、区長部局との連携、こういったところが大変重要となってきますので。これは、課税額自体が見込みに行きませんと、収入に対して、歳入の欠損が出るということもありますので、全体的に、そういったところで、歳入のほう。法人住民税の国税化の影響ですけれども、平成２９年度は、２３区全体で６２８億円というふうに見込んでいるものです。","id":"exchange-060"},{"speaker":"あべ委員","kind":"質問・要望","question":"ふるさと納税なのですけれども、これは単にそれぞれの自治体で減収というようなことだけではなくて、今、使われ方として、特に富裕層の節税対策として使われている面が非常に強いということで、そういう意味では、税制というものに対して、非常に悪影響と言いますか、公平性が失われるような形で使われているということですので、単に金額だけではなくて、ぜひこの制度そのものについて。","respondent":"秋山財政課長、今井住宅課長、柏原企画調整課長、立木産業活性化担当課長","answer":"ホームページ等で、お出しはしておりますけれども、それをもっとわかりやすくですので、決算等、いろいろな機会を捉えて。孤立死の影響で、建物に損害を与えた場合ですけれども、幸いにして、今回の事例はそういうことはありませんでした。旧第一日野小学校跡地とＴＯＣ等々の関係ですけれども、こちらにつきましては、お貸しする前提のところが。剰余金に関しましては、年度末、しまった段階で、指定管理者とともに分配配分等を検討する予定となっています。","id":"exchange-061"},{"speaker":"あべ委員","kind":"質問・要望","question":"大崎ブライトコアのほうです。放っておいても２億円ですから、剰余金はぜひ出していただきたいと思っているのですけれども、当然、２億円にはならないと思います。あの施設を使うことによって、どれだけ地域経済が活性化したか、企業に還元できたかというようなことも、経済効果の波及効果というのも、ぜひ、どこかの時点で計測していただきたいと思いますが、いかがでしょうか。","respondent":"柏原企画調整課長、立木産業活性化担当課長","answer":"第一日野小学校の土地をお貸しした際に、ＴＯＣの本社の建替えというところが、まちのにぎわい、それから地域経済の活性化の継続というところで、大きく影響を受けるだろうといったところがあったというところで。ＳＨＩＰの経済波及効果につきましては、いろいろな切り口から、これから、さまざまな面から検証してまいりたいと思います。","id":"exchange-062"},{"speaker":"あべ委員","kind":"質問・要望","question":"ＴＯＣ、大崎では、まちのにぎわいに対してマイナスの効果を与えているということを、ぜひ勘案して、そのこととセットで議論していただきたいと思っています。もう一度、答弁をお願いします。","respondent":"柏原企画調整課長","answer":"五反田のまちの活性化と、そういったところを視点にしながら、ＴＯＣとは協議していきたいと思ってあります。","id":"exchange-063"},{"speaker":"塚本委員","kind":"質問","question":"これは、とりもなおさず区民税の減収ということにつながっていくのかと、このように想定ができるのかなと思うのですけれども、こういった事態を、ある程度、今この人口ビジョンの中で想定されている中で、行政需要は増えるけれども、財源は減っていくのではないかという事態を見据えた中で、区としてどのような対策、必要だというふうに考えていらっしゃるか、お伺いをさせてください。","respondent":"柏原企画調整課長","answer":"税収との関係ですけれども、この生産年齢人口の方々に、いかに品川区に入っていただくか、そして住み続けていただけるかといったところがポイントであろうというふうに捉えてございまして、先ほども議論ございましたけれども、こうした生産年齢人口の方々への施策ということで。","id":"exchange-064"},{"speaker":"塚本委員","kind":"質問・要望","question":"何年、何年という形で、増減ということで。こういう変化が、１０年、２０年後ぐらいで起こってくる中で、区有施設の行政の用途というのを変えていかなければいけないというようなことが、１０年、２０年後ぐらいにいろいろ出てくるのではないかというふうに予想されるのですけれども、こういうことについて、区としてどのような対応を、今、考えて、対策を考えていらっしゃるのか、お伺いさせてください。","respondent":"柏原企画調整課長","answer":"改修や大きな改築、新築というようなときには、そういった多機能、多様、多目的のほかに、先を見た中で、転用であったりだとか、そういったことも視野に入れながら、施設のあり方というのを考えていきたいというふうに考えているものです。","id":"exchange-065"},{"speaker":"塚本委員","kind":"質問","question":"今、複合化という、ちょっとお話と、転用というお話もありましたけれども。そういう考え方と、どちらかと言うと、後者のほうが今後の時代には向いているところもあるのかななどというふうに、私も思ったりもするのですが、そういうところについては、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"一概に全部転用というわけではなくて、やはりその施設の今の状態であるとか、ニーズというのを考えながら、その施設に対しては、個別の検討を入れながらということになろうかと思います。","id":"exchange-066"},{"speaker":"塚本委員","kind":"質問・要望","question":"動きと言うか、厚生労働省からの話があるという中で、また、日中一時預かりのほうにつきましては、今年、区としても、定員がしっかり満たせるように手を入れていくというようなお話も、ちょっと伺っております。","respondent":"中山障害者福祉課長","answer":"放課後等デイサービスについては、特に療育を目的と考えております。一方で、親御さんの就労支援、あるいはレスパイト支援といった預かりの視点からは、この日中一時支援であるにじのひろばのほうを活用していきたいというふうに考えているところです。","id":"exchange-067"},{"speaker":"塚本委員","kind":"質問","question":"今、療育目的でのデイと、それ以外。それ以外と言ってしまっていいのか、日中一時支援というような考え方だというふうに受け止めましたけれども。そういうことでいくと、日中一時支援の費用負担のところが、どうしてもやはり、すまいるスクールと比較すると、大きな開きがあるかと思います。この日中一時支援の負担軽減につきまして、より一層、ぜひ進めていく必要があるかなと思いますが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"利用料自体は変更はないのですけれども、保護者の方の所得層に応じて、上限額をそれぞれ、例えば、低所得であれば負担がゼロ。それから、住民税所得割が２８万円以下であれば、月々の上限が４,６００円。","id":"exchange-068"},{"speaker":"塚本委員","kind":"質問","question":"いずれにしても、この格差、障害のあるなしにかかわらず、格差を感じないということでの、今、施策の前進、お伺いさせていただきましたので、今後ともそういった考えに沿っての、この日中一時預かり、放課後一時預かりについては、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"西本委員","kind":"質問・要望","question":"知事のほうが挙げております、３つのシティですね。それぞれの中で、特にちょっと気になる点、確認したい点を質問したいと考えています。それによって、区の財政の割合はどうなってくるのかも含めて、ご質問したいと思います。かねてから、私のほうで、ＬＥＤはもう早く促進していかないと間に合いませんよということをお話をして、要望させていただいて、庁舎内、それから区内施設の交換が始まっております。","respondent":"秋山財政課長","answer":"ご指摘になりました東京都の予算案でありますけれども、これは東京都の平成２９年度予算案でありますので、まだ議決をされたわけではございませんので、総論から言えば、品川区の平成２９年度予算には反映されていないというようなお答えになろうかと思います。","id":"exchange-070"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、考え方を教えてくださいと言っているわけであって、金額を教えてくださいとは言っておりません。なので、待機児童の問題もありますし、それからＬＥＤの問題も、過去においては、推進をしてくださいということを、私は要望しておりますので、こういう動きがあります、だから、うまく使ってくださいね、それによっての品川区の考え方はどうですかと聞いておりますので、それをお答えください。","respondent":"秋山財政課長、佐藤保育課長、大澤待機児童対策担当課長、三ツ橋環境課長、多並道路課長","answer":"それぞれの考え方は、所管から述べさせますが、私どもとしましては、平成２９年度予算の中で東京都議会で議決された後には、それに基づいて。反映していない事業に関しては、例えば、病児保育の整備であれば、実際に事業所がありませんので、こういった事業所が出てきた場合は。待機児童の解消につきましては、今、ちょうど入園審査の時期でございまして、平成２９年度の待機児童の状況がまだ出ていませんので。","id":"exchange-071"},{"speaker":"西本委員","kind":"質問・要望","question":"ＬＥＤに関しては、やはり家庭のほうに広げていかなければならない。今は、品川区としては、オリンピック・パラリンピックに関連する事業が中心でしょうけれども、これから本当に技術の革新が始まろうとしている中で、うまくそれを利用して、活用して、品川区も達成していただきたい、推進をしていただくようにお願いして、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"渡辺委員","kind":"質問","question":"お願いします。私は、９３ページ、シティプロモーション推進経費に関すること。１１７ページ、出産・子育て応援事業、認知症高齢者の支援とケアの充実ほか１９事業。このあたり、大きく３点伺います。第３回が、１２３の自治体が参加したと。平日開催なので、これは自治体間の連携ということで、平日なのだというのは、とても理解をしています。どのくらいの規模の行事になるのか、まずそこを教えてください。","respondent":"中島企画部副参事","answer":"過去、いろいろ聞きましたところ、５００、６００ぐらいの人数的なものも、過去あったということも聞いておりますので、品川区といたしましては、やはり、きゅりあんの大ホールも活用して行いますので、それが盛況と見えるような形の人数規模を目指していきたいと考えています。","id":"exchange-073"},{"speaker":"渡辺委員","kind":"質問・要望","question":"ちょっと場所のことを伺っていなかったのですが。それなりの数字ですよね。これは別に、地域の専門的ではない方に押しつけるものではなくて、まず軸となる、行政ですとかの考え方がある、要望があるべきと思っているのですね。このシビックプライドをキーワードの軸に据えたときに、地域力向上に結びつくというのは、よく言われる、自助、共助、公助のところで、一番求められる共助のところ。","respondent":"中島企画部副参事","answer":"シティプロモーションサミットと、シティプロモーションに今、取り組んでいる施策の考え方、あとシビックプライドについてのお尋ねだと思いますが、シティプロモーションのほう、地域の魅力をさまざまな形で掘り起こして、磨いて、メディアを通じて発信しています。","id":"exchange-074"},{"speaker":"渡辺委員","kind":"質問・要望","question":"やりたいところもいっぱいあるでしょうから、チャンスだと思います。職員の参加の方法とか、あるいは同時に、平日ではありますが、区民の参加のこと、そして交流をどう生かしていくか、教えていただきたいと思います。やはり、品川を知っていただく中で、ランチですとかお弁当だとか、夕食、あるいはしながわみやげ、これをどんどん仕掛けていただきたいと思いますが、この辺合わせてお願いします。","respondent":"中島企画部副参事","answer":"確かに、１０月の平日の開催ですので、参加できる方々の制約等もあろうかと思いますが、できる限り、職員ならびに区民と、これからつくり上げられるかどうかを含めて、詳細のプログラムを検討してまいりたいと考えています。","id":"exchange-075"},{"speaker":"渡辺委員","kind":"提案","question":"職員の方の参加、特に力を入れてやっている、通常業務もありますが、やるべきだと思いますし、区民の参加の仕方、これは今、確定していないと思いますが、方向性だけ、やはりこの日にかけるという強い意識を、最後、表現していただけると、私たちも応援しやすいなと思いますし、いろいろな、これから知恵を、企画を求めて、まだ１０月ですから、肉づけがいろいろできるのではないかなと思うので、その点。","respondent":"中山企画部長、永尾高齢者福祉課長","answer":"シティプロモーションサミットへの決意ですけれども、基本的な認識として、品川の魅力を発信する場として、品川の持っている多様性とか、地域の元気というものをキーワードに、発信していく場にしたいと思います。それは、やはり、いつ実施されるのかわからなかったりだとか、場所がわからないと、利用することもしづらいということなので、定期的に、少なくとも月に１回以上、同じ曜日、同じ時間でやるようにという条件をつけた上で。","id":"exchange-076"},{"speaker":"のだて委員","kind":"質問","question":"私からは、１０２ページの就学援助費と、１４２ページの奨学金貸付金返還金に関連して質問します。就学援助についてですが、国からの補助金は、今年度１６２万円から、来年度１８９万円に、やや増額されました。その理由をまず伺います。","respondent":"有馬学務課長","answer":"就学援助費そのものは、昨年と同じ６０万円となっておりますけれども、特別支援教育就学奨励費につきましては、人数の見込みが増えるだろうということで、人数の増になっている関係で、この金額が増えているものです。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問・要望","question":"しかし、事業総額の約０.４％しか、国から補助金が来ていないという状況です。準要保護世帯の支給額も、同様に引き上げるべきだと思いますが、いかがでしょうか。来年度の就学援助の対象になる基準は、どうなるのでしょうか。現在、生活保護の基準に１.２５倍した額を対象にしていますが、これまでの、平成２５年度の基準額から、引き下げないでいただきたいと思いますが、いかがでしょうか。","respondent":"有馬学務課長","answer":"制度自体の支給の基準ですけれども、来年度につきましては、従来どおり、保護世帯の１.２５倍というのを基準として、支給を行っていく考えです。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問・要望","question":"対象の基準額は引き下げないということで、安心しました。今後も、この基準は引き下げないよう、要望しておきたいと思います。そして、準要保護については、要保護と同じ額に引き上げないということでしたけれども、金額が実態よりも少なくてもよいということなのでしょうか。なぜ引き上げないのか、伺います。","respondent":"有馬学務課長","answer":"その分につきましては、もう既に、今回改定となりました、小学校で言いますと４万６００円、中学校で言えば４万７,４００円というものが、既に生活保護費のほうで支給されておりますので、実質的な影響はないものと考えています。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問・要望","question":"要保護では、生活保護のほうで実施しているので、実質的な影響はないというお話でしたけれども、私が求めているのは、準要保護の引き上げを求めていますので、いかがでしょうか。","respondent":"有馬学務課長","answer":"そういう意味では、これは慎重に検討すべきだと思いますし、もともとが財調単価で計算をしておりますので、財調単価の推移を見ながら、それは検討していくものだというふうに判断しているものです。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問・要望","question":"準要保護については、先ほどご説明もありましたけれども、国の補助が、平成１７年度までに廃止されて区の単独になりましたけれども、やはり、どの子も教育を受けることを保証する重要な事業ですので、国に補助金の再開を求めていく必要もあると思いますけれども、いかがでしょうか。","respondent":"有馬学務課長","answer":"そのときの、文部科学省の通知ですけれども、釘を刺すかのように、要するに、準要保護にかかる支援については、三位一体改革によりまして、もう決着済みですよというような話がついておりますので、今の段階でこれをくつがえしていくのは。","id":"exchange-081"},{"speaker":"のだて委員","kind":"質問・要望","question":"今の段階では難しいというお話でしたけれども、粘り強く求めていっていただいて、準要保護の引き上げをやっていっていただきたいと、要望しておきます。次に、新入学学用品費、いわゆる入学準備金の入学前からの支給についてです。今、全国で入学前支給が始まっています。２３区内でも、既に始めているところ、そして導入を検討しているところなども含めて、どこが進めているのか伺います。","respondent":"有馬学務課長","answer":"正確には把握していないところですけれども、２３区におきましては、板橋区、それから世田谷区が、既に支給しているです。それから、平成２９年度の支給に向けて数区。それから、今後検討していくということが数区あるというふうなことで、その動向をつかんでいるところです。","id":"exchange-082"},{"speaker":"のだて委員","kind":"質問・要望","question":"２３区内でもこれだけの区が導入へ動き出しています。昨年の決算特別委員会で、入学前支給を求めた際に、区は少し検討したと。入学前からの申請と、入学後の申請もすれば、不公平、つまりは受けられるはずだった人が受けられないということはないと思いますが、いかがでしょうか。","respondent":"有馬学務課長","answer":"２３区の中では、６年生のときに一旦認定し、また、中学１年になったときに、これは事後払いになるけれども、もう一度その時点で認定せざるを得ないのではないかなというような、２回に分けて認定するというようなことも、そういうことも一緒に検討していますので。","id":"exchange-083"},{"speaker":"のだて委員","kind":"質問・要望","question":"中学校、６年生の段階だけでなく、小学校も入学前からの支給をしていただきたいと思います。特に、品川区では、小中一貫校で、小学校から制服が必要にもなってきますので、お考えを伺いたいと思います。奨学金についても伺います。返還金が、来年度４５４万円減額されていますが、その理由を伺います。給付型奨学金について研究していくと、この間、答弁ありましたけれども、その研究成果はいかがでしょうか。","respondent":"有馬学務課長、廣田子ども家庭支援課長","answer":"基本的には、前年度の所得、それから既に区民であること、公立の学校に入ること、ということの３つの条件がありますので、そこは、まだまだ検討の余地があるだろうというふうに思っております。給付型の奨学金については、検討するというご答弁をした覚えはございませんけれども、奨学金の今後のあり方については、今年度、考えていこうと考えています。","id":"exchange-084"},{"speaker":"のだて委員","kind":"質問・要望","question":"小学１年生からの入学前の支給というのは、まだまだハードルが高いということでしたけれども、ハードルは越えていくものだと思いますので、ぜひ、進めていっていただきたいと思います。奨学金については、研究成果をお聞きいたしました。そして、今年度、研究していくというお話でしたけれども、もう少し詳しく伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"いろいろ情報収集をさせていただいているところですけれども、その結果に基づきまして、子どもの未来応援プロジェクトでありますとか、奨学金運営委員会の中でお諮りしていくような予定ですので、そちらの検討が済んでから。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、情報収集で検討しているということでした。お子さんは公立高校に入学し、授業料を払わなくてよいということになっていますけれども、教科書や積立金、生徒会費など、月１万７,０００円の出費があり困っているという声が寄せられました。そういった方への支援のためにも、この給付制奨学金、必要だと思います。ぜひ、進めていっていただきたいと思いますが、改めてご答弁願います。","respondent":"廣田子ども家庭支援課長","answer":"授業料以外の負担という部分では、課題と考えておりますので、今後の検討の中でも取り上げていきたいと思っています。","id":"exchange-086"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは、１５１ページの自治振興宝くじについてと、税外収入について、それと、１０１ページをはじめとする無電柱化事業について、８９ページの生活保護費について、お伺いをしていきます。そこにぜひ、皆さんのお力もお貸しくださいと。無電柱化ですが、今まで品川区は、この無電柱化について調査というものをされたことがあるのかどうかだけお伺いをします。よろしくお願いします。","respondent":"伊崎地域活動課長、柏原企画調整課長、多並道路課長、伊東生活福祉課長","answer":"事業の実施主体自体は、一般コミュニティ助成事業に関しましては、区市町村または区市町村が求めるコミュニティ組織となっておりますので。ネーミングライツの部分です。区のほうでも、これまでもいろいろお話をいただきながら、ネーミングライツのほう、検討はしてきたです。区道としましては、９.２キロメートル、約３％の整備を進めてきたところです。起訴されますと、廃止というような形をとっているところで、その瞬間ごとに停止・廃止としているところで、支払い方法に関しては。","id":"exchange-087"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"宝くじの件ですが、ほかの２３区でも、おみこしの整備等で、町会が申請をして助成を受けているところもありますので、品川区が一括してというお話もありましたが、ぜひ、そういったことを周知をしていただいて、もし求める町会があったら、ぜひ手を差し伸べていただければと思いますので、これは要望で終えます。税外収入、ぜひ取り組んでいただければと思います。","respondent":"伊東生活福祉課長、安井土木管理課長","answer":"来ない場合であっても、こちらからの問い合わせに関しては、警察のほうも回答していただけますので、その時点で、しっかりその後のことを考えていくというような形の、そういうシステムになってあります。いわゆる、そういった新しい看板なのですけれども、今現在のところでは、屋外広告条例にひっかかるという扱いになっているですので、その辺が、都のほうでどういうふうに扱いを改めるか。","id":"exchange-088"},{"speaker":"石田（し）委員","kind":"質問","question":"ひっかかるという、無電柱化の件ですが。でも、そうなのですかね。パナソニックは、もうこれ、社会インフラとして、そういった技術を一般に公開をしています。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"藤原委員","kind":"確認","question":"１点だけ確認します。よく理解できなかったので。石田しんご委員の質問の中で、自治振興宝くじのコミュニティ助成の件で、おみこしにも出るのですか、出ないのですか。","respondent":"伊崎地域活動課長","answer":"こちら、先ほど申し上げましたように、一般財団法人自治総合センターの補助金でございまして、対象となる物品の詳細につきましては、その都度のご相談となっていると承っておりますので、今、この段階では、出るとも出ないとも、お答えを申し上げられません。","id":"exchange-090"},{"speaker":"伊藤委員","kind":"質問","question":"私は、１２９ページの学校地域連携推進経費に関連をして、それから１５２ページの観光インフラ整備支援助成金に関連して質問します。その後、組織化をしていって、具体化をしていくというふうに、ある程度、計画性を持っていかないと、スクールコーディネーターは定着していかないと思うのですが、品川区の見解をお聞かせください。","respondent":"熊谷指導課長","answer":"段階的に、ご説明を丁寧にしながら、進めていきたいと考えております。","id":"exchange-091"},{"speaker":"伊藤委員","kind":"質問","question":"地域と学校をつないでいくということ。これだけでも、結構時間がかかるわけであって、それを定着していくと、さらにまた時間がかかっていくわけだから、そういう、もう少し具体的な年度の計画と、それから、これを展開するにあたっては、ぜひ、品川区内でも連携をとっていただいて、地域活動課とか、さまざまな地域と連携をとっていただいて進めるべきと考えるのですが、いかがでしょうか。","respondent":"熊谷指導課長","answer":"既に今年度におきましても、町会長会議等で全て回りまして、ご説明をしてきたところでありますけれども、これからも、広報しながわ等で周知をしていくことも重要だと思いますし、引き続き丁寧に説明をしていきたいと考えます。","id":"exchange-092"},{"speaker":"伊藤委員","kind":"質問","question":"お願いしたいのですけれども、丁寧な説明の仕方というのが、町会長会議に行っただけでは、進まないと思うのですよ。だって、地域の大きな連携を必要とするわけでしょう、この事業は。それはもちろん、町会も必要なのだけれども、それぞれの地域の、例えば、場合によっては神社やお寺もあるでしょうし、いろいろなケースがあるわけではないですか。答弁をお願いいたします。","respondent":"伊崎地域活動課長","answer":"地域センター等を通しましても、地域の方がコミュニティ・スクールにご理解をいただき、また、ご協力いただけますように、指導課とともに、教育委員会とともに、お願いをしていきたいと考えております。","id":"exchange-093"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ぜひ、連携をとっていただいて、非常にすばらしい目的をやろうとされているわけですから、まとめていくと、計画的に、説明を丁寧にしながら、もう地域の総力を集めた仕組みをつくってくださいということを、お願いをしておきます。次のステップとして、ここから出てくるさまざまなアイデアを具体化していく、これがまさに品川区に求められている作業なのですよ。ご見解をお聞かせください。","respondent":"鈴木文化観光課長","answer":"区としては、大規模な組織改正は、３、４年程度に一度行っておりますので、文化観光課だけではなくて、全体の、区の中の改編の中で、しっかりと検討していけたらというふうに考えております。","id":"exchange-094"},{"speaker":"伊藤委員","kind":"提案","question":"そのことを考えていくと、私はやはり、過渡的な経過でいいのでしょうから、観光というものだけ、やはり独立した形で、品川区が集中的に協議をして、具体化して制度化していく。観光振興協議会をつくって、さまざまな部会をつくって、提案をいただいた。品川区全体としてやっていくわけだから、やはりそこのところ、もう少し補強してほしいなと思うのですが、いかがでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-095"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは、１０１ページの避難道路機能強化事業、もう１つが、１１６ページの子ども・若者自立等支援体制整備事業補助金、この２つをお聞きしたいと思います。どちらの補助金についても、簡単に、主な事業をお知らせいただきたいと思います。道路も、それから子ども・若者支援も、両方お願いいたします。","respondent":"寺嶋木密整備推進課長、高山子ども育成課長","answer":"避難道路機能強化事業補助金の内容について、ご説明いたします。こちらは、東京都が避難道路に指定した滝王子通り、これの拡幅整備事業に対する補助金でございまして、国と、それから東京都のほうから、補助金の交付があります。私のほうからは、東京都の子ども・若者自立等支援体制整備事業につきましてのご説明をいたします。","id":"exchange-096"},{"speaker":"こんの委員","kind":"質問","question":"品川区としては、もう既に無電柱化を進めているのですが、避難道路の機能強化のために、無電柱化をさらに進めていくべきであるという考え方から、どこから今後進めていくのが大事かなというふうに考えているところです。もう１つは、桐畑隧道のトンネルを利用する。この３つしかないのですね。この３つが遮断されてしまうと、逃げ道がない。これは必要であるというふうに考えますけれども、いかがでしょうか。","respondent":"多並道路課長","answer":"国が研究しているところもあるのですけれども、東京都でも、今年、平成２９年１月に、新たに低コスト化の検討をする会を設置いたしまして、東京都でも新たに取り組んでいくということが、話ではありました。","id":"exchange-097"},{"speaker":"こんの委員","kind":"質問・要望","question":"これからそうした東京都の動きもある中で、ぜひ、そういうのを活用して考えていっていただきたいと思います。こうしたものへの強化についても、ちょっとお聞きしておきたいと思うのですけれども。区としても、この海抜表示板あるいは避難ビルを誘導する標識、こうしたものを、今後、設置をしながら、夜間対応もしていくべきであると思いますけれども、いかがでしょうか。","respondent":"和田河川下水道課長","answer":"委員ご指摘のとおり、そういう蓄光をするような光が受けられていない場合は、真っ暗な場合は、光らないわけでありまして、この辺に関しましては、やはり、津波というのは夜間襲ってくる場合もありますので、その点も鑑みて、今後検討していきたいと考えています。","id":"exchange-098"},{"speaker":"こんの委員","kind":"質問・要望","question":"子ども・若者自立支援体制のほうは、先ほどお聞きしました協議会や計画、それから相談体制ということでありますので、そのほかにも、私、第４回定例会のほうで、青年期、特に高齢化したひきこもり対策についてお伺いしたときに、実態調査を求めてまいりましたけれども、その点についてはいかがお考えでしょうか。","respondent":"高山子ども育成課長","answer":"お尋ねの、品川区における実態調査という面で申しますと、２月の期間を設けまして、ライフスタイルに関するアンケート調査というのを実施しまして、こちらのほうで対象の年齢を広げまして、実態の調査について集計しているところ、調査しているところですので。","id":"exchange-099"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"８０ページ、８１ページの住民基本台帳証明手数料というところと、１３８、１３９ページの減債基金繰入金についてお尋ねします。以前、決算特別委員会でお聞きしたときに、大井町、武蔵小山サービスコーナーでの取扱いの割合、どれぐらいなのかというふうにお尋ねしたとき、１５％程度ということでしたが、近々の資料では、どのような数字でしょうか。","respondent":"提坂戸籍住民課長","answer":"取扱い件数の割合と、ほぼ同じです。","id":"exchange-100"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"サービスコーナーで働いている方々は、いつも暇そうにしているなどという、大変厳しいご批判があって、それを区のほうにお伝えしたところ、サービスコーナーを民間事業の方々に委託するべきと、区の顔でもあるサービスコーナーですからということで、法律上、何か問題があるのかということをお伺いしたところ、当時の戸籍住民課長から、「住民票の証明というものについては、法律上の制約はございません。","respondent":"提坂戸籍住民課長","answer":"請求に関する交付、あるいは不交付の決定、それから、請求内容に対する審査ですね。照合ということも含めるのですけれども。その辺は、区の職員がしっかりと責任を持って行わないといけないということで、人員の体制とか、その辺も踏まえて検討してきたところです。","id":"exchange-101"},{"speaker":"高橋（し）委員","kind":"意見","question":"いわゆる、委託業務の範囲の切り分けと、あと区のほうの職員の方の体制等も絡めて、どういうふうにするかということで、検討されたということです。それで、そういったことで、今回実現したわけでありますけれども、そのように検討された結果、効率化と、先ほどありましたけれども、人とそれから経費についての面で、どのような効率化があるのか、具体的にお話しいただければと思います。","respondent":"提坂戸籍住民課長","answer":"混み具合によって、その辺を、事業者の方にお任せして、人員の体制を組んでいただくということを考えております。","id":"exchange-102"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ちょっと金額とかは、またあれとしても。先ほどから、ほかの委員からも出ましたけれども、いわゆる個人情報の取扱いについては、本当に十分過ぎるほど、問題が起きないように、流出防止に配慮していただきたいと思います。最後に、こちらの件では、武蔵小山や、平成３０年の開設という目黒のほう、これを委託を拡大すべきだと考えておりますが、また４年ぐらいかかって実現するのでしょうか。","respondent":"提坂戸籍住民課長","answer":"目黒のサービスコーナーにつきましては、平成３０年４月にオープンを予定しておりますが、オープン当初より、大井町サービスコーナーと同じ形の民間委託を考えております。","id":"exchange-103"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"充当先が明確になっているのですが、どうして一般財源かということには、残念ながら説明がなかったです。そのような観点からすると、この減債基金繰入金の説明欄だけが空欄ということは、どうなのでしょうか。そのときに、わかりやすくなるような予算書を、ぜひ作成していただきたいと思いますが、この財政上の話で、ここに文言を入れると、統計上、何か差し障りがあるのでしょうか。見解を伺います。","respondent":"秋山財政課長","answer":"ですので、一般財源として使うことができる、使途が制限されないということが、国のほうで決まっておりますので、そういう意味から、ここに減債基金繰入金の説明欄には、何も書いていないです。","id":"exchange-104"},{"speaker":"高橋（し）委員","kind":"質問","question":"使途は制限されないのだけれども、充当先が決まっているのでありますから、ここに書いたらいかがですかというお話なのですけれども。","respondent":"秋山財政課長","answer":"一般財源である、です。","id":"exchange-105"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１３５ページ、先ほどもちょっと出ましたけれども、大崎再開発ビルの株式配当金と、それから、８３ページ、建築確認、それから、１５０ページ、宝くじでお願いします。多分、これは、我々も確認しますが、しっかり予算がついたならば、４月、５月ぐらいで執行してくれと。それから、建築確認なのですが、まず初めにお聞きしたいのは、建築に関する相談件数。そこからお願いします。","respondent":"稲田都市開発課長、鈴木建築課長","answer":"そういうところで、我々としては最短に進めてきたつもりなのですけれども、平成２９年６月から、区のほうで、まず道路に関する埋設管の整備等を行いまして、引き続き、もうすぐに警視庁が信号を立てて。建築相談の年間の件数ですが、相談内容、用途地域、あるいは道路、具体的な建築法規、さまざまですが、これらをトータルしますと、およそ２万４,０００件ほどです。","id":"exchange-106"},{"speaker":"石田（秀）委員","kind":"確認","question":"確認のほうなのだけれども、年間で相談が２万４,０００件あるとして、例えば、平成２８年の予算は６０件建築確認があって、平成２９年度は４２件、中間が１９が１３、完了が３０の１１というのが予算。決算だと３８、１２、２９となるのだけれども。そういう状況の中で、この状況の確認で、育つかというのは、すごく心配しています。この辺のところはどうお考えかというのを、お聞かせ願いたい。","respondent":"鈴木建築課長","answer":"こういったところが、難しいところが、窓口に相談件数が増えている要因でございまして。そうした難しい解釈、考え方については、確認申請の中だけではなくて、まさに事前相談として、日々、窓口で、設計事務所から受けているものです。","id":"exchange-107"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、その２万４,０００件も相談があるのなら、そこの部分については、そんな法的なもので、大分判断が難しいというのであれば、増員するべきだろうと思っています。どういうふうな仕組みになっているのかなというのを教えていただきたい。私は、そういう形のものを、こういうところからでもやっていくべきだと思っていて、その辺の考え方はどうされているのかというのを、教えてください。","respondent":"秋山財政課長","answer":"その指示を受けて、各所管では、課長からの指示がそれぞれにあって、いろいろ探しているというところだと思います。いろいろな、財団とか、いろいろなところがいろいろなことをやっているとなりますと、１つの指示だけで、なかなか、見つけられるというのは難しいと思います。","id":"exchange-108"},{"speaker":"石田（秀）委員","kind":"提案","question":"それは多分、区民の要望があったから、私も覚えていた。各所管の人たちに、そういう部分のことをして、これは、こういうことでも探していけよということを、きちんと習慣づけるということになると、その部分で２割前向きなことを考えていこうという頭があれば、ほかのことでも、こういうことをやりましょうという、新規政策なんかも、提案も、私は出てくると思っていて。見解をお聞きしたいと思います。","respondent":"秋山財政課長","answer":"そういうことに関しても、一方的に、財政のほうが、ただ見つけてこいと言うのではなくて、財政のほうにそういう情報があれば所管にも流しますし、所管からも、横の連携ですとか、そういうところも含めて連携をしていくということによって、まずは。","id":"exchange-109"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、１０８ページ、障害児通所給付費から、日中一時支援事業と、放課後等デイサービスについて伺いたいと思います。この事業には国や都の負担金が出ていると思うのですけれども、どこの部分が増えて、利用料が軽減されるようになるのか伺いたいと思います。それとも、おやつ代や送迎費、保険料は、別の負担が求められてしまうのか、そこを伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"ですので、おやつ代、それから保険料については、負担をしていただくということで考えております。この日中一時支援事業ですけれども、地域生活支援事業の位置づけになっておりますので、その枠組みの中で、都と国から、それぞれ補助金をいただいているものです。","id":"exchange-110"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"１０日通えば２,０００円。代表質問でも取り上げましたけれども、この放課後等デイサービスの、月上限１０日というのを、厚生委員会でも示されましたけれども、基本１０日ということにしていくということで、上限ではなく基本に、言葉が、表現が変えられました。とはいえ、１０日というのは変わらず。この１０日は、何を根拠に決められているのか、伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"他区の中には、日中一時支援事業を持っていないところもございまして、そうした区においては、この放課後等デイサービスにその機能をかぶせているというふうに考えているところです。","id":"exchange-111"},{"speaker":"石田（ち）委員","kind":"質問","question":"本会議での答弁でも、支給決定の基準については、習い事や塾は週２日程度の状況であることから１０日にしているということでありましたが、先ほども課長から療育という言葉が出されているのですけれども、この、塾や習い事と療育というのが、なぜ同じ考えになるのかが、ちょっとわからないのです。これと、この考えと、習い事というのが同じだと、区は考えているのでしょうか。","respondent":"中山障害者福祉課長","answer":"放課後等デイサービスについては、こうした特別支援学校ですとか、あるいは家庭での教育、そういったところでは、なかなか味わえない場所の違い、そういったものの、人とのかかわりということになっていますので、基本的には１０日程度で大丈夫だろうというふうに考えております。","id":"exchange-112"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"学校との連携を図りながら支援を行うと。こうした状況を見ても、品川区の塾や習い事を基準にした利用日数１０日という考え方そのものを変えていくべきではないかと思うのですけれども、いかがでしょうか。そして、やはり障害があってもなくても、放課後の育成・療育に差がないようにしていくことを求めますけれども、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"そうしたいろいろなことを勘案して、一応、基本的には１０日というふうにしているだけで、ただそこは、個別の状況に応じまして、１０日に限らず、日数というのは増やしたりもしておりますし、一方で、放課後等デイサービスの事業所のほうにも、そういった話も伝えつつ、家庭と。","id":"exchange-113"},{"speaker":"若林委員","kind":"質問","question":"４７ページの歳入など、財政についてと、７７ページの土木使用料の区民住宅等について、伺いたいと思います。財政的には、昨日の最終補正予算の審議をさせていただいて、そのときに、繰越金について質疑をさせていただきました。そのときに、繰越金については、平成２７年度の実質収支、イコール繰越金と、これと同額にしているというふうにご答弁があったのですが。","respondent":"秋山財政課長","answer":"ただし、平成２８年度の当初予算の段階では、繰越金の額は確定していませんので、２５億円という当初予算を組んでおいて、平成２８年度の途中に決算が出ますので、決算の時点で実質収支が確定しますので、その額で最終補正と同額にしているです。","id":"exchange-114"},{"speaker":"若林委員","kind":"質問","question":"それが平成２８年度の、翌年度の収入に入って、それが、平成２８年度の決算が終わると、同額の４７億円が繰り越しされて、それはまた平成２９年度の、今年度の予算のところに、決算として４７億円、毎年同額が繰り越されていくという、そういう意味ですか。","respondent":"秋山財政課長","answer":"なので、実質収支額は、その年の決算によって、毎年変わるわけですね。実質収支の額というのは変わりますので、その額が、次年度の繰越額になるという、そういう関係でありますので、４７億円という数字が、毎年毎年、繰り越していくということではございません。","id":"exchange-115"},{"speaker":"若林委員","kind":"確認","question":"同じ額が繰り越されていくわけではないということで、確認をします。続いて、予算の話になるのですが。もう１つ、平成２９年度の予算、区民税の議論はさまざまありました。一方、もう１つの財政調整交付金、これについては、調整三税等、都区でまさに財政調整をして入ってくるお金ですけれども、これについても、区民税と同じような傾向性があるというふうに捉えていいのでしょうか。","respondent":"秋山財政課長","answer":"財政調整交付金は、調整三税の原資が調整三税ですので、１つは固定資産税、それから、あと、もう１つが法人住民税ですので、個人住民税と、全くパラレルな動きをとるというわけではないとは思います。","id":"exchange-116"},{"speaker":"若林委員","kind":"質問・要望","question":"この単年度収支の黒字が続くということは、いかがなものかなという意味で質疑をさせていただきました。これが、品川区にとっての、これから収入、税収が減っていくという傾向も踏まえて、今後もこの単年度収支の黒字を続けるということが、品川区の財政上の健全性を維持するという、大きな方針があるという意味で捉えていいのか、お聞かせをいただきたいと思います。","respondent":"秋山財政課長","answer":"実質収支と単年度収支のお話ですけれども、先ほど、お話をさせていただいた、実質収支。私がご説明をしたのは、実質収支比率の話であったというふうに思っています。２３区の、地方交付税がないという状況の中で、その話をさせていただいたかなと考えています。","id":"exchange-117"},{"speaker":"若林委員","kind":"質問・要望","question":"確かに、単年度収支だけが、健全化の指標の１つではありませんけれども、さっき言いましたように、毎年の１年間の収支、いわゆる決算が出てきて、毎年、翌年度に繰り越されていくお金が、どんどん、現実的に増えていると。続いて、７７ページの区民住宅ですが、まず、これは簡単に、区民住宅の家賃助成の仕組みを確認させてください。こういう仕組みでいいのかどうか、お知らせをいただきたいと思います。","respondent":"今井住宅課長","answer":"歳出のほうには出てまいりません。","id":"exchange-118"},{"speaker":"若林委員","kind":"質問・要望","question":"それは確認をさせていただきました。こういう地域の潤いや、心の豊かさ、こういうことのためにも、ぜひとも住み続けていただきたい。こういった公的な住宅を使って、先ほどの、そういうさまざまな階層の方たちに、活力や活気のために、または地域の潤いのために、住み続けていただくための、品川区の既存の公的な住宅で、今後、どのようなモデルを考えておられるか、ご所見を伺いたいと思います。","respondent":"今井住宅課長","answer":"区民住宅につきましては、今、２３区全体で１,７００ある中で、品川区は７００以上の区民住宅を持っておりますが、借上型については、こちらのほうは、オーナーのほうに着実に返還していくとともに、建設型につきましては、１５年以上、２０年以上たつ住宅もありますので、現在。","id":"exchange-119"},{"speaker":"松澤委員","kind":"確認","question":"５８ページ、１１款分担金及び負担金、１項負担金１目総務負担金、庁舎管理費について。それと、１２１ページ、商店街にぎわい創出事業に関連して、戸越公園駅南口旧イトーヨーカドー跡地についてお聞きしたいと思います。これはおそらく食堂だろうと思うのですけれども、この確認と、この食堂が、どのような経緯で、どのような手順を経て、ここに入ってきたのかについて、お聞きしたいと思います。","respondent":"立川経理課長、米田人事課長","answer":"庁舎管理費負担金の減ですが、こちらは、昨年度に比べまして、いわゆる総合庁舎の工事費が減になったということで、約１億円程度、減になったところです。この間、第二庁舎の２階の部分の全体的なリニューアルに合わせて、事業者も一定程度、年数がたちましたので、運営を区に切りかえた上で、事業者の募集をプロポーザル方式により行い、そこで一番提案の優れている日京クリエイト。","id":"exchange-120"},{"speaker":"松澤委員","kind":"質問","question":"リニューアルをして、運営を区にして、プロポーザルで選んだということですね。関連してお聞きしたいのですけれども、ラヴィアンタワーの完成に合わせて、地域貢献施設として、大井一丁目１５番１に、２棟、組合からいただいた小さなビルがありますけれども、これをいただいた経緯についてお聞きしたいと思います。","respondent":"立川経理課長","answer":"もう１棟、サンピア側ですが、こちらは、商店街から再開発のビルにつながるという所でございまして、いわゆるにぎわいにつながるような、そういう施設を、１・２階の部分には充ててほしいということで、主に店舗ということで、改装を進めたものをいただいたです。","id":"exchange-121"},{"speaker":"松澤委員","kind":"質問","question":"今聞きましたように、立会道路のほうには、経理課の分室と書いてありますよね。こちらのサンピアの２６号線のほうは、社会福祉協議会。ただ、１階に、今言われたように、飲食店が入っているのですよね。区にいただいたということは、区の施設なのですけれども、ここに飲食店が入っている。この経緯についてお聞きしたいと思います。","respondent":"立川経理課長","answer":"３・４階の部分は社会福祉協議会が使っているところなのですけれども、１・２階の部分に店舗を入れてほしいという要望をいただいた上で、寄附として受領したという、そういったことで、現在、店舗として利用しています。","id":"exchange-122"},{"speaker":"松澤委員","kind":"意見","question":"そういう経緯で店舗にしたのはわかるのですけれども、今、食堂ではプロポーザルにしましたという、はっきりした答えが出ているのです。この店舗を入れた理由、どういう形で選んで、この業者が選ばれたのかというのを、そこのところを聞きたいと思います。","respondent":"立川経理課長","answer":"寄附の話があった時点で、既に再開発組合側では、もう店舗の募集を開始しておりまして、それで、コーヒー店、ラーメン店、あと、和食の料理屋、この３つのお店について、もう既にこの時点で推薦をいただいておりまして、それで、区としましては。","id":"exchange-123"},{"speaker":"松澤委員","kind":"質問","question":"そうしますと、もらうときに、この店舗を入れてもらいたいのでと、要するに、くれるほうの側が選んだという形でいいのでしょうか。確か、もらったときには空き家だったというふうに思っています。その後、工事をして店舗ができた。こういう形で、もらうときに、もう店舗が決まっていて、こういう形でもらうというの、おそらくこれ、初めてだと思うのですけれども、初めてということでいいでしょうか。","respondent":"立川経理課長","answer":"既に推薦をいただいておりまして、それで３社から区の方で決定したです。ですから、通常でしたら、公募をかけたりして、いわゆる入居者を決定していくところですけれども、これは、そういった推薦と一緒に、寄附の受領依頼があったですので、こういったことになっているです。","id":"exchange-124"},{"speaker":"松澤委員","kind":"質問","question":"区が、民間の飲食店を入れるというのは、やはりこれ、おかしいですから、どこかでこれは是正していかなければいけないというふうに思っているのですよ。当然のことながら、家賃もとって、民間ですから権利金もとって、きちんと契約もしているのでしょうけれども、その詳細の数字は、こういう予算特別委員会で聞かないですけれども、私は、ここは、この通り、本当の目抜き通りになるのですよね。","respondent":"立川経理課長","answer":"普通財産の貸付につきましては、いわゆる物件の経済的価値を発揮することによって、間接的に行政運営に貢献するという、そういった性質のものですので、立地等を勘案しまして、適切な事業者の選定ということを進めていきたいと考えております。","id":"exchange-125"},{"speaker":"松澤委員","kind":"質問・要望","question":"当然、民間と同じように、複数年契約をしているのでしょうから、もし、ずっとやりたいと言っても、なかなか契約が切れないでしょうけれども、撤退したときには、そういう方向にしていただきたい、そういうふうにお願いをしておきたいというふうに思います。イトーヨーカドー戸越公園店が閉店して、不動産業者に売却するという話が起こり、地域からも、区に買ってほしいという要望がありました。","respondent":"東野まちづくり立体化担当課長","answer":"こういう店舗が入らない状況も想定いたしまして、現在、区がお借りして、事業を行うことも想定していると、検討しているという状況です。同社への店舗の要請につきましては、今後も続けていきたいと考えています。","id":"exchange-126"},{"speaker":"松澤委員","kind":"質問・要望","question":"確かににぎわいづくりということで、あそこで店舗を入れてもらいたいという要望はたくさんあるのですけれども、それに対して、店舗の誘致がうまくいかないから区が借りますよという、こういうことをやったら、どこでも、もしそういうような形で起きた場合には、みんな区が借りるのですか。今の話ですと、もしそういう形にしておいて、商店が手を挙げたら入れるということなのでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"区のスタンスといたしましては、あくまでも店舗を入れていただきたいという姿勢は、続けていきたいと思います。ただし、期限があるようなものですので、それにつきましては、区が借りるということも検討の１つに、今、入れているです。","id":"exchange-127"},{"speaker":"松澤委員","kind":"質問","question":"検討の１つということで、入れるのは、それは政策の問題ですけれども、私はやはり、うまく行かないから区が施設を借りるというような形は、あまり好ましくないかなというふうに思っているものですから、質問させていただきました。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-128"},{"speaker":"須貝委員","kind":"質問","question":"私は、１２９ページ、学校地域連携推進経費についてお聞きしたいと思います。その前に、ちょっと、議会費ということで、一言申し上げたいと思います。そして、先生も参加します。どんどん、いろいろ制度を増やしておりますが、これで、先生方の健康管理は大丈夫なのでしょうか。今でも、休職されている先生方が何人もいるという話を聞いておりますが、実際どうなのでしょうか。お聞かせください。","respondent":"熊谷指導課長","answer":"地域で９年間、義務教育段階の子どもたちを育てていくということで、放課後の地域未来塾もそうですけれども、子どもたちを地域で、学力も含め、育てていくということで、かえって教員の負担感は少なくなると考えております。","id":"exchange-129"},{"speaker":"須貝委員","kind":"質問","question":"この方針を決める、それから段取りを決めるというのは、地域の方々が根本的にやりますが、それをまとめ上げるのは先生方ですよね。地域の方に、では完全に丸投げして、全部やって、学校は一切関知しなくて、皆さんにお助け願いますということですか。もう一度お聞かせください。","respondent":"熊谷指導課長","answer":"ですので、その中に、学識経験者であったり、また保護者、地域住民、そして身近な卒業生、そういった方も入っておりますし、地域の方々も入っておりますので、そういう中で、今後の方向性について検討していくというものです。","id":"exchange-130"},{"speaker":"須貝委員","kind":"質問","question":"済みません。なかなかかみ合わなくて。そうではなくて、その手法を決めますよね。段取り。こういうふうに、今度、コミュニティ・スクールで、こういうイベントをやります。こういう授業をやります。それは、学校の現場ですから、教員がまとめて、そして段取りも教員がある程度決めていきますよね。そうではなかったら、丸投げということですか。もう一度、お聞かせください。","respondent":"熊谷指導課長","answer":"ですので、教員が全て決めていったものを、このコミュニティ・スクールで行っていくというよりは、まずは、校区教育協働委員会は校長のブレーンですので、その中で検討したことを、学校支援地域本部にお手伝いいただくという形です。","id":"exchange-131"},{"speaker":"須貝委員","kind":"質問","question":"済みません。なかなか答えていただけないのですが。地域の人が、では、全部こういう書類をつくって、やれますか、という話です。私は違うと思います。こんなことをまた増やしていったら、ベテランの教員が来なくなるのではないですか。やはり先生は、もっと学校でしっかり子どもと向き合って、やはり会話できる、話ができる、子どもの顔色が見られる時間というのが、私は必要だと思うのですが、違うのですか。","respondent":"熊谷指導課長","answer":"ですので、反対に、ミシンのお手伝いが欲しいのだけれども、ですとか、地域めぐりの補助が欲しいのだけれども、ですとか、そういった要望に関して、今までは教員が、もしくは副校長がコーディネートしてきたものについて、コーディネーターが間に入って。","id":"exchange-132"},{"speaker":"須貝委員","kind":"質問","question":"それは授業外ですから。それから、今、学習指導の話もありました。だから、先生というのは、そこで楽になるという、今、おっしゃっていますけれども、それをフォローしなければいけないのではないですか。そういうような姿を見ていたら、ますますベテランの、いい先生と言っていいかどうかわからないけれども、そういう方が来てもらえなくなるのではないかと、すごく心配するのですが、どうでしょうか。","respondent":"熊谷指導課長","answer":"ですので、まず、この品川コミュニティ・スクールをやっていく中で、地域の方のお力添えもいただきながら、また地域にも貢献していく子どもたちを育てていくことができると考えております。","id":"exchange-133"},{"speaker":"須貝委員","kind":"質問","question":"大丈夫なのですか。学校教員の超過勤務について、どう考えているのでしょうか。でも、超過勤務は、申し訳ないけれども、減っていないのではないですか。私にはそう見えます。それすらできないのに、さらにこれをやっていたら、本当に、教員の皆さんの超過勤務ということを考えたら、もうストレスから何から、先生、まいってしまうのではないですか。この品川区から出ていきたくなってしまうのではないですか。","respondent":"熊谷指導課長","answer":"どちらにしましても、教育内容、性教育ですとか法教育、さまざまありますけれども、そういったものは、どこの区市町村、教育委員会でも、子どもたちのためにということで、各学校で行われているところですが、そういったものを精査して、またさらに、地域の方の力も借りながら。","id":"exchange-134"},{"speaker":"須貝委員","kind":"質問・要望","question":"今までも、いろいろ先生方の問題が、疲れている云々で、ストレスだって問題になっています。でも、実際、仕事は減っていない。教員に関しては、超過勤務という問題は、労働基準監督署に権限はありません。だから、残業手当も出ません。４％の調整率だけでしょう。そのまま放っておいて、ああ、３年たちました。そして、子どもを指導できるような、そういう仕組みを、早くつくっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-135"},{"speaker":"大倉委員","kind":"質問","question":"お願いいたします。１２７ページ、シェアサイクル事業について、１３６ページ、ふるさと納税について、伺います。シェアサイクル事業なのですが、午前中もほかの委員から質問がありましたが、まずこのシェアサイクル事業について、都の補助金２分の１となっておりますが、この性質について、どういったものなのか、補助金についてのご説明をしていただければと思います。","respondent":"安井土木管理課長、黒田税務課長","answer":"サイクルポートであるとか、あるいは自転車、大体２００台ぐらいを予定しているのですが、それとか、自転車を入れるラック等のハード部分等に補助金があるというようなところで、そういったものについての経費と。そういった中で、区といたしましては、品川区を応援していただける方には応援していただきたいということで、平成２８年６月から、クレジットカードを使った寄附の募集ということで。","id":"exchange-136"},{"speaker":"大倉委員","kind":"質問","question":"シェアサイクル、ハード・ソフト面という部分で、今後、これから予算のほう、プレスのほうでもありますが、対象エリア、品川区役所から海側についてやっていくということで、まだこれから業者については決めていって、今後ずっと、２０２０年、オリンピック・パラリンピック開催の交通需要の対策の１つとしても活用していくということで、書いてありますので。","respondent":"安井土木管理課長、柏原企画調整課長","answer":"シェアサイクルですけれども、現在、スマホと、それからクレジットカードで現金決済をするというような形で、システム化されていて、誰でも使えるというようなことが、これを利用される場合に必要なことであろうということで。委員からご紹介いただきました、福井県坂井市の事例ですけれども、こちらのほうは、返礼品によらず、そういった事業に対しての寄附というところで取り組んでいるという面につきましては、この内容につきましては。","id":"exchange-137"},{"speaker":"大倉委員","kind":"質問・要望","question":"シェアサイクルですが、わかりました。自転車への広告については大丈夫だというようなお話もある中で、どういった、採算性とか収入という部分を考えているか、教えていただきたいと思います。指定寄附金でも、昨日ちょっと伺ったのが、団体が多かったということですが、個人の方にも、しっかり寄附をしやすい環境づくりという部分で、取組みを進めていっていただきたいと思います。","respondent":"安井土木管理課長、黒田税務課長","answer":"今、シェアサイクル、これからもしばらくやっていくということの前提のためには、運営経費のほうが、なるべく区の負担が少ないということで、ランニングコストのほうを十分に考えなければいけないというふうに思っております。まちかど観光案内所でありますとか、観光協会が発行しておりますしながわみやげのパンフレットにも、返礼品の一覧を紹介していますが、使い道といった点では、平成２７年度１０月からふるさと納税を始めた際に。","id":"exchange-138"},{"speaker":"大倉委員","kind":"質問","question":"わかりました。シェアサイクル、しっかりと安定的な運営という部分でお願いしたいと思います。そうすると、自転車が今後増えていくと言う中で、まず、安全な自転車レーンの交通について、少し伺いたいのですが、国土交通省、警視庁のほうで、安全で快適な自転車利用環境創出ガイドラインというのも出ました。スピードの出し過ぎというのがあると考えています。ふるさと納税は、また改めて伺います。","respondent":"多並道路課長","answer":"やはり自転車レーン、また、自転車走行空間を整備する際は、安全対策、ハード面でできる部分の、限られた部分もありますけれども、よく警視庁とも連携して、また、東京都、国、いろいろな事例を踏まえながら、より安全対策が図れるような、個別具体的な中で。","id":"exchange-139"},{"speaker":"大倉委員","kind":"意見","question":"私もちょっと聞いたら、車が出て行くときに、坂だと、右見て、左見て、行こうと思ったときに、また右を気にして出て行くと、自転車は早いので、左からぱっと出てくるという部分で、そういった部分もありますので、坂というところも気をつけていただきながら、取組みを進めていっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-140"},{"speaker":"安藤委員","kind":"質問","question":"８０ページの情報公開手数料、１３４ページの旧第一日野小学校跡地の財産貸付収入について伺います。情報公開手数料ですが、区では制度をつくった際には無料でしたが、１９９７年に有料化し、１件につき３００円の手数料、それにコピー代をとっています。質問ですが、都の無料化の動きをどう考えているのか、伺います。品川区も手数料を無料にすべきだと思いますけれども、いかがでしょうか。","respondent":"中元広報広聴課長","answer":"区といたしましては、今までの考えを変えるつもりはございません。現状のままで運用していくと言うところで考えております。","id":"exchange-141"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこで私、区が今までおっしゃっていた２２７条の手数料の考え方を調べてみました。伺いますが、区民が区政への参加を求めて情報公開請求することは、請求者の個人的な利益のために行われていることなのでしょうか。ご答弁ください。私は、区民が情報公開を行うことは、区政参加を進め、ひいては区政の発展にもつながるという、個人の利益を超えたものだと思いますけれども、いかがでしょうか。","respondent":"中元広報広聴課長","answer":"政策的なものに関しましても、ホームページ等でお出しできる情報は、丁寧に説明をしていくということで、対応していきたいと思っているところです。","id":"exchange-142"},{"speaker":"安藤委員","kind":"質問","question":"一部の営業目的ですとか、濫用とかというのは、それは防ぐ手立てで防げると思うのですね。そこが大事な点だと思います。情報公開請求、区政に参加するため、区政の情報を、自ら能動的に得ようとする行為を保証するということは、私は、民主主義や地方自治をさらに発展させていく上では、不可欠な基盤整備で、大変大事だと思うのですが、区にはそういう認識はないのでしょうか。伺いたいと思います。","respondent":"中元広報広聴課長","answer":"そういう認識は、もちろん一方ではありますが、ただやはり、情報公開に関しましては、それなりの事務の手間もかかっているものですので、その部分につきましては、やはり受益者負担ということで、手数料を頂戴しているという考え方で、現在、いるものです。","id":"exchange-143"},{"speaker":"安藤委員","kind":"質問・要望","question":"この貸付契約を報告した２０１２年６月２７日の行革特別委員会で、ずるずる延びるのではないですかという質問があったのに対して、当時の行財政改革担当課長も、「建替え時期が、平成２８年度めどの着工といった時期が明確化されたこと、こういったことも、要望書の中にございましたので、区としても貸付に向けて、ＴＯＣとも協議を進めてまいった」と言っております。伺いたいと思います。","respondent":"柏原企画調整課長","answer":"今回の、今、貸付をしている部分と、その暫定活用の部分では、契約上は別物というふうに捉えていただきたいと思います。平成２４年９月からのものが現契約のものでございまして、その前のものは、暫定の契約ということで、別ということでご認識していただきたいと思います。","id":"exchange-144"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと、何を区としてＴＯＣに求めているのかわからないのですね。遺憾という言葉が出ましたけれども、はっきりと返還を求めていくということなのかどうか。何をＴＯＣにお話をしているのか、伺いたいと思います。","respondent":"柏原企画調整課長","answer":"ＴＯＣのほうからも、先ほど申しましたように、オリンピック・パラリンピック等々に向けての需要の変更があったというふうなお話があったというものでありますので、引き続き、今後の事業展開について、しっかりした方針と言いますか、出るような形で。","id":"exchange-145"},{"speaker":"安藤委員","kind":"質問","question":"建替えの見通しもないと。契約期間内に建替え完了するのですか。伺いたいと思います。前の暫定の貸付と合わせて１０年ですからね。これ、事業が完了する見通しがなくっているわけですから、速やかに契約を終了し、返してもらい、認可保育園や特養、防災広場など、切実な区民要求実現にこそ充てるべきだと思いますが、いかがでしょう。これは、当初の貸付の目的とも大きく違っているのではないか、伺います。","respondent":"柏原企画調整課長","answer":"そもそも、先ほど来申し上げていますＴＯＣの貸付につきましては、先ほども申し上げたように、本体の建替えによって、事業の継続の部分、地域経済の活性化がいかに継続できるかというところで、お貸ししたです。","id":"exchange-146"},{"speaker":"安藤委員","kind":"質問・要望","question":"学校跡地は、もともと地域の思いが詰まった場所であり、区民の貴重な共有財産です。一企業の便宜を図るＴＯＣへの貸付はやめ、住民要望のための活用を強く求めたいと思います。最後にもう１回お伺いしますが、これ、ＴＯＣビルの建替えが貸付の最大の理由としていますが、この建替え、契約期間内に終わるのですか。それだけお聞かせください。","respondent":"柏原企画調整課長","answer":"先ほど申しましたように、ＴＯＣ側の事業の変更がありましたので、それに関しましては、今、終わるように交渉しながら進めてもらうということで、強く申し出ているところです。","id":"exchange-147"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私は、５９ページ、総務費負担金です。それから、１０８ページの、民生・児童委員協力員活動費の２点でお伺いします。先に５９ページのほうですけれども、先ほどもちょっと出ましたけれども、角度は違いますが、職員互助会のほうに、平成２８年度予算では含まれていたものが、こういう形で出された形になっておりますけれども、その辺の理由をまずお聞かせいただきたいと思います。これを教えてください。","respondent":"米田人事課長、大串福祉計画課長","answer":"この１年間、昨年２月のオープン以来、日京クリエイトの事業運営についての評価ですけれども、今般も、テレビ・新聞などのメディアに、「品川めし」というメニューが取り上げられたり、あるいはフロアのところに。２２１ページのほうは民生委員経費ということで、定員ベースで計算しています。したがいまして、そちらの定員ベースで計算しております４,８００万円の経費、そちらの中には、この協力員の経費も入っているといった形です。","id":"exchange-148"},{"speaker":"たけうち委員","kind":"提案","question":"食堂のほう、理由はわかりました。そういった中で、民生委員さんと、ちょっと違うのですけれども、民生委員の経験者の方ですから、民生委員さんとちょっと違う、例えば、具体的に言うと、研修旅行なんかは行かれないらしいのですけれども、別々のお金が出ているらしいのですけれども、そういうところの違いみたいなものもあるらしいのですが、そういうところをどう考えてらっしゃるか、教えてください。","respondent":"米田人事課長、川島健康課長、大串福祉計画課長","answer":"健康課長のほうからもお話があると思いますが、SHINAGAWA“もったいない”推進店ですとか、ＴＦＴメニューの提供、カロリー・塩分表示。塩分を少なくする、それからカロリーを少なくする、カロリー表示、塩分表示もしておりますし、健康づくりの観点から、引き続き人事課のほうとも情報交換。我々のほうといたしましては、なるべく、こういった形での協力員ということではなくて、正規の民生委員さんが配属されるように、当該の町会。","id":"exchange-149"},{"speaker":"たけうち委員","kind":"質問・要望","question":"もちろん、一番いいのは、課長がおっしゃったようにきちんとした民生委員が生まれるのが一番いいのですけれども、そうではない場合に、こういう形でフォローしていただいている、やっている仕事はほとんど同じなわけですから、そういうところで疎外感がないような取組みを今後またぜひ検討していただきたいと思いますので、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-150"},{"speaker":"鈴木（真）委員","kind":"確認","question":"２８番目の質問者なので、なるべく項目が重ならないように質問していきたいと思います。８８ページ、国庫負担金、それから１０８ページの都負担金で、生活保護費関係。それから、９２ページで、国庫補助金の中で、地域創生推進交付金。都市型観光プランに絡めて、その辺お伺いしたいと思います。この使い道について、ちょっと確認をしたいと思います。これに絡んでくるかどうか、その辺の答えをお願いします。","respondent":"伊東生活福祉課長、高山子ども育成課長、鈴木文化観光課長","answer":"この８８ページの生活保護費の負担金と言うところですけれども、生活保護費に関しましては、総支出額の４分の３を国が負担し。私のほうからは、１１６ページの子ども・若者自立等支援体制整備事業補助金についてのご説明を申し上げます。地域創生推進交付金の都市型観光プラン推進事業にかかる部分ですが、ご質問にありました、明治維新１５０周年記念関係の事業は、一応。","id":"exchange-151"},{"speaker":"鈴木（真）委員","kind":"質問","question":"わかりました。これは中身の問題ではなくて、やり方、区のホームページからも直に見えたほうが良いのではないでしょうか。ちょっと事業対象外になってしまったので、聞き方、変な形なのですけれども、一応、考え方だけ教えて下さい。例えば、非行という部分も出てくると思うのですけれども、仕事の内容として、その部分が強いと思うのですけれども、保護司というのは、メンバーに入っているのでしょうか。","respondent":"鈴木文化観光課長、伊東生活福祉課長、高山子ども育成課長","answer":"来年度に向けまして、明治維新１５０周年ということで、連携して事業に取り組んでいるものです。ちなみに、自立・廃止というところでは、昨年度の実績で言いますと、５３世帯、そして、一部就労、収入増というところでは３００世帯ということで。それ以外に、先ほど申しました主任児童委員、そして青少年委員の方、そして青少年対策地区委員の方にもかかわっていただく中で。","id":"exchange-152"},{"speaker":"鈴木（真）委員","kind":"質問","question":"生活保護に関しては、自立に向けてやっていただくのと、この前、どこかの質問にもあった塾ですか。それから、若者のほうです。不登校のお子さんなどもこの対象に考えているのではないかと思うのですけれども、その辺をお伺いします。例えば、さっき大学という話も出たと思うのですけれども、サテライト校ですとか、通信教育の学校だとか、その辺の連携というのは、うまくとれているのでしょうか。","respondent":"高山子ども育成課長、伊東生活福祉課長","answer":"連携という部分で言えば、この青少年問題協議会の下部組織であります専門委員会の組織とは別に、その他、意見を申し述べるものというようなことで、関係する庁内の課長級職員。生活保護受給者に関しては、いわゆる塾代の補助という形での支援をしておりますので、効率的になるように、これからもやっていきたいと考えています。","id":"exchange-153"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"補助金ということで、都の補助金についてお伺いさせてもらいます。ちょっと資料を見ていたら、都の施策及び予算に関する要望ということで、８月に区長会で東京都に要望をだしていらっしゃいました。これも要望書に出ていました。都区のあり方検討、４４０項目でしたか。急な、ちょっと全然違うところから出てきた質問なのですが、お答えいただければと思ったのですが、いかがでしょうか。","respondent":"秋山財政課長","answer":"都区のあり方検討につきましては、一定のめどが立っているということで、一時休止的なこともあります。","id":"exchange-154"},{"speaker":"鈴木（真）委員","kind":"質問","question":"例えば、財調協議の中でも、協議はやっていると思うのですけれども、ここに、「都区のあり方」という言葉が出てきたということは、あり方検討会はやっていたから、その辺の部分かなというふうにとってしまったのですが、そういう認識だったのですが、いかがでしょうか。","respondent":"秋山財政課長","answer":"都区のあり方の検討の動向につきまして、私、ちょっと、そこの委員のご指摘の記述について確認はしていないものですので、ちょっとあれですけれども。","id":"exchange-155"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"済みません。資料も何もなくて聞いてしまったのですけれども。去年の８月２５日に、区長会で都に要望したときの項目のまとめの部分に、この言葉が出ていたので。２０項目の中には入っていませんでした。だけど、それがあえてその言葉を出しているというのはどういう意味かなと思ったので、今回ちょっとお聞きしたのですが。改めて、お聞きするようにしますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-156"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/697202?Template=document&Id=1056#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":138228,"voices":404}},{"id":"h29-20170307-10","meetingId":"h29-cm03","date":"2017年3月7日","dateIso":"2017-03-07","committee":"議会運営委員会","time":"午後 ６時３０分～午後 ６時３７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/560108?Template=document&Id=5214#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":2852,"voices":16}}]);
